insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c1122ecd-b505-5602-b383-1e753169570d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 45 year old woman with hypertension takes lisinopril. She attends with a dry cough. What is the SINGLE most appropriate alternative antihypertensive?', 'Dry cough is a class effect of ACE inhibitors (bradykinin accumulation), so switching to another ACE inhibitor will not help. An ARB such as losartan or candesartan blocks the angiotensin II receptor without affecting bradykinin, and is the appropriate switch. Renal function and potassium should be checked after starting.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
