  ('40eaedf4-ca04-5bbb-9c4c-a40dadc3a2d9', 'c1122ecd-b505-5602-b383-1e753169570d', 'A', 'Losartan', true, 0),
  ('9b57b99e-fa41-5081-8b89-32c355493ef6', 'c1122ecd-b505-5602-b383-1e753169570d', 'B', 'Perindopril', false, 1),
  ('cfe84567-a8bc-5d92-8ae5-f1ab56602705', 'c1122ecd-b505-5602-b383-1e753169570d', 'C', 'Ramipril', false, 2),
  ('61073181-f3b7-5879-b0f4-cea39b573f85', 'c1122ecd-b505-5602-b383-1e753169570d', 'D', 'Enalapril', false, 3),
