insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0c9d9eb5-0349-5600-8d80-df80076026ac', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 40 year old woman is found at home in a drowsy state and taken to the Emergency Department. She has had multiple Emergency Department admissions for severe and recurrent depression. Her pulse rate is 108 bpm. She is confused with dilated pupils, dry mucous membranes and a palpable bladder to the umbilicus. Which medication is most likely responsible for her clinical findings?', 'Anticholinergic features (tachycardia, confusion, dilated pupils, dry mucous membranes, urinary retention) after an overdose in a person with depression point to a tricyclic antidepressant such as amitriptyline. TCA overdose can cause seizures and a broad QRS with arrhythmias, which are treated with IV sodium bicarbonate. SSRIs are much safer in overdose.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1d6b1d1c-4bf4-5e3e-8747-c423100ec15c', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'A', 'Amitriptyline', true, 0),
  ('a3efb353-7616-5520-8fef-3ab1d6856fe9', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'B', 'Fluoxetine', false, 1),
  ('261ddc2d-403a-5427-986d-bef20c4b4eb1', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'C', 'Lithium', false, 2),
  ('b6c22a08-0356-5e87-8629-20baa2629d4c', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'D', 'Phenelzine', false, 3),
  ('bfec6f71-fc56-5bea-8ca6-677c9c187f04', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'E', 'Venlafaxine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 54 year old man has swelling of both ankles and is seen in the GP surgery. He has hypertension and takes amlodipine. His pulse rate is 92 bpm and BP 162/90 mmHg. His BMI is 41kg/m². His jugular venous pressure is not raised. Urinalysis shows no abnormality. He has pitting oedema of both ankles. Which is the most likely cause of his ankle swelling?', 'Calcium channel blockers such as amlodipine commonly cause dose-related ankle oedema by dilating precapillary arterioles. A normal JVP and normal urinalysis make heart failure and nephrotic syndrome less likely. Options include reducing the dose, switching drug class, or adding an ACE inhibitor or ARB, which reduces CCB oedema.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('023f85b5-89f5-5a72-b3f9-f45c1a0e613e', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'A', 'Drug side effect', true, 0),
  ('813bf359-cce6-5f72-aece-f959f3a54855', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'B', 'Heart failure', false, 1),
  ('be8b843d-17e6-5062-aa8a-11c10c2a9603', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'C', 'Lymphoedema', false, 2),
  ('4b54a402-003e-5891-9c6d-0b0ebd4f7e96', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'D', 'Nephrotic syndrome', false, 3),
  ('5e7164e3-9ca6-57cc-a94e-0110881d1a75', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'E', 'Obesity', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 73 year old woman has blood taken for her international normalised ratio (INR) and is seen in the GP Surgery. She is taking clarithromycin for a chest infection. She has hypertension, osteoporosis, trigeminal neuralgia and a metallic mitral valve replacement 20 years ago. She takes warfarin, amlodipine, atorvastatin, carbamazepine and sodium risedronate. Investigations: INR 1.3 (2.5) Which medication is most likely to have interacted with warfarin to cause this INR?', 'Carbamazepine is a potent enzyme inducer (CYP450) that increases warfarin metabolism and lowers the INR. Clarithromycin is an enzyme inhibitor that raises the INR. For an INR that has fallen and is harder to control, carbamazepine is the likely culprit. INR should be monitored closely when interacting drugs are started or stopped.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c3b3593e-c87e-58f1-b577-944e8bfc81eb', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'A', 'Amlodipine', false, 0),
  ('829c3d1c-3330-5c65-b8dc-a75c77f89773', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'B', 'Atorvastatin', false, 1),
  ('e2cc597b-ee20-5b0f-a948-d026c3a648eb', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'C', 'Carbamazepine', true, 2),
  ('ccfeefe6-7e69-5837-b884-de7a575d39e7', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'D', 'Clarithromycin', false, 3),
  ('a8c719b2-660e-5664-abb7-6b54bf9f5288', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'E', 'Risedronate sodium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 72 year old man has worsening breathlessness and ankle swelling for 2 months and is seen by his GP. He is diagnosed with heart failure and prescribed ramipril. He is asked to attend for a ‘monitoring blood test’ in 2 weeks. Which is the most appropriate monitoring test to carry out?', 'After starting an ACE inhibitor, renal function and electrolytes (creatinine and potassium) should be checked within 1-2 weeks and after each dose increase, because of the risk of hyperkalaemia and kidney impairment. A rise in creatinine of up to 30% or potassium up to 6.0 mmol/L may be acceptable.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
