  ('46705aef-88d7-51f9-be81-e1ae28efbb5a', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'A', 'Brain natriuretic peptide', false, 0),
  ('6627bdb5-c361-51cb-8fd4-5b3e52e2c3b3', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'B', 'Creatine kinase', false, 1),
  ('84ea0c0c-1224-5bbe-a1b6-ffa2352554c1', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'C', 'Full blood count', false, 2),
  ('c8935e21-82d7-532d-88c8-6581b4b3252a', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'D', 'Liver function tests', false, 3),
  ('300c6e22-dcf2-5884-910d-a2ba3c9d656b', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'E', 'Renal function', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 70 year old man with COPD is given high-flow oxygen through a non-rebreather mask by paramedics and becomes increasingly drowsy. An arterial blood gas on 15 L/min oxygen shows pH 7.21, PaCO2 9.4 kPa, PaO2 24 kPa and bicarbonate 27 mmol/L. Which of the following BEST describes this blood gas?', 'The pH is low (acidaemia) and PaCO2 is high, so the acidosis is respiratory. Bicarbonate is only at the upper limit of normal and has not risen enough to offset the CO2, so this is acute and uncompensated, likely from uncontrolled oxygen in a CO2-retainer. Target saturations of 88-92% with controlled oxygen through a Venturi mask. If acidosis persists despite optimal medical treatment, NIV is indicated (pH below 7.35 and PaCO2 above 6.5 kPa).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d708cb0f-eb2b-5b9b-965a-0813554c3936', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'A', 'Acute respiratory acidosis', true, 0),
  ('8395ace6-1c64-5395-a122-dee4c661e2a3', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'B', 'Mixed respiratory and metabolic acidosis', false, 1),
  ('7bf9348d-c50f-54f1-8077-fface3a45843', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'C', 'Metabolic alkalosis', false, 2),
  ('8f3dc252-72c1-5302-a2a0-15e13348b679', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'D', 'Metabolic acidosis with respiratory compensation', false, 3),
  ('e1c6c9f6-3bc9-5a48-8f8d-baae21a4190b', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'E', 'Compensated respiratory acidosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 25 year old man with type 1 diabetes has an arterial blood gas showing pH 7.18, PaCO2 2.9 kPa, bicarbonate 8 mmol/L, sodium 138 mmol/L and chloride 100 mmol/L. What is the anion gap and the BEST description of this acid-base disturbance?', 'Anion gap = Na - (Cl + HCO3) = 138 - (100 + 8) = 30 mmol/L (normal is about 8-14 without potassium). Low pH and low bicarbonate show a metabolic acidosis, and the low PaCO2 is respiratory compensation (Kussmaul breathing). Causes of a high anion gap acidosis include ketoacidosis (here likely DKA), lactic acidosis, renal failure and toxins (methanol, ethylene glycol, salicylates). Normal anion gap acidosis is seen with diarrhoea or renal tubular acidosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bb1fe868-0d58-5e5d-8cdf-021d067c49cf', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'A', 'Anion gap 8 mmol/L; mixed respiratory and metabolic alkalosis', false, 0),
  ('f24a8f16-92ab-5263-b26d-6a600a0372cc', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'B', 'Anion gap 12 mmol/L; normal anion gap metabolic acidosis', false, 1),
  ('789e9540-ea9c-5d8a-bd5c-4b597ad54bed', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'C', 'Anion gap 38 mmol/L; metabolic alkalosis', false, 2),
  ('c5ed9926-6d79-5c7b-96f5-b460cdf28aa9', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'D', 'Anion gap 30 mmol/L; high anion gap metabolic acidosis with respiratory compensation', true, 3),
  ('b56e1180-da2b-590a-9aa0-94f1f579a14e', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'E', 'Anion gap 30 mmol/L; respiratory acidosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b02c4f7f-e009-50b9-91d4-06bc608000ae', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 62 year old woman in the Emergency Department with sepsis from a urinary source has received 30 mL/kg of IV crystalloid. Her mean arterial pressure remains 55 mmHg and lactate is 5.1 mmol/L. She has had IV antibiotics. What is the SINGLE most appropriate next step?', 'Persistent hypotension (MAP below 65 mmHg) and a raised lactate despite adequate fluid resuscitation means septic shock. She needs critical care referral for vasopressors (noradrenaline first-line), targeting a MAP of 65 mmHg or above, with arterial line monitoring. Too much fluid causes oedema and harm. IV hydrocortisone is considered if vasopressor needs keep rising.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cdb6ea9d-a4aa-5b84-ac52-a9903e998f74', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'A', 'Continue fluids indefinitely until BP normalises', false, 0),
  ('3c040307-5de4-55fa-8d89-54530479f5ab', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'B', 'IV hydrocortisone as first-line', false, 1),
  ('1bdf8d91-9d42-50c2-a34b-9bbd579cee28', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'C', 'Stop antibiotics and wait for cultures', false, 2),
  ('2e72cfcc-3695-5edc-ba99-7a47b0ba0f3a', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'D', 'Refer to critical care for vasopressor support (noradrenaline)', true, 3),
  ('c53f63e9-0bfa-5758-bfcb-d52314d9a534', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'E', 'Oral fluids and ward observation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 68 year old man is in ICU on a ventilator for pneumonia. His PaO2/FiO2 ratio is 12 kPa (90 mmHg), with bilateral infiltrates on chest X-ray not explained by heart failure. What is the SINGLE most appropriate ventilation strategy?', 'Acute respiratory distress syndrome (Berlin definition) is acute onset, bilateral opacities and PaO2/FiO2 300 mmHg or below with PEEP of 5 or more, not fully explained by heart failure. A ratio under 100 is severe. Management is lung-protective ventilation (low tidal volumes, plateau pressure under 30 cmH2O), appropriate PEEP, prone positioning for severe ARDS, conservative fluids and treating the cause.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2ca17ba9-5fde-563d-8af3-e351ab82cb3e', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'A', 'Bronchoscopy for all', false, 0),
  ('d0b0e7ea-0f4b-576e-bc63-da2c655b9dea', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'B', 'Diuretics only', false, 1),
  ('186802a5-2dec-5971-82f7-b1c30f700136', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'C', 'High tidal volume ventilation (12 mL/kg)', false, 2),
  ('c5df7e54-1d19-565e-a239-e5d8bfb0fc98', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'D', 'Zero PEEP', false, 3),
  ('c1899603-6a50-5870-8f9e-8f96593acd99', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'E', 'Lung-protective ventilation (low tidal volume 6 mL/kg ideal body weight) with prone positioning', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 55 year old woman is admitted to ICU with septic shock. After 30 mL/kg fluid, her MAP is 58 mmHg despite noradrenaline. What is the MAP target for vasopressor therapy?', 'The Surviving Sepsis Campaign recommends an initial MAP target of 65 mmHg with noradrenaline as the first-line vasopressor. Vasopressin is added if MAP stays inadequate, and adrenaline can also be considered. IV hydrocortisone is considered for ongoing vasopressor requirement. Lactate is repeated to guide resuscitation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('220ae973-fc2b-5484-8742-5bbedaff2531', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'A', 'No target', false, 0),
  ('d7698df6-aedb-5423-8ba1-4b0fb520609c', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'B', '50 mmHg', false, 1),
  ('563ae475-5b93-5053-8310-e98fd18185b8', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'C', '80 mmHg', false, 2),
  ('234f97a0-7f25-557d-b2bc-dece871476c9', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'D', '100 mmHg', false, 3),
  ('96e72c50-0def-5223-8b1f-1ce721ecea81', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'E', '65 mmHg', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6f02ffec-70ff-5e7f-995a-500699780d27', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 75 year old man with an acute kidney injury and sepsis has had his NEWS2 score increase from 3 to 7 over 4 hours. According to NEWS2 guidance, what is the SINGLE most appropriate response?', 'NEWS2: a score of 0-4 needs routine or ward-based response, 5-6 (or 3 in one parameter) an urgent response (ward clinician within 1 hour), and 7 or more an emergency response with a critical care outreach team and continuous monitoring. NEWS2 aggregates respiratory rate, saturations, oxygen use, temperature, systolic BP, heart rate and consciousness (including new confusion).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7332a81f-1a69-528e-bb79-02755b9b831a', '6f02ffec-70ff-5e7f-995a-500699780d27', 'A', 'Routine ward review tomorrow', false, 0),
  ('85503187-3ac2-5b58-89cd-981bd21d8d3a', '6f02ffec-70ff-5e7f-995a-500699780d27', 'B', 'Urgent (emergency) response with a clinical team competent in critical care, with at least hourly observations', true, 1),
  ('fb7a28e7-741d-53af-8046-0a6ada1c9b93', '6f02ffec-70ff-5e7f-995a-500699780d27', 'C', 'Continue 12-hourly observations', false, 2),
  ('a2db1c26-01fd-5886-844b-f43031627866', '6f02ffec-70ff-5e7f-995a-500699780d27', 'D', 'Increase observations to 4-hourly only', false, 3),
  ('958a8eef-5324-5463-ae51-93c69d86cd61', '6f02ffec-70ff-5e7f-995a-500699780d27', 'E', 'Discharge planning', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a86a001c-ea53-588d-b83a-e0240dffbcb6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 30 year old man has been intubated for a head injury. His GCS before intubation was E1 V2 M4. What was his GCS score and what does it indicate?', 'GCS = eyes (1-4) + verbal (1-5) + motor (1-6). Here 1 + 2 + 4 = 7. Severe head injury is GCS 8 or below, moderate 9-12 and mild 13-15. A GCS of 8 or below usually needs airway protection by intubation. Motor scores: 4 is withdrawal, 3 abnormal flexion (decorticate) and 2 extension (decerebrate).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bcaf00e5-8f8f-57d7-97f4-aad8ef2f55a5', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'A', '5 — mild head injury', false, 0),
  ('933ae18b-0bb0-516e-9e52-021441a2b9d8', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'B', '7 — severe head injury', true, 1),
  ('b910977d-ca34-562f-807d-bd1ad52f2df0', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'C', '7 — mild head injury', false, 2),
  ('99dbfb85-2943-5a10-bca4-2fbdc732d6fc', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'D', '9 — moderate head injury', false, 3),
  ('93268355-2e0e-5739-a435-b80864151df8', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'E', '11 — moderate head injury', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 42 year old woman in ICU after a road traffic accident has a head injury with intracranial pressure of 30 mmHg. Her MAP is 80 mmHg. What is her cerebral perfusion pressure?', 'Cerebral perfusion pressure = MAP - ICP = 80 - 30 = 50 mmHg. The target CPP in traumatic brain injury is usually 60-70 mmHg. Raised ICP is managed by head-up positioning (30 degrees), sedation, normocapnia, osmotherapy (mannitol or hypertonic saline) and neurosurgical intervention. Cushing''s triad (hypertension, bradycardia, irregular breathing) is a late sign of raised ICP.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('163c10f7-3dce-55fc-ac89-df720f215974', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'A', '2.7 mmHg', false, 0),
  ('ade56a8b-2c72-5bd2-a49d-faedc761adbd', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'B', '30 mmHg', false, 1),
  ('031f9ed5-0078-5593-845e-e515655657fb', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'C', '50 mmHg', true, 2),
  ('71b45d33-87b4-5ff7-8ae6-4812c908110f', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'D', '80 mmHg', false, 3),
  ('afb5dfa1-c0c9-5d56-be88-db62ea182747', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'E', '110 mmHg', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 60 year old man in ICU has had a temperature of 38.6°C, new purulent tracheal secretions and a new infiltrate on chest X-ray 4 days after intubation. What is the SINGLE most likely diagnosis?', 'VAP occurs more than 48 hours after intubation. Organisms include Pseudomonas, MRSA and Gram-negative bacteria. Prevention bundles include head-of-bed elevation to 30-45 degrees, daily sedation holds, subglottic suctioning and oral care. Treatment is broad-spectrum antibiotics according to local guidance, narrowed on culture results.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3c4e5640-b2b4-5c21-b438-6645912530d5', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'A', 'Pulmonary embolism', false, 0),
  ('0c8fad95-7c03-5f60-a71d-e06301b7b4b0', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'B', 'Community-acquired pneumonia', false, 1),
  ('2a8d9b0f-b346-5ee8-bbca-10a819c65d92', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'C', 'Ventilator-associated pneumonia', true, 2),
  ('10d484b3-8f1f-5601-ae4f-7807d32ff1b4', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'D', 'Aspiration of gastric contents on admission', false, 3),
  ('879cf11a-c141-57d2-9f2c-641a5665f86b', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'E', 'Atelectasis only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 22 year old man has been brought in after a head injury. CT shows a large haemorrhage and he has fixed dilated pupils, no cough or gag reflex and no respiratory effort. Brainstem death testing is planned. Which condition must be met before testing?', 'Before brainstem testing, there must be irreversible brain damage of known cause, with reversible causes excluded (depressant drugs, hypothermia, metabolic and endocrine disturbance, neuromuscular blockade). Two sets of tests are done by two senior doctors. They test pupillary, corneal, vestibulo-ocular, gag and cough reflexes, motor response to pain in the cranial nerve distribution, and apnoea. EEG is not required in the UK.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eebe1d73-827e-5c17-9555-1a8b636b43af', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'A', 'Patient must be awake', false, 0),
  ('339e2051-516e-560d-ace4-5184df95b768', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'B', 'Family must agree to organ donation', false, 1),
  ('ee73aead-629c-5ef4-9fa0-f6298039fe94', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'C', 'Exclusion of reversible causes (sedatives, hypothermia, metabolic and endocrine disturbance)', true, 2),
  ('3cc415be-16cf-54d4-8ded-bf37b4a43ab5', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'D', 'The patient must have been in ICU for 1 month', false, 3),
  ('49652ca7-ba67-5816-9728-015eb14aaac1', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'E', 'An EEG must be flat', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7da34d6b-21a4-58ff-8741-016c8868bca2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 70 year old woman is in ICU with severe pancreatitis. She has been nil by mouth for 5 days and cannot eat. Her gut is functioning. What is the SINGLE most appropriate nutritional support?', 'Nutritional support is considered for patients who have eaten little or nothing for over 5 days or are malnourished. Enteral feeding is preferred over parenteral when the gut works, because it maintains gut integrity and reduces infections. In acute pancreatitis, enteral feeding is preferred. Re-feeding syndrome (hypophosphataemia) must be monitored for.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f10b0901-4245-56ed-b729-cf763a9de40f', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'A', 'Nil by mouth until full recovery', false, 0),
  ('173f4993-7508-5cd8-8792-91214b345d30', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'B', 'IV 5% glucose only', false, 1),
  ('51a4cf47-93fb-5b2d-bab6-7cfd3eaaccdb', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'C', 'Enteral feeding via nasogastric (or nasojejunal) tube', true, 2),
  ('bd51382c-4014-583c-9a8f-aff4ea5dc1be', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'D', 'Oral fluids only', false, 3),
  ('b39759a0-d610-5062-a742-0243028ae337', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'E', 'Total parenteral nutrition as first-line', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 62 year old man with chronic alcohol use and low intake for weeks is started on nasogastric feeding. Three days later he has confusion, weakness and heart failure. His phosphate is 0.3 mmol/L. What is the SINGLE most likely diagnosis?', 'Refeeding syndrome happens when feeding restarts after starvation. Insulin release drives phosphate, potassium and magnesium into cells, causing low levels, fluid retention, heart failure, arrhythmias and neurological problems. High-risk patients should start feeding slowly (as low as 5-10 kcal/kg/day), with thiamine and B vitamins, and daily monitoring and replacement of electrolytes (NICE CG32).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('027e0df3-6721-5009-bcc7-7d4e37997ca7', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'A', 'Refeeding syndrome', true, 0),
  ('8dfdbdf9-12cb-5480-8988-bfe5bf2815b2', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'B', 'Delirium tremens', false, 1),
  ('7df24d9a-677c-5969-9923-6f93eb002bc7', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'C', 'Hepatic encephalopathy', false, 2),
  ('590eb2a2-2b53-5ddd-933f-516506ae785f', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'D', 'Hyperkalaemia', false, 3),
  ('b35488ac-3eb7-5186-b060-4bab227f7318', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'E', 'Wernicke''s encephalopathy only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4674da67-c399-5eef-a5fa-ed047d3b00bc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 65 year old man is ventilated in ICU and his ABG shows pH 7.48, PaCO2 3.6 kPa, PaO2 14 kPa and bicarbonate 24 mmol/L. What is the SINGLE most likely acid-base disturbance?', 'High pH with low PaCO2 and normal bicarbonate indicates an uncompensated respiratory alkalosis, here probably from over-ventilation, which is corrected by reducing the minute ventilation. Other causes include anxiety, pain, PE, early sepsis, salicylates and pregnancy. Metabolic alkalosis (high bicarbonate) happens with vomiting, diuretics and hyperaldosteronism.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3f4ec3e2-d816-5ec5-831d-bd633cf49f90', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'A', 'Metabolic alkalosis', false, 0),
  ('f7eeddea-19e8-5cd0-8a9a-176fa9b7d757', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'B', 'Respiratory alkalosis', true, 1),
  ('1875aa6a-41aa-5cdb-a48d-782d8a577351', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'C', 'Normal', false, 2),
  ('b72cc5d3-0d49-504e-9c0f-4630e6881289', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'D', 'Respiratory acidosis', false, 3),
  ('7c220228-26b4-59f1-bcd9-f73cf35cc6ef', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'E', 'Metabolic acidosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b597b7f6-34be-5f23-8687-47fe607f06a0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 42 year old man attends his GP about a mole on his back that his partner noticed has grown over the past 3 months. It measures 9 mm, has irregular edges and contains several shades of brown and black. It occasionally itches. He has fair skin and a history of sunburn. What is the SINGLE most appropriate management?', 'Using the weighted 7-point checklist, change in size, irregular shape and irregular colour score 2 each (major features), and diameter of 7 mm or more and itch (change in sensation) score 1 each. A total of 3 or more prompts a suspected cancer referral for melanoma. Lesions suspected to be melanoma should not be excised in primary care, because complete diagnostic excision with appropriate margins is needed for accurate staging.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9bef387a-5f9d-52f4-a052-83559c7e6c28', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'A', 'Cryotherapy in the GP surgery', false, 0),
  ('cb868f2b-a405-5eab-8c13-b760e053795e', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'B', 'Suspected cancer pathway (two-week wait) referral to dermatology', true, 1),
  ('f05025c0-a3eb-5c00-9986-d872e54b1a46', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'C', 'Excise the lesion in the GP surgery', false, 2),
  ('fcefc566-9beb-5f06-a011-b63b8bcb8a08', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'D', 'Prescribe topical hydrocortisone and review in 2 weeks', false, 3),
  ('94f3fd30-7833-582f-8bfc-71fd9a0d653a', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'E', 'Reassure and review in 6 months', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b3d819cb-bf66-5ad3-af35-d99890b9a353', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 68 year old retired farmer has a slowly growing lesion on the side of his nose for 1 year. It is a pearly, rolled-edge nodule with fine telangiectasia on its surface and a central ulcer. He has no other lesions or lymph nodes. What is the SINGLE most likely diagnosis?', 'A pearly nodule with rolled edges, telangiectasia and central ulceration (''rodent ulcer'') on a sun-exposed site is basal cell carcinoma, the most common skin cancer. It grows slowly and very rarely spreads, so most are referred routinely (not via a suspected cancer pathway) unless there is concern about the site or size. Treatment is surgical excision or Mohs surgery for facial lesions. SCC grows faster and is keratotic, and can metastasise.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('72995f83-3cb1-521b-b20c-b84ef58486f8', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'A', 'Squamous cell carcinoma', false, 0),
  ('43b43f64-5e1d-55cd-95d1-a8cf811b8499', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'B', 'Keratoacanthoma', false, 1),
  ('a83a2cfb-669a-5880-b6f9-c256e6d5cf9f', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'C', 'Seborrhoeic keratosis', false, 2),
  ('6d50121c-e7f2-58d5-972e-e3e9c5e434d6', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'D', 'Basal cell carcinoma', true, 3),
  ('0e7dcb88-0c2b-5eaa-9052-f7c3830e7423', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'E', 'Malignant melanoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cc9215bc-851d-55b3-be43-38a849ebbfe6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 34 year old man has well-demarcated, salmon-pink plaques with silvery scale on his elbows, knees and scalp. His nails show pitting and onycholysis. Emollients have been tried. What is the SINGLE most appropriate first-line topical treatment for his body plaques?', 'This is chronic plaque psoriasis. NICE recommends a potent corticosteroid applied once daily plus a vitamin D analogue (such as calcipotriol) once daily, applied separately at different times of day, for up to 4 weeks for trunk and limb plaques. Phototherapy and systemic agents (such as methotrexate) are for extensive or resistant disease. Nail changes are linked to psoriatic arthritis, so ask about joint symptoms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('887f783c-7d25-567a-aa2e-c0ed6c9640c8', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'A', 'Topical permethrin', false, 0),
  ('a6734ba1-1a40-556e-ac8a-bf56fe43f943', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'B', 'Topical aciclovir', false, 1),
  ('a6799d2e-a1e1-55e8-b818-e796267d14bb', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'C', 'Oral methotrexate as first-line', false, 2),
  ('a99f1771-3ef1-5dbf-8ae7-6676a666812f', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'D', 'Potent topical corticosteroid once daily plus topical vitamin D analogue once daily, applied at different times', true, 3),
  ('d0594c4c-6270-5999-83c2-4f93b83a795f', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'E', 'Topical antifungal cream', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 3 year old girl with known atopic eczema becomes unwell with a fever. Her eczema has rapidly worsened over 24 hours, with clusters of painful punched-out erosions and vesicles on her face and neck. What is the SINGLE most appropriate management?', 'Rapidly worsening painful eczema with clustered punched-out erosions and fever is eczema herpeticum (HSV infection of eczematous skin), a dermatological emergency. It needs urgent same-day referral and oral or IV aciclovir. If the eyes are involved, refer to ophthalmology. Topical steroids should be avoided on affected areas until treatment has started.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('260b19cc-38ab-594a-b516-5c3db0f07f4b', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'A', 'Topical tacrolimus', false, 0),
  ('52ea2cfa-a1d2-53b4-b66e-81f43a787526', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'B', 'Emollients only and review in 1 week', false, 1),
  ('f616591f-18d3-516a-8c98-0229e33e5485', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'C', 'Increase topical steroid potency', false, 2),
  ('7d8d3818-6f02-5b58-9e98-be6b1deb8ecc', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'D', 'Oral flucloxacillin alone', false, 3),
  ('abf95684-37c6-5829-8085-bca92ed90f48', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'E', 'Urgent same-day referral and systemic aciclovir', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c9696926-6859-5b6b-8778-059cb6752fb2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 26 year old woman has 4 weeks of an intensely itchy rash that is worse at night. Her partner has similar symptoms. There are small papules and burrows between her fingers and on the flexor surfaces of her wrists. What is the SINGLE most appropriate treatment?', 'Itch that is worse at night, burrows in the finger webs and wrists, and affected contacts suggest scabies (Sarcoptes scabiei). Permethrin 5% cream is applied to the whole body from the neck down (including the scalp and face in young children and older people), left on for 8-12 hours, and repeated after 7 days. All household and sexual contacts must be treated at the same time, and bedding and clothing washed at 50°C or above. Itch can persist for up to 4 weeks after treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fc3ff886-5de1-540a-8dd1-9d548e0c2344', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'A', 'Oral flucloxacillin', false, 0),
  ('87671ffe-8d87-5493-9fd2-9d867b269320', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'B', 'Potent topical steroid', false, 1),
  ('0748faeb-a033-5a7f-9aa5-f63b45d8e341', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'C', 'Oral antihistamine only', false, 2),
  ('38034e47-48cc-55c1-acbf-08118dbd8e8e', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'D', 'Topical clotrimazole', false, 3),
  ('6c0253ed-5e8c-5627-b9af-a5994179800c', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'E', 'Permethrin 5% cream applied to the whole body, repeated after 7 days, and treat all close contacts at the same time', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('866b7d3d-7455-5b1a-8988-b0c583824417', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 16 year old boy has comedones, inflammatory papules and some pustules on his face. There are no nodules or scars. Over-the-counter treatments have not helped. What is the SINGLE most appropriate first-line treatment?', 'NICE recommends a 12-week course of a fixed topical combination for mild-moderate acne: adapalene/benzoyl peroxide, tretinoin/clindamycin or benzoyl peroxide/clindamycin. Moderate-severe acne can have a topical treatment plus an oral tetracycline (lymecycline or doxycycline) for up to 6 months. Isotretinoin is specialist-only for severe or scarring acne, with a Pregnancy Prevention Programme and mood monitoring.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c648670e-187c-5363-b8cd-f02f089ac96b', '866b7d3d-7455-5b1a-8988-b0c583824417', 'A', 'Oral isotretinoin', false, 0),
  ('bcb242c6-6e6f-512c-97f3-e032613aa304', '866b7d3d-7455-5b1a-8988-b0c583824417', 'B', 'Oral doxycycline alone', false, 1),
  ('e72efd34-e7d8-5744-b484-08f0fc77747a', '866b7d3d-7455-5b1a-8988-b0c583824417', 'C', 'Topical steroid', false, 2),
  ('d93b8b7f-1253-584c-af02-b9b7bb3373a2', '866b7d3d-7455-5b1a-8988-b0c583824417', 'D', 'Oral trimethoprim', false, 3),
  ('6c4952f6-8e1f-525e-acd3-af573bfed820', '866b7d3d-7455-5b1a-8988-b0c583824417', 'E', 'A fixed topical combination (e.g. adapalene with benzoyl peroxide) for 12 weeks', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 42 year old woman has facial flushing, redness, telangiectasia and papules and pustules on her cheeks and nose. Her eyes are gritty. There are no comedones. Hot drinks and alcohol make it worse. What is the SINGLE most likely diagnosis?', 'Rosacea causes facial flushing, persistent redness, telangiectasia and papulopustules without comedones, often with eye involvement and triggers (heat, alcohol, spicy food, sunlight). Treatment is trigger avoidance, sunscreen, topical ivermectin, azelaic acid or metronidazole for papulopustular disease, brimonidine for erythema, and oral doxycycline for moderate-severe disease. Rhinophyma can develop.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('49909d26-1da1-589a-8497-f6713e7945cd', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'A', 'Carcinoid syndrome', false, 0),
  ('2952b4e3-9914-566d-98ae-9b31a9d2f778', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'B', 'Rosacea', true, 1),
  ('644a8e7f-f603-5b24-b6fc-984bbd2be8bb', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'C', 'Seborrhoeic dermatitis', false, 2),
  ('ad6f4af2-c253-5d87-a394-7b89424a5095', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'D', 'Acne vulgaris', false, 3),
  ('93b452a9-bfde-58a0-be83-64663a7dbd30', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'E', 'SLE', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6896da25-7d70-53a4-b40d-bc090b8c6f98', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 30 year old man has had an itchy, scaly rash on his scalp, eyebrows, nasolabial folds and behind his ears for months. It is worse in winter and with stress. What is the SINGLE most appropriate treatment?', 'Seborrhoeic dermatitis is an inflammatory reaction linked to Malassezia yeast, affecting sebaceous areas (scalp, face, chest). Treatment is topical antifungals (ketoconazole shampoo and cream), with short courses of mild topical steroids for flares. Severe or sudden seborrhoeic dermatitis can be a sign of HIV or Parkinson''s disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
