  ('a2c532b3-a20b-5c18-a148-a10de3e5aaf0', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'A', 'Ketoconazole 2% shampoo and cream', true, 0),
  ('d537ab46-bd0b-5649-9ea8-2ffc21682a51', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'B', 'Oral terbinafine', false, 1),
  ('5b8c2612-9f3d-598e-95b4-1e4bafc461a2', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'C', 'Oral isotretinoin', false, 2),
  ('4b263c53-f872-5af5-b7eb-360fa541d91a', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'D', 'Permethrin', false, 3),
  ('8a3f81ca-7e39-5e0b-a9b5-a5e5b3c13333', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'E', 'Potent topical steroid long-term on the face', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('df1572ab-e500-546e-9976-8c6da6bc0b68', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 14 year old girl has had a single large oval scaly pink patch on her trunk for 5 days, followed by smaller oval patches in a ''Christmas tree'' pattern on her back. She is otherwise well. What is the SINGLE most likely diagnosis?', 'Pityriasis rosea starts with a herald patch, followed by smaller oval patches along skin cleavage lines in a ''Christmas tree'' distribution. It may be linked to HHV-6/7. It is self-limiting over 6-12 weeks, and emollients and antihistamines help itch. Secondary syphilis should be considered in sexually active people because it can look similar, including on the palms and soles.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a0f5e320-8d80-53c8-ad91-67ac9ed645e5', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'A', 'Tinea corporis', false, 0),
  ('238d1373-fe0e-5814-948f-4bcf7d595cf4', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'B', 'Pityriasis rosea', true, 1),
  ('3655cf28-69ad-5ba1-9312-1e770c488951', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'C', 'Psoriasis', false, 2),
  ('47a455bc-765c-5d75-9f51-95c0dab9ce19', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'D', 'Secondary syphilis', false, 3),
  ('f18df559-946e-5a20-ba8b-05dc8ffa3b67', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'E', 'Pityriasis versicolor', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b080f3c2-d85f-5389-a135-39465c23eefc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 55 year old man has itchy, purple, flat-topped polygonal papules on the flexor surfaces of his wrists, with fine white lines on top. There is a white lacy pattern on his buccal mucosa. What is the SINGLE most likely diagnosis?', 'Lichen planus causes the 5 Ps: purple, pruritic, polygonal, planar papules and plaques, with Wickham''s striae, often on the flexor wrists, plus oral white lacy lesions. The Koebner phenomenon (lesions at sites of trauma) occurs. It may be drug-induced or linked to hepatitis C. Treatment is potent topical steroids, with oral steroids or phototherapy if widespread.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b7d8c0f0-d515-5902-9c18-3d99dc037a63', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'A', 'Eczema', false, 0),
  ('1fd34408-caed-568b-ac1b-bee3940f59be', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'B', 'Pityriasis rosea', false, 1),
  ('97edb3b5-a6df-5919-951a-9e1a602c292a', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'C', 'Scabies', false, 2),
  ('45732e9d-91df-5400-9f74-b0f0c37ba4f0', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'D', 'Psoriasis', false, 3),
  ('c2a41151-0337-5cce-90a2-fe7bcf00b6f0', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'E', 'Lichen planus', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 72 year old man has tense, fluid-filled blisters on his trunk and limbs on an urticarial background, with severe itching. There are no mouth lesions. Skin biopsy with immunofluorescence shows linear IgG and C3 at the basement membrane. What is the SINGLE most likely diagnosis?', 'Bullous pemphigoid is an autoimmune subepidermal blistering disease of older people, with tense blisters (rarely in the mouth) and linear basement membrane deposits. Pemphigus vulgaris has flaccid intraepidermal blisters that break easily into erosions, often with mouth involvement, a positive Nikolsky sign and intercellular IgG. Pemphigoid is treated with potent topical or oral steroids and doxycycline.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8e10c4ab-39ea-55b8-9635-10716f36249e', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'A', 'Bullous pemphigoid', true, 0),
  ('69b51344-656f-5aa6-afd3-6d0057ca5dd9', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'B', 'Dermatitis herpetiformis', false, 1),
  ('87eb12f0-d716-5ee9-86fc-a9e5136d9a3a', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'C', 'Stevens-Johnson syndrome', false, 2),
  ('3264c7c2-c67e-5d05-93f6-dd337a48acf2', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'D', 'Pemphigus vulgaris', false, 3),
  ('1d5c519f-97a8-5170-bf52-14a86d84bef0', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'E', 'Bullous impetigo', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b32355b8-6c4b-590b-bf87-633ac6de817f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 28 year old woman was started on lamotrigine 2 weeks ago. She now has a fever, painful red skin with blistering and peeling over 20% of her body, and ulcers in her mouth, eyes and genitals. What is the SINGLE most likely diagnosis?', 'SJS/TEN is a severe mucocutaneous drug reaction with epidermal necrosis and mucosal involvement (SJS under 10% body surface area, overlap 10-30%, TEN over 30%). Causes include lamotrigine, carbamazepine, allopurinol, sulfonamides and NSAIDs. The drug must be stopped immediately and the patient managed in a burns or ICU setting with ophthalmology input. SCORTEN predicts mortality.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('93c8906c-fb0e-5a49-99d0-e449fc820eff', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'A', 'Drug reaction with eosinophilia (DRESS)', false, 0),
  ('b734ece6-450d-5085-9d45-5749de02d413', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'B', 'Bullous pemphigoid', false, 1),
  ('d516d661-432c-536f-94bc-f057855677f6', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'C', 'Stevens-Johnson syndrome / toxic epidermal necrolysis', true, 2),
  ('0b770398-471f-551f-a0e1-249706fa0cdf', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'D', 'Staphylococcal scalded skin syndrome', false, 3),
  ('43efe737-844b-5f1b-8cc2-a3e4188289a1', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'E', 'Erythema multiforme minor', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('27f4561f-eba8-53ef-9a08-2eebe90834ca', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 7 year old girl has target lesions with a dark centre, pale zone and red outer ring on her hands, feet and limbs. She had cold sores last week. She has no significant mucosal involvement. What is the SINGLE most likely diagnosis?', 'Erythema multiforme causes typical target lesions, often on the extremities, most commonly triggered by HSV and sometimes Mycoplasma or drugs. EM minor has little or no mucosal involvement and is self-limiting. Recurrent HSV-associated EM can be prevented with antiviral prophylaxis. It is distinct from SJS/TEN.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('df41fb73-cf93-5b40-8ff0-6fa55f46687b', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'A', 'Stevens-Johnson syndrome', false, 0),
  ('ce000d06-aef0-50cf-a5c5-1f067a7aa72d', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'B', 'Urticaria', false, 1),
  ('93cf212d-70bb-5342-9b50-41c112f3a51b', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'C', 'Lyme disease', false, 2),
  ('9b8701bd-5932-5061-9997-af78ce7cc3dd', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'D', 'Kawasaki disease', false, 3),
  ('18a0de2d-fe17-5c36-8dda-e830bae0c767', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'E', 'Erythema multiforme', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('135075e9-425e-5a5b-a9d9-85668dd5b962', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 38 year old woman has tender, red-purple nodules on both shins for 2 weeks. She has had a dry cough. Her chest X-ray shows bilateral hilar lymphadenopathy. What is the SINGLE most likely diagnosis?', 'Erythema nodosum is a panniculitis causing tender red nodules on the shins. Causes include streptococcal infection, sarcoidosis, IBD, TB, pregnancy, the COCP and drugs (sulfonamides). Investigation of the cause includes a chest X-ray, throat swab or ASOT, and inflammatory markers. It is usually self-limiting over 6-8 weeks, treated with rest and NSAIDs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('df6fd929-a2a0-51bf-a75a-45afd9c68c68', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'A', 'Cellulitis', false, 0),
  ('5a2b57d8-631f-589f-b38f-93a8b457b621', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'B', 'Insect bites', false, 1),
  ('c45ae1e4-997d-5e52-bc21-8b21fcda6038', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'C', 'DVT', false, 2),
  ('2fdf069b-7006-53c7-a787-84e876963844', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'D', 'Vasculitis', false, 3),
  ('b02fe751-f224-5ae7-828c-a300ea91bf70', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'E', 'Erythema nodosum due to sarcoidosis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7fd79224-89e0-5510-b4a9-c9aa0d864610', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 25 year old man has had several weeks of itchy, red, scaly annular plaques with central clearing and an active scaly edge on his trunk. Skin scrapings show fungal hyphae. What is the SINGLE most appropriate treatment?', 'Tinea corporis (ringworm) is a dermatophyte infection causing annular scaly plaques with central clearing and an advancing edge. Topical antifungals are first-line. Extensive or resistant infection, scalp (tinea capitis) or nail involvement needs oral antifungals (terbinafine or griseofulvin). Steroids alone worsen it (''tinea incognito'').', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('10048a85-27ba-5bce-8d32-c923b36f8d3d', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'A', 'Oral aciclovir', false, 0),
  ('5b36f1c3-96cf-5c9d-9209-7c68f474f52b', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'B', 'Topical antibiotic', false, 1),
  ('9bb39747-d213-5c40-b526-9b6209b6a553', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'C', 'Topical imidazole (e.g. clotrimazole) or terbinafine cream', true, 2),
  ('2178b78b-80eb-5d3c-baca-68d138e57903', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'D', 'Oral isotretinoin', false, 3),
  ('82dbddbf-7a5c-5972-99d8-e1ca0be5b45c', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'E', 'Potent topical steroid alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('06c6c981-1059-59a4-90e7-cccd8be5b97b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 45 year old man has thickened, yellow, crumbly toenails on both big toes for a year. Nail clippings confirm a dermatophyte infection. The nails are painful and he wants treatment. What is the SINGLE most appropriate treatment?', 'Dermatophyte onychomycosis is confirmed by nail clippings before treatment. Oral terbinafine is first-line (6 weeks to 3 months for fingernails, 3-6 months for toenails), with LFTs checked. Itraconazole is the alternative, and is first-line for Candida. Amorolfine nail lacquer may be used for limited superficial disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('39f3f472-df24-5953-9fba-852136b87d22', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'A', 'Topical steroid', false, 0),
  ('e34888c7-be0d-55bd-80e4-fecb87b762fb', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'B', 'Oral terbinafine for 3-6 months (with LFT checks)', true, 1),
  ('5b310e09-bda5-50ec-b2d2-b637b12de797', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'C', 'Nail removal only', false, 2),
  ('c369ae43-b886-5073-a403-319fc28858e5', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'D', 'Oral fluconazole for 1 week', false, 3),
  ('6ab8884f-4170-58b2-9d71-cc004d510e55', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'E', 'Topical clotrimazole for 1 week', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9f95cea1-7119-58ee-8009-865aad4a294f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 32 year old man has well-defined hypopigmented and hyperpigmented scaly macules on his upper trunk, more obvious after sun exposure. A KOH preparation shows a ''spaghetti and meatballs'' appearance. What is the SINGLE most likely diagnosis?', 'Pityriasis versicolor is caused by Malassezia yeast and produces scaly macules that may be hypo- or hyperpigmented, usually on the trunk. Microscopy shows hyphae and spores (''spaghetti and meatballs''). Treatment is ketoconazole shampoo applied to affected skin, or oral itraconazole for extensive disease. Pigment changes may take months to resolve.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f12026a0-42f0-5366-9e69-09e94b156076', '9f95cea1-7119-58ee-8009-865aad4a294f', 'A', 'Tinea corporis', false, 0),
  ('81d78bda-abcc-5878-9ece-bf5b53c524d4', '9f95cea1-7119-58ee-8009-865aad4a294f', 'B', 'Pityriasis versicolor', true, 1),
  ('24ae7358-5afa-5e6c-9563-72f4e3c2796e', '9f95cea1-7119-58ee-8009-865aad4a294f', 'C', 'Vitiligo', false, 2),
  ('3e95915c-fa8c-50bf-9827-0d638f0e0abc', '9f95cea1-7119-58ee-8009-865aad4a294f', 'D', 'Pityriasis rosea', false, 3),
  ('5b9aa5c7-fc10-57c6-8db9-cb446568a0a0', '9f95cea1-7119-58ee-8009-865aad4a294f', 'E', 'Psoriasis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 35 year old woman has had depigmented white patches with sharp margins on her hands and around her mouth for 1 year. Wood''s lamp shows bright white fluorescence. She has hypothyroidism. What is the SINGLE most likely diagnosis?', 'Vitiligo is autoimmune loss of melanocytes, causing depigmented patches, often symmetrical and around the orifices and extremities. It is associated with other autoimmune diseases (thyroid disease, pernicious anaemia, type 1 diabetes, Addison''s). Treatment includes sun protection, camouflage, topical steroids or calcineurin inhibitors, phototherapy and topical ruxolitinib.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a8c4f58e-de96-5ec0-a3ff-66060e27eb72', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'A', 'Post-inflammatory hypopigmentation', false, 0),
  ('cc6e0fd5-42d8-55f9-a876-2a4b10208bcd', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'B', 'Leprosy', false, 1),
  ('cb3f24f1-5a10-5bdd-827d-a3d1e90be3ed', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'C', 'Vitiligo', true, 2),
  ('620f4514-53bf-5a6f-8439-e3cbb9e6d5c6', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'D', 'Albinism', false, 3),
  ('c86b8c9e-ce0e-58ac-9f2e-5e75638c8e3a', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'E', 'Pityriasis versicolor', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 70 year old farmer has a rapidly growing 1.5 cm keratotic nodule with a central keratin plug on the back of his hand, which appeared over 6 weeks. What is the SINGLE most appropriate management?', 'A rapidly growing keratotic nodule in sun-damaged skin may be squamous cell carcinoma or a keratoacanthoma, which is hard to tell apart clinically. NICE recommends a suspected cancer referral for suspected SCC. Treatment is surgical excision. SCC can metastasise. Risk factors include UV exposure, immunosuppression (transplant recipients) and actinic keratoses.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('df752c3e-a2d4-587e-966a-d22170d5919a', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'A', 'Topical steroid', false, 0),
  ('aa0f2de1-9b62-5e34-a36d-131ed3a4862b', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'B', 'Review in 6 months', false, 1),
  ('00c06ba8-181b-5ebf-b0c4-898b023b7b48', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'C', 'Suspected cancer pathway referral (possible squamous cell carcinoma or keratoacanthoma) for excision', true, 2),
  ('bf9b4e87-2971-5401-a79e-bda6092c5fdb', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'D', 'Reassure; likely a wart', false, 3),
  ('0f8eecb2-dd3b-5db2-a3b4-b4b223526b27', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'E', 'Cryotherapy in primary care', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 72 year old man has multiple rough, scaly, red patches on his bald scalp and the backs of his hands. They are not tender, indurated or rapidly growing. What is the SINGLE most likely diagnosis?', 'Actinic (solar) keratoses are premalignant lesions on sun-damaged skin with a small risk of becoming SCC. Treatment options include sun protection, topical 5-fluorouracil, imiquimod, diclofenac gel, cryotherapy and photodynamic therapy. Tenderness, induration, rapid growth or ulceration suggest SCC.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e009b105-a6c3-53a5-b7b8-1f0b78c7e3d4', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'A', 'Seborrhoeic keratoses', false, 0),
  ('4a146ace-3a77-59d6-bfa1-417cef5a8d79', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'B', 'Basal cell carcinoma', false, 1),
  ('faa9ddc6-4373-523e-b9a3-706dd5ea791b', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'C', 'Psoriasis', false, 2),
  ('60d397e2-000c-5156-bc0c-33769c7c5a3d', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'D', 'Actinic keratoses', true, 3),
  ('c719eb23-b072-52a1-89b9-e21e91f32a27', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'E', 'Squamous cell carcinoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('429d7902-3e9a-5501-80a5-00292d12d579', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 68 year old woman has multiple greasy, brown, ''stuck-on'', warty lesions on her back that have been present for years. They do not bleed. What is the SINGLE most appropriate management?', 'Seborrhoeic keratoses are common benign epidermal tumours in older people. They are waxy, warty and look ''stuck-on'', ranging from tan to dark brown. No treatment is needed. They can be removed by cryotherapy or curettage if irritated. A sudden eruption of many (the Leser-Trélat sign) may be associated with malignancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('db8aa844-01c3-51c6-96d8-a6ca86d9fc47', '429d7902-3e9a-5501-80a5-00292d12d579', 'A', 'Reassurance; seborrhoeic keratoses are benign (removal only for cosmetic reasons or if irritated)', true, 0),
  ('4e13345c-9b1a-58f3-a84a-6ea9150413c0', '429d7902-3e9a-5501-80a5-00292d12d579', 'B', 'Suspected cancer referral', false, 1),
  ('b7ad84ed-f2d0-5756-8947-7c1738d14f6e', '429d7902-3e9a-5501-80a5-00292d12d579', 'C', 'Oral antibiotics', false, 2),
  ('debb2f0d-cb44-5b78-9a10-8323c1c09220', '429d7902-3e9a-5501-80a5-00292d12d579', 'D', 'Topical 5-fluorouracil', false, 3),
  ('49527f6c-30c2-51b6-9dab-257f2aa11fac', '429d7902-3e9a-5501-80a5-00292d12d579', 'E', 'Excision of all lesions', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5c3684f0-8ded-5c60-8c2c-83741db5389d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 24 year old man develops itchy, raised, red wheals on his trunk that each last a few hours and then disappear, recurring daily for 8 weeks. He has no angioedema or systemic symptoms. What is the SINGLE most appropriate first-line treatment?', 'Chronic urticaria (more than 6 weeks) is usually spontaneous. First-line treatment is a daily non-sedating H1 antihistamine, increased up to four times the standard dose under specialist advice. Omalizumab is used in refractory cases. Triggers (NSAIDs, stress, heat) should be avoided. Individual wheals lasting over 24 hours or leaving bruising suggest urticarial vasculitis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('18283177-4491-574f-aeef-a0ee8a1985d1', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'A', 'Oral antibiotics', false, 0),
  ('f37225de-2188-5c48-be40-84373de6fe42', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'B', 'Non-sedating H1 antihistamine (e.g. cetirizine), up to 4 times the standard dose if needed', true, 1),
  ('abe29a64-e9e6-5ba9-84a0-6a476e70d834', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'C', 'IM adrenaline', false, 2),
  ('6fd7a458-5b1a-57d5-814b-767d9f872754', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'D', 'Oral prednisolone long-term', false, 3),
  ('04e563c5-bdfb-5044-b2dc-79a003e4dd5b', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'E', 'Topical steroid', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1640f6fa-f6f4-5801-a70e-f79de32711a5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 40 year old woman has a painful, rapidly expanding ulcer on her leg with a purple, undermined edge. It started as a small pustule after a minor injury. She has ulcerative colitis. What is the SINGLE most likely diagnosis?', 'Pyoderma gangrenosum is a neutrophilic dermatosis causing painful ulcers with violaceous undermined edges. It can be triggered by trauma (pathergy). It is associated with IBD, rheumatoid arthritis and haematological malignancy. Debridement can make it worse. Treatment is potent topical or oral steroids, ciclosporin or biologics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('569cb40a-e427-5d9c-b9d3-f8b470d3b35a', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'A', 'Arterial ulcer', false, 0),
  ('200b4a7c-964e-5bca-8b19-c7ce8dfddf76', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'B', 'Erythema nodosum', false, 1),
  ('b961d7dc-5276-5225-a662-b2cd3466e3b0', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'C', 'Pyoderma gangrenosum', true, 2),
  ('e24f9fd3-9554-53d3-9fa7-4cd6ac732140', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'D', 'Venous ulcer', false, 3),
  ('0a58a93d-eb14-58b5-9250-ad8a629aa387', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'E', 'Necrotising fasciitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('12b64963-7473-57fd-9c27-cf9d019bf787', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 55 year old man has a painless, firm, pearly nodule growing over 6 months on his cheek with fine surface blood vessels. A dermatologist confirms nodular basal cell carcinoma. Which treatment offers the HIGHEST cure rate for a facial BCC in a high-risk site?', 'Mohs micrographic surgery examines all margins during the procedure, giving the highest cure rates while sparing tissue. It is preferred for high-risk BCCs (central face, around the eyes, nose and lips, recurrent, ill-defined or morphoeic). Standard surgical excision is used for most other BCCs. Superficial BCCs can be treated with imiquimod or photodynamic therapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5cafa37d-71e3-5b03-a78a-0e38ff9a6d68', '12b64963-7473-57fd-9c27-cf9d019bf787', 'A', 'Cryotherapy', false, 0),
  ('8a852619-4b5d-5522-b945-abeb205d06e4', '12b64963-7473-57fd-9c27-cf9d019bf787', 'B', 'Curettage', false, 1),
  ('919859d3-cc8a-5fbb-becc-ce20a5b4888c', '12b64963-7473-57fd-9c27-cf9d019bf787', 'C', 'Radiotherapy as first-line for all', false, 2),
  ('9eb6d9f5-ace0-5486-b225-89237e78a9ca', '12b64963-7473-57fd-9c27-cf9d019bf787', 'D', 'Topical imiquimod', false, 3),
  ('a51e9560-7f65-53af-a12e-e49c590cd195', '12b64963-7473-57fd-9c27-cf9d019bf787', 'E', 'Mohs micrographic surgery', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 4 year old boy has a few small, pearly, umbilicated papules on his trunk for 2 months. He has atopic eczema. He is otherwise well. What is the SINGLE most appropriate management?', 'Molluscum contagiosum is a poxvirus infection causing umbilicated papules. It is common in children and usually resolves on its own within 18 months. Treatment is not usually needed, though children can keep attending school. Extensive or facial lesions in adults, or in immunocompromised people, warrant further assessment (including HIV in adults).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f5b09a0b-56fe-5747-ba05-8c5d494954a5', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'A', 'Reassurance; molluscum contagiosum usually resolves without treatment within 18 months', true, 0),
  ('baebfe69-285c-5dc7-adbc-ffd907c31af5', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'B', 'Topical steroid on lesions', false, 1),
  ('a581d2a4-0efc-513e-9c68-9fbc07fd6ee8', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'C', 'Oral antibiotics', false, 2),
  ('ca980dda-ef19-51d9-87c5-8a2796944b41', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'D', 'Oral aciclovir', false, 3),
  ('82635635-2cd8-541e-aadc-f343c60199f2', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'E', 'Cryotherapy for all lesions', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ffd96e9b-0c86-538f-8de2-869be987deac', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 6 year old girl has an itchy, red rash with yellow crusting on her face and neck. Her mother has tried non-prescription creams but the rash has continued to spread. She is otherwise well. Her temperature is 36.9°C. She has a yellow crusting on the sores around her mouth. Which is the most likely diagnosis?', 'Honey-coloured (golden-yellow) crusted lesions around the mouth and face in a child are typical of impetigo, usually caused by Staphylococcus aureus. NICE recommends hydrogen peroxide 1% cream for localised non-bullous impetigo, topical fusidic acid if that is unsuitable, and oral flucloxacillin for widespread or bullous disease. The child should stay off school until the lesions have crusted or 48 hours after starting antibiotics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e03d6e35-9a55-55a4-8648-e062f048c369', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'A', 'Chickenpox', false, 0),
  ('0eca1f06-fcbe-52c2-93dd-1f7bdc24f4fb', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'B', 'Fungal infection', false, 1),
  ('e16e404c-ccfe-52dd-bedb-b9dbe981dd6b', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'C', 'Impetigo', true, 2),
  ('f611c866-0c0a-597d-bae9-931cb1e92c4f', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'D', 'Measles', false, 3),
  ('de2fad3a-e2de-5aff-8796-e26cd51b43ae', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'E', 'Psoriasis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 70 year old woman has a red and scaly rash on her trunk and is seen by the district nurses. She is bed bound and receiving treatment of a pressure sore. She has scratch marks on her limbs and trunk and scaling linear lesions on her hands and feet. Which is the most appropriate initial topical treatment for her rash?', 'Widespread itch with scratch marks and burrows (linear scaling lesions) on the hands and feet in a bed-bound patient suggests scabies, including possible crusted scabies. First-line treatment is permethrin 5% cream to the whole body, repeated after 7 days, with treatment of contacts. Crusted scabies may need oral ivermectin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2f041acf-60f2-5090-92c6-b3c5153ecf1a', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'A', 'Clobetasone', false, 0),
  ('0e7dee1b-c73d-5146-b693-0c6db635f0c9', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'B', 'Clotrimazole', false, 1),
  ('d3fd6861-5a2b-5e03-92ce-c442991f0146', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'C', 'Hydrocortisone', false, 2),
  ('bb1f596a-c62c-5822-a95e-7e8d84a700ab', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'D', 'Malathion', false, 3),
  ('7b751b58-02cb-5504-be4d-10de7fd9e345', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'E', 'Permethrin', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('58076c7b-22fc-5552-880e-67845bc71dab', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 23 year old woman has a mole on her leg which has recently changed in size, shape and appearance. She originally noticed it 3 years ago. It is not itchy and does not bleed.  [The image in the original paper shows an asymmetrical lesion with an irregular border and uneven pigmentation.] Which is the most likely diagnosis?', 'A mole that has changed in size, shape and appearance (asymmetry, irregular border, colour variation) suggests malignant melanoma. It needs a suspected cancer referral to dermatology (7-point checklist: change in size, shape or colour each score 2). (The original question shows an image; key features are described here.)', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('db974873-ef44-563c-93b2-987420b98d41', '58076c7b-22fc-5552-880e-67845bc71dab', 'A', 'Compound naevus', false, 0),
  ('e4abf186-a18e-5e70-8deb-f80e6e019022', '58076c7b-22fc-5552-880e-67845bc71dab', 'B', 'Giant naevus', false, 1),
  ('987b19f0-18ea-5da0-8247-39a4283ee54e', '58076c7b-22fc-5552-880e-67845bc71dab', 'C', 'Junctional naevus', false, 2),
  ('eed40612-2c20-5cd5-a564-6c72c8278dee', '58076c7b-22fc-5552-880e-67845bc71dab', 'D', 'Malignant melanoma', true, 3),
  ('f181422c-86f1-5da7-acea-66483ef03977', '58076c7b-22fc-5552-880e-67845bc71dab', 'E', 'Seborrhoeic keratosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f05b39fd-c380-5108-9975-2a33d8c54ad1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 12 year old boy has painful blisters which burst leaving shallow lesions. He has been feeling hot and unwell for last 5 days. He has eczema and uses emollients regularly.  [The image in the original paper shows clusters of punched-out erosions on eczematous skin.] Which is the most likely diagnosis?', 'Painful vesicles that burst into punched-out erosions, with fever and malaise, in a child with eczema is eczema herpeticum (HSV), a dermatological emergency. It needs urgent aciclovir and same-day referral. (The original question shows an image; key features are described here.)', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f0ecc26a-5ca7-5b37-b950-b9c985cef88d', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'A', 'Atopic eczema', false, 0),
  ('34d243c9-684b-5c90-aef4-98de58a57042', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'B', 'Chicken pox', false, 1),
  ('b16cb656-ac8c-5f95-9a64-4274c8cc47e2', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'C', 'Eczema herpeticum', true, 2),
  ('7ed49aeb-01da-57dd-b31d-41356162b251', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'D', 'Impetigo', false, 3),
  ('78dcd742-eb55-5e1f-a247-5e439a1eb47e', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'E', 'Staphylococcal skin infection', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 9 year old boy is brought to the GP surgery with a nosebleed from his right nostril that started 5 minutes ago after he picked his nose. He is well, haemodynamically stable and has no history of bleeding disorders. What is the SINGLE most appropriate first-aid advice?', 'Most nosebleeds come from Little''s area (Kiesselbach''s plexus) on the anterior septum. First aid is to sit up, lean forward and pinch the soft cartilaginous part of the nose firmly for 10-15 minutes without letting go, and spit out blood rather than swallowing it. Tilting the head back makes the patient swallow blood. Cautery is used if a bleeding point is seen once bleeding has settled, and packing is used if first aid fails.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('09bf07d8-b375-5556-9e0e-8253ba71aa8c', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'A', 'Insert a nasal pack immediately', false, 0),
  ('b08287a3-700f-59ee-bdfb-31edeefa209f', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'B', 'Apply silver nitrate cautery immediately', false, 1),
  ('40a28bbd-32d6-5b53-a4b2-edcbc61d282c', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'C', 'Pinch the bony bridge of the nose for 2 minutes', false, 2),
  ('a74e028c-c2df-51fc-95fb-0de5e5c25e67', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'D', 'Lie flat and tilt the head back', false, 3),
  ('10fa9fd9-61b0-52d3-bdbd-dc735857d6b4', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'E', 'Sit forward and firmly pinch the soft part of the nose for 10-15 minutes', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 3 year old girl has had ear pain and a fever of 38.4°C for 1 day. Otoscopy shows a red, bulging left tympanic membrane. She is eating and drinking, is not systemically unwell, and has no ear discharge. She has had no previous ear infections. What is the SINGLE most appropriate management?', 'Acute otitis media is usually self-limiting within 3 days (up to 1 week). NICE recommends analgesia and either no antibiotic or a back-up prescription. Immediate antibiotics (amoxicillin for 5-7 days) are for children who are systemically unwell, at high risk of complications, under 2 years with bilateral infection, or with otorrhoea. Safety-net for signs of mastoiditis or meningitis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('04a90d4f-73f1-534a-9d6c-d7719363b757', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'A', 'Oral amoxicillin for 5 days for all children', false, 0),
  ('9ad9ae56-47f2-53c0-a566-9328560ce165', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'B', 'Grommet insertion', false, 1),
  ('e71d035b-e2e5-5fbb-a1d8-623b5edf169d', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'C', 'Paracetamol or ibuprofen for pain, with no antibiotic or a delayed (back-up) prescription', true, 2),
  ('40d13d92-9e23-5b69-89d2-0b230b5f080c', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'D', 'Topical antibiotic ear drops', false, 3),
  ('4cbd4ca5-90b8-5aac-b54b-96502112adcb', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'E', 'Urgent ENT referral', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('210abd1c-1fec-5e39-8250-d599325cdaa4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 22 year old man has 4 days of a worsening sore throat, now severe on the right side. He has a muffled ''hot potato'' voice, trismus and is drooling. His temperature is 38.7°C. There is swelling above and lateral to the right tonsil, with the uvula deviated to the left. What is the SINGLE most likely diagnosis?', 'Unilateral severe throat pain, trismus, a ''hot potato'' voice, drooling and uvular deviation away from the affected side are typical of quinsy, a complication of tonsillitis. It needs same-day ENT referral for needle aspiration or incision and drainage, IV antibiotics, analgesia and fluids. Tonsillectomy may be considered after recurrent episodes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5b22c929-0538-585d-856b-d27f2fd53ce9', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'A', 'Peritonsillar abscess (quinsy)', true, 0),
  ('f4eb3393-6849-53c5-be67-07efae4dd2cb', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'B', 'Acute epiglottitis', false, 1),
  ('d4654aeb-867f-562c-a9e5-4a4e700f8d16', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'C', 'Retropharyngeal abscess', false, 2),
  ('6976e3fb-ec89-574a-a247-adce6bd98639', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'D', 'Infectious mononucleosis', false, 3),
  ('2427ca71-5473-55e2-a13b-995398887030', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'E', 'Tonsillar carcinoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 58 year old woman has brief episodes of intense spinning lasting under a minute, triggered by turning over in bed or looking up. She has no hearing loss, tinnitus or other neurological symptoms. When her head is turned to the right and she is lowered quickly to lie back, she develops torsional upbeating nystagmus with vertigo after a short delay. What is the SINGLE most appropriate management?', 'Brief vertigo triggered by head position changes, with a positive Dix-Hallpike test (delayed torsional nystagmus that fatigues), is benign paroxysmal positional vertigo, caused by otoconia in the posterior semicircular canal. The Epley particle repositioning manoeuvre is curative in most patients. Vestibular suppressants are not helpful long-term. Betahistine is used for Ménière''s disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e2df411-7ac0-582a-8dfd-1282b163253a', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'A', 'Epley manoeuvre', true, 0),
  ('58b271f1-292c-549d-9297-905dd743f850', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'B', 'Urgent MRI brain', false, 1),
  ('304962dd-f3c1-50ad-8493-b860afc0008e', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'C', 'Betahistine', false, 2),
  ('1ff1af4a-61eb-53e5-8ffe-69edd3da44bf', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'D', 'Oral prednisolone', false, 3),
  ('93b72589-4580-56c2-870e-26e4ebc5e4e5', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'E', 'Long-term prochlorperazine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4c957391-4f42-5d4e-b042-1f9bba09dcec', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 45 year old man noticed this morning that he could not hear on the phone with his left ear. He has tinnitus in that ear but no pain or discharge. Otoscopy is normal. Rinne''s test is positive in both ears and Weber''s test lateralises to the right. What is the SINGLE most appropriate management?', 'Weber lateralising to the right with positive Rinne bilaterally indicates a left sensorineural hearing loss. Sudden onset within 72 hours means sudden sensorineural hearing loss, which needs immediate (same-day) referral to ENT or the emergency department. High-dose oral steroids may improve recovery if started early. An MRI is needed later to exclude a vestibular schwannoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9459ab11-6ffb-55dd-903c-3b4302729e06', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'A', 'Prescribe olive oil ear drops', false, 0),
  ('df80289a-3e86-5584-ba62-1ac5b1e7eba7', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'B', 'Oral amoxicillin', false, 1),
  ('b38241ad-c512-56bd-9cd6-d0293f3d8633', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'C', 'Urgent same-day ENT referral (within 24 hours)', true, 2),
  ('4c880e9a-fbe8-5820-a5fe-c4eda4cef554', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'D', 'Routine audiology referral', false, 3),
  ('853c9f73-e8a5-501d-b24e-61d03f3fc251', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'E', 'Reassure and review in 4 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 45 year old man has had a blocked nose and loss of smell for 6 months, with clear nasal discharge. Examination shows bilateral grey, mobile, insensitive polyps. He has asthma and is sensitive to aspirin. What is the SINGLE most appropriate first-line treatment?', 'Bilateral nasal polyps cause nasal obstruction, rhinorrhoea and anosmia, and are associated with asthma and aspirin sensitivity (Samter''s triad). First-line treatment is intranasal steroids, with a short course of oral steroids for severe disease and surgery (FESS) if medical treatment fails. Unilateral polyps, bleeding or crusting need urgent referral to exclude malignancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b8da25d1-4f49-572a-a203-82dbf927807f', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'A', 'Immediate surgery', false, 0),
  ('f0b4ffe4-65a1-5752-91f9-1f365af256fb', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'B', 'Decongestant spray long-term', false, 1),
  ('6336d972-72e3-50cd-a505-d534c6e10787', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'C', 'Intranasal corticosteroid drops or spray', true, 2),
  ('7050cb13-f830-57fa-a3ea-27c92426a2f4', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'D', 'Antibiotics', false, 3),
  ('ada04086-ad92-54c2-b607-b5a865767819', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'E', 'Antihistamines only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('409b1291-547e-5ff3-83b6-3b34bb6665e6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 34 year old woman has had nasal congestion, facial pain and pressure over her cheeks, and purulent nasal discharge for 5 days after a cold. She is afebrile and otherwise well. What is the SINGLE most appropriate management?', 'NICE: acute sinusitis is usually viral and resolves within 2-3 weeks. For symptoms under 10 days, give self-care advice and no antibiotics. For symptoms over 10 days without improvement, consider a high-dose nasal steroid, with a back-up antibiotic (phenoxymethylpenicillin). Red flags (periorbital swelling, visual change, severe headache) need urgent referral.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ff72bdf6-8176-50ae-b4c1-8c45555e3112', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'A', 'Oral prednisolone', false, 0),
  ('265aca29-3089-5913-817a-138139d3168d', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'B', 'Urgent ENT referral', false, 1),
  ('a5dfff7e-035d-5a53-81a7-935a464e5d67', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'C', 'Self-care (analgesia, saline irrigation); no antibiotics, as most acute sinusitis is viral and self-limiting', true, 2),
  ('3fb3713f-4623-54e8-bbb5-813fdcac1fbd', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'D', 'CT sinuses', false, 3),
  ('03f5ac81-7825-5615-8cb4-5e33edae9fe0', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'E', 'Oral co-amoxiclav for 2 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9097d355-9db5-5ce1-b5f6-60105e5114e8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 72 year old man on aspirin has a nosebleed that has not stopped despite 20 minutes of firm pressure and cautery. He is haemodynamically stable. What is the SINGLE most appropriate next step?', 'If first aid and cautery fail, anterior nasal packing (a nasal tampon or ribbon gauze) is used, followed by admission or ENT review. Posterior bleeds (often in older people with hypertension or anticoagulation) may need posterior packing, sphenopalatine artery ligation or embolisation. Anticoagulation and clotting should be checked. Tranexamic acid can help.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ec1dc0b4-47b8-5479-b379-1969e1587bb3', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'A', 'Posterior packing first', false, 0),
  ('34ab436b-2578-54e1-a8bd-3e9ac643d2da', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'B', 'Anterior nasal packing (e.g. nasal tampon)', true, 1),
  ('f208be6b-3c75-5f92-9435-336d7abea84c', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'C', 'Immediate surgery', false, 2),
  ('d5b6f711-d2ea-5400-be65-93c3efc50a29', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'D', 'Discharge home', false, 3),
  ('29388486-41af-5479-9786-5df9d0f24237', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'E', 'IV vitamin K', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('eb15f895-cba9-5393-b177-8860a0d75f8a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 7 year old boy has had recurrent tonsillitis, with 8 episodes in the past year, each needing time off school. What is the SINGLE most appropriate management?', 'Tonsillectomy (SIGN criteria) is considered for 7 or more well-documented episodes in 1 year, 5 or more a year for 2 years, or 3 or more a year for 3 years, when episodes are disabling. Other indications include quinsy (two episodes) and obstructive sleep apnoea. Post-tonsillectomy haemorrhage, primary (within 24 hours) or secondary (5-10 days, often infection), is a key complication.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7a61fc1f-0a5f-5534-b94b-14517d53571f', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'A', 'Oral steroids', false, 0),
  ('3c48e9d8-5cb0-5732-872a-debcdb28ab7a', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'B', 'Long-term prophylactic antibiotics', false, 1),
  ('808db33d-d9b7-578b-9da2-2aacb1ba5098', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'C', 'Adenoidectomy only', false, 2),
  ('0ad1736f-8a92-5409-9b23-a604a57b3a35', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'D', 'Refer to ENT for consideration of tonsillectomy', true, 3),
  ('0b6393a5-c04b-550a-89b0-cc0613255d54', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'E', 'Reassure', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f288730c-6580-5e5b-9909-775b07559fbb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 3 year old boy has had hearing problems and speech delay. Otoscopy shows dull, retracted tympanic membranes with an air-fluid level, and tympanometry shows a flat (type B) trace bilaterally for 3 months. What is the SINGLE most appropriate management?', 'Otitis media with effusion (glue ear) is common in young children, causing conductive hearing loss. Most cases resolve, so active observation for 3 months is first-line. Persistent bilateral OME with hearing loss affecting speech or education warrants grommets (with or without adenoidectomy) or hearing aids. Children with Down syndrome or cleft palate are more prone to it. Unilateral glue ear in adults needs nasopharyngeal examination to exclude a tumour.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('68ebe70f-dc24-526a-8853-1b7621d8a40b', 'f288730c-6580-5e5b-9909-775b07559fbb', 'A', 'Antihistamines', false, 0),
  ('93b11dfc-445d-5819-8003-a774591fbdd4', 'f288730c-6580-5e5b-9909-775b07559fbb', 'B', 'Refer to ENT for consideration of grommets (ventilation tubes) or hearing aids', true, 1),
  ('9a3e1dce-8dcb-5121-9d5c-4316a6950c03', 'f288730c-6580-5e5b-9909-775b07559fbb', 'C', 'Reassure; no follow-up', false, 2),
  ('66e80b51-7492-5478-8ef3-dcfc7f8ac4c0', 'f288730c-6580-5e5b-9909-775b07559fbb', 'D', 'Oral steroids', false, 3),
  ('407dac7c-24c3-57b0-a380-07e5092369f8', 'f288730c-6580-5e5b-9909-775b07559fbb', 'E', 'Oral antibiotics for 6 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7091283d-be87-56f3-b7cc-1928e2bccbe8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 30 year old woman who swims regularly has had a painful, itchy right ear with discharge for 4 days. The ear canal is red and swollen with debris. Pulling the pinna is painful. The tympanic membrane is intact. What is the SINGLE most appropriate treatment?', 'Otitis externa is inflammation of the ear canal, often from swimming or trauma (cotton buds), commonly caused by Pseudomonas or Staphylococcus aureus. Treatment is topical antibiotic, with or without steroid drops, and keeping the ear dry. A wick may be needed if the canal is swollen shut. Malignant (necrotising) otitis externa in older people with diabetes is an emergency.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cc6817a7-e980-571f-828e-5a0db8a041b1', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'A', 'Oral amoxicillin', false, 0),
  ('1df0ab43-3365-5fd7-96b5-8cc9fc5e7990', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'B', 'Grommet insertion', false, 1),
  ('38dcad83-d2be-5a7c-b272-548dedf856cd', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'C', 'Oral steroids', false, 2),
  ('5b4570e9-1baf-503f-bcec-0e7bab7b84f2', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'D', 'No treatment', false, 3),
  ('8818a037-d8f8-5b04-b278-512170514e24', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'E', 'Topical antibiotic ± steroid ear drops (e.g. ciprofloxacin or neomycin with steroid)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d0ced757-ff1c-50ec-982e-e31980ca69dc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 74 year old man with diabetes has had severe ear pain and discharge for 3 weeks despite topical treatment. There is granulation tissue in the floor of the ear canal and he has a facial nerve palsy. What is the SINGLE most likely diagnosis?', 'Necrotising otitis externa is an invasive Pseudomonas infection spreading to the skull base, in older people with diabetes or the immunocompromised. It causes severe pain, discharge, granulation tissue in the canal and cranial nerve palsies (VII). It needs urgent ENT referral, CT or MRI imaging and prolonged IV antipseudomonal antibiotics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
