  ('57012129-a659-5c42-aa91-7665d8cd6f2b', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'A', 'Necrotising (malignant) otitis externa', true, 0),
  ('b690f7fd-8853-5473-a34e-63c848250d94', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'B', 'Simple otitis externa', false, 1),
  ('7d2e5ec6-7a54-59fd-a38f-2225ed3f206e', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'C', 'Bell''s palsy', false, 2),
  ('21fe3d1c-5acf-5add-8098-b76257f30a11', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'D', 'Acute otitis media', false, 3),
  ('943f510e-214d-5d3a-9545-7c49917baba4', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'E', 'Cholesteatoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4ab7773-d95a-5998-a931-96dde465eaaf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 40 year old woman has had a chronic smelly discharge from her left ear and progressive hearing loss for a year. Otoscopy shows a pearly white mass with debris in the attic (pars flaccida) of the tympanic membrane. What is the SINGLE most likely diagnosis?', 'Cholesteatoma is keratinising squamous epithelium in the middle ear, often in the attic. It causes a foul discharge and conductive hearing loss, and can erode structures (ossicles, facial nerve, labyrinth, intracranial spread). It needs ENT referral for CT and surgical removal (mastoidectomy).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3d4237f8-31be-5a7a-a007-7b28284c9cb0', 'e4ab7773-d95a-5998-a931-96dde465eaaf', 'A', 'Otosclerosis', false, 0),
  ('184cb0f9-2cf7-5b29-bb83-522f1ac34bb8', 'e4ab7773-d95a-5998-a931-96dde465eaaf', 'B', 'Acute otitis media', false, 1),
  ('29161ec6-b33b-5190-9ae0-ff1cd053f8ba', 'e4ab7773-d95a-5998-a931-96dde465eaaf', 'C', 'Otitis externa', false, 2),
  ('7a68b564-915d-51a8-8e45-809d21bf05b8', 'e4ab7773-d95a-5998-a931-96dde465eaaf', 'D', 'Cholesteatoma', true, 3),
  ('99c6bc71-e9e0-566c-ba21-60613af7c53f', 'e4ab7773-d95a-5998-a931-96dde465eaaf', 'E', 'Glue ear', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cd8d4f87-ea3b-5909-984d-088dde5c0fd1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 30 year old woman has had progressive hearing loss in both ears, worse in her left, since her pregnancy. Her mother had similar hearing loss. Otoscopy is normal. Rinne''s test is negative on the left. What is the SINGLE most likely diagnosis?', 'Otosclerosis is fixation of the stapes footplate by abnormal bone, causing progressive conductive hearing loss in young adults. It is often autosomal dominant and can worsen in pregnancy. Otoscopy is normal (sometimes with a pink Schwartze sign). Audiometry shows a Carhart notch. Treatment is hearing aids or stapedectomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
