  ('495faa1b-fe3c-557a-abe9-19c7f52960f5', 'cd8d4f87-ea3b-5909-984d-088dde5c0fd1', 'A', 'Otosclerosis', true, 0),
  ('758143fd-2987-5685-8f5c-d31806aeb01d', 'cd8d4f87-ea3b-5909-984d-088dde5c0fd1', 'B', 'Acoustic neuroma', false, 1),
  ('e08c1295-f0ba-5533-8296-7e51c4ea904c', 'cd8d4f87-ea3b-5909-984d-088dde5c0fd1', 'C', 'Noise-induced hearing loss', false, 2),
  ('60a80635-1f81-5478-8195-514c002c0132', 'cd8d4f87-ea3b-5909-984d-088dde5c0fd1', 'D', 'Presbycusis', false, 3),
  ('c2dc3695-2878-53ec-bb0b-2eb291d0b94f', 'cd8d4f87-ea3b-5909-984d-088dde5c0fd1', 'E', 'Ménière''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('94a183a5-9c85-5e82-a3a2-e2ff39ce4ef2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 72 year old man has had gradual, symmetrical hearing loss for several years, with difficulty hearing in noisy places. Otoscopy is normal. Audiometry shows bilateral high-frequency sensorineural hearing loss. What is the SINGLE most likely diagnosis?', 'Presbycusis is gradual, bilateral, symmetrical sensorineural hearing loss, affecting high frequencies first. Management is hearing aids. Asymmetrical or unilateral sensorineural loss, sudden loss or associated neurological symptoms need investigation (MRI for vestibular schwannoma). Hearing loss is a modifiable risk factor for dementia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('28e66bf3-6856-59c4-834b-81efa2eea988', '94a183a5-9c85-5e82-a3a2-e2ff39ce4ef2', 'A', 'Acoustic neuroma', false, 0),
  ('0b1d8102-bca4-5677-8f2a-51a3941c7852', '94a183a5-9c85-5e82-a3a2-e2ff39ce4ef2', 'B', 'Glue ear', false, 1),
  ('d60cb4bf-dbd7-5b7d-91d4-21b7a78d80f6', '94a183a5-9c85-5e82-a3a2-e2ff39ce4ef2', 'C', 'Presbycusis (age-related hearing loss)', true, 2),
  ('85b7bd49-5b67-5bd2-9cf4-fb2541e4533d', '94a183a5-9c85-5e82-a3a2-e2ff39ce4ef2', 'D', 'Otosclerosis', false, 3),
  ('665cd09d-7726-5275-ae67-5c0c80a7a768', '94a183a5-9c85-5e82-a3a2-e2ff39ce4ef2', 'E', 'Ménière''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b8d68cbf-fef6-59a2-bc80-4a46f19b6c40', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 4 year old boy had acute otitis media last week. He now has a fever, his right ear is pushed forwards and outwards, and there is a tender, red, boggy swelling behind the ear. What is the SINGLE most likely diagnosis?', 'Acute mastoiditis is a complication of acute otitis media in which infection spreads to the mastoid air cells. It causes postauricular swelling, redness and tenderness, with the pinna pushed forwards and outwards, plus fever. It needs urgent ENT admission, IV antibiotics and CT imaging, and sometimes surgical drainage or mastoidectomy. Complications include subperiosteal abscess, meningitis and venous sinus thrombosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('83ca03e4-c605-52cb-8856-bdc4e26407d0', 'b8d68cbf-fef6-59a2-bc80-4a46f19b6c40', 'A', 'Acute mastoiditis', true, 0),
  ('d098f4b3-e1c3-50a6-9c23-08c2aa7a5f4f', 'b8d68cbf-fef6-59a2-bc80-4a46f19b6c40', 'B', 'Parotitis', false, 1),
  ('efc915ec-31c2-5c7c-a74c-a944f6f067c5', 'b8d68cbf-fef6-59a2-bc80-4a46f19b6c40', 'C', 'Cholesteatoma', false, 2),
  ('6c0b02a4-62eb-50f8-b982-8a6f6bca5b31', 'b8d68cbf-fef6-59a2-bc80-4a46f19b6c40', 'D', 'Otitis externa', false, 3),
  ('304a161f-a62e-5416-b5d7-703f4610a61d', 'b8d68cbf-fef6-59a2-bc80-4a46f19b6c40', 'E', 'Postauricular lymphadenitis only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bf02cad6-a0a3-5116-b54a-13154ffbf522', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 2 year old child has had a unilateral, foul-smelling, purulent nasal discharge for 1 week. The other nostril is normal. She is well. What is the SINGLE most likely diagnosis?', 'A unilateral, offensive nasal discharge in a young child is a nasal foreign body until proven otherwise. It can be removed with the ''parent''s kiss'' technique (blowing into the child''s mouth while blocking the other nostril) or by ENT. Button batteries in the nose or ear are emergencies because they cause rapid tissue necrosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('54ff337a-f650-5f93-97bf-c38e4f6450c5', 'bf02cad6-a0a3-5116-b54a-13154ffbf522', 'A', 'Choanal atresia', false, 0),
  ('567308ce-ef04-5ffe-9ec9-76351d3aa533', 'bf02cad6-a0a3-5116-b54a-13154ffbf522', 'B', 'Sinusitis', false, 1),
  ('04b5b452-c116-5332-aefe-4c875a8b8cf7', 'bf02cad6-a0a3-5116-b54a-13154ffbf522', 'C', 'Nasal foreign body', true, 2),
  ('7111bdb3-b8a3-51ad-bea2-6838ed5bea93', 'bf02cad6-a0a3-5116-b54a-13154ffbf522', 'D', 'Allergic rhinitis', false, 3),
  ('101dcd88-d1a7-560f-b9f9-311f82d86603', 'bf02cad6-a0a3-5116-b54a-13154ffbf522', 'E', 'Nasal polyps', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('93af0aec-c298-5c88-9b8e-08697d495663', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 25 year old man has had a sore throat, fever and painful swallowing for 2 days. He has bilateral tonsillar exudate, tender cervical nodes and no cough. His FeverPAIN score is 4. He has no penicillin allergy. What is the SINGLE most appropriate antibiotic?', 'For acute sore throat with a FeverPAIN of 4-5 (or Centor 3-4), NICE recommends considering an immediate antibiotic: phenoxymethylpenicillin for 5-10 days, or clarithromycin or erythromycin in penicillin allergy. Amoxicillin is avoided because it causes a rash if the cause is glandular fever. Most sore throats are viral and self-limiting.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('30f47fd2-cc81-5544-a180-87c3cccbee61', '93af0aec-c298-5c88-9b8e-08697d495663', 'A', 'Ciprofloxacin', false, 0),
  ('92fcb7fd-f64b-55b6-9e50-69717d54972e', '93af0aec-c298-5c88-9b8e-08697d495663', 'B', 'Phenoxymethylpenicillin for 5-10 days', true, 1),
  ('9522f0cf-c17c-58a1-a820-d0a945c4cd76', '93af0aec-c298-5c88-9b8e-08697d495663', 'C', 'Amoxicillin', false, 2),
  ('211d87ab-93aa-5cca-b31a-c9b3346a4f48', '93af0aec-c298-5c88-9b8e-08697d495663', 'D', 'Co-amoxiclav', false, 3),
  ('32198752-86f6-5fb7-8e3b-ea0da5082324', '93af0aec-c298-5c88-9b8e-08697d495663', 'E', 'Doxycycline', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('73512836-34c2-56dd-9ab8-736009086b23', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 35 year old man has had sudden onset vertigo lasting 3 days, with nausea and vomiting, after a flu-like illness. He has no hearing loss or tinnitus. He has horizontal nystagmus, and the head impulse test is abnormal (corrective saccade). He can walk with some unsteadiness. What is the SINGLE most likely diagnosis?', 'Vestibular neuritis (inflammation of the vestibular nerve, often after a virus) causes acute prolonged vertigo without hearing loss. Labyrinthitis also causes hearing loss. An abnormal head impulse test supports a peripheral cause. Short-term vestibular suppressants (prochlorperazine) are used for 3 days at most, followed by vestibular rehabilitation exercises.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('aadfeeaf-faac-54e5-9798-3218dc8176fa', '73512836-34c2-56dd-9ab8-736009086b23', 'A', 'BPPV', false, 0),
  ('47683f0d-72ce-5f51-b86f-e345c2168df6', '73512836-34c2-56dd-9ab8-736009086b23', 'B', 'Vestibular neuritis', true, 1),
  ('7975de1d-3e44-5d6e-b6a8-9db30c6b6990', '73512836-34c2-56dd-9ab8-736009086b23', 'C', 'Posterior circulation stroke', false, 2),
  ('6a4822dc-58b3-5cf2-b283-d28eea62bda5', '73512836-34c2-56dd-9ab8-736009086b23', 'D', 'Labyrinthitis', false, 3),
  ('6b72d156-4328-531e-a020-c79ca23d403d', '73512836-34c2-56dd-9ab8-736009086b23', 'E', 'Ménière''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ccfb8e31-f605-5b15-a2ea-918a90c8caa2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 60 year old man has a 3 cm firm, painless swelling in front of his right ear that has grown slowly over 2 years. Facial nerve function is normal. What is the SINGLE most likely diagnosis?', 'Pleomorphic adenoma is the commonest salivary gland tumour, usually in the parotid. It is benign but can recur or rarely become malignant. Warthin''s tumour is the second commonest, typically in older male smokers and sometimes bilateral. Facial nerve palsy, pain or rapid growth suggests malignancy. Assessment is ultrasound with FNA, and treatment is superficial parotidectomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('02d75512-2ee3-5c1a-8a1d-f51f74f21cea', 'ccfb8e31-f605-5b15-a2ea-918a90c8caa2', 'A', 'Lymphoma', false, 0),
  ('4e295de5-86d5-5338-8392-6c84348d9307', 'ccfb8e31-f605-5b15-a2ea-918a90c8caa2', 'B', 'Warthin''s tumour', false, 1),
  ('7278c6a0-9021-5236-92d6-3801e759a8b7', 'ccfb8e31-f605-5b15-a2ea-918a90c8caa2', 'C', 'Acute parotitis', false, 2),
  ('1894ea3a-3d9d-5d97-8201-b9a23763e419', 'ccfb8e31-f605-5b15-a2ea-918a90c8caa2', 'D', 'Sialolithiasis', false, 3),
  ('99c9ceac-19d7-5078-acd7-e6a9bbbe0660', 'ccfb8e31-f605-5b15-a2ea-918a90c8caa2', 'E', 'Pleomorphic adenoma of the parotid gland', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('988cfc96-8fad-5170-aea6-7eae5c9f9aad', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 45 year old woman has painful swelling under her jaw on the left, which comes on when she eats and settles over an hour. Examination shows a palpable stone in the floor of her mouth. What is the SINGLE most likely diagnosis?', 'Salivary stones most often form in the submandibular gland (because of its alkaline, thicker saliva and uphill duct). They cause painful swelling during meals. Management is hydration, sialogogues (sour sweets), massage and removal of the stone (endoscopic or surgical). Secondary infection (sialadenitis) needs antibiotics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('34eff5ab-f23e-5e74-82e0-bd53861b3127', '988cfc96-8fad-5170-aea6-7eae5c9f9aad', 'A', 'Mumps', false, 0),
  ('dbc016cb-00ac-51d6-9d37-83975755155c', '988cfc96-8fad-5170-aea6-7eae5c9f9aad', 'B', 'Lymphadenopathy', false, 1),
  ('d39c55c4-b0fe-54c1-ab01-7fb361638412', '988cfc96-8fad-5170-aea6-7eae5c9f9aad', 'C', 'Submandibular sialolithiasis (salivary stone)', true, 2),
  ('00441670-38c0-550a-b7ab-c750b284460d', '988cfc96-8fad-5170-aea6-7eae5c9f9aad', 'D', 'Pleomorphic adenoma', false, 3),
  ('77f972ef-7779-5c80-9db1-e03be9500efb', '988cfc96-8fad-5170-aea6-7eae5c9f9aad', 'E', 'Dental abscess', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f098d0d9-e29c-57fc-ae01-f874bb868653', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'An 18 year old woman with type 1 diabetes presents with vomiting, abdominal pain and deep sighing breaths. Capillary glucose is 26 mmol/L, blood ketones 5.2 mmol/L, venous pH 7.12 and bicarbonate 9 mmol/L. Her blood pressure is 102/64 mmHg and heart rate 116 beats/minute. What is the SINGLE most appropriate initial management?', 'This is diabetic ketoacidosis (glucose over 11 mmol/L, ketones over 3 mmol/L, pH below 7.3 or bicarbonate below 15). The first priority is fluid resuscitation with 0.9% sodium chloride. A fixed-rate IV insulin infusion at 0.1 units/kg/hour is started once fluids are running, and potassium is added according to levels. Her usual long-acting insulin should be continued. Bicarbonate is not routinely recommended. 10% glucose is added once blood glucose falls below 14 mmol/L.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b5595468-1a34-5558-a7b9-fa71ecb43303', 'f098d0d9-e29c-57fc-ae01-f874bb868653', 'A', 'IV 10% glucose', false, 0),
  ('be63cf58-a79f-5a89-a8f1-77223ef5e4a3', 'f098d0d9-e29c-57fc-ae01-f874bb868653', 'B', 'IV fixed-rate insulin infusion before any fluids', false, 1),
  ('47b4f5ef-822d-5bc1-b567-57258c408792', 'f098d0d9-e29c-57fc-ae01-f874bb868653', 'C', 'Subcutaneous rapid-acting insulin', false, 2),
  ('ace3ede1-9527-54e0-adca-a4ee0e6db62d', 'f098d0d9-e29c-57fc-ae01-f874bb868653', 'D', 'IV sodium bicarbonate', false, 3),
  ('1ea2a81d-a01f-54db-a71e-3fe99a955e86', 'f098d0d9-e29c-57fc-ae01-f874bb868653', 'E', 'IV 0.9% sodium chloride', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e830819b-267f-5e66-8e6d-081d083bbece', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 64 year old man with type 2 diabetes on gliclazide is found by his wife sweating, shaky and mildly confused after missing lunch. His capillary blood glucose is 2.8 mmol/L. He is conscious, cooperative and able to swallow safely. What is the SINGLE most appropriate immediate management?', 'In a conscious patient who can swallow, hypoglycaemia is treated with 15-20 g of fast-acting carbohydrate (for example 4-5 glucose tablets or 150-200 mL of pure fruit juice). Recheck capillary glucose after 10-15 minutes and repeat up to three times if still below 4 mmol/L, then give a long-acting carbohydrate snack. IM glucagon or IV glucose (usually 10% or 20%) is for patients who are unconscious or cannot swallow. Sulfonylurea-induced hypoglycaemia can recur, so observe and review the dose.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('876cb8db-28e0-56aa-a945-610dba4e1ce4', 'e830819b-267f-5e66-8e6d-081d083bbece', 'A', 'Stop gliclazide and recheck glucose tomorrow', false, 0),
  ('0a242212-f6fe-5bc0-b782-bb7b443fa733', 'e830819b-267f-5e66-8e6d-081d083bbece', 'B', 'IV 50% glucose', false, 1),
  ('2db155d1-9668-5857-b15b-4dc198814c8e', 'e830819b-267f-5e66-8e6d-081d083bbece', 'C', 'IM glucagon 1 mg', false, 2),
  ('24de8aa0-a444-58db-8c27-789a4f6dfbaa', 'e830819b-267f-5e66-8e6d-081d083bbece', 'D', '15-20 g of fast-acting carbohydrate by mouth, such as glucose tablets or fruit juice', true, 3),
  ('6d1f23f8-2ad5-58ee-8b28-92b1d060bcd6', 'e830819b-267f-5e66-8e6d-081d083bbece', 'E', 'A meal containing complex carbohydrate only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('384bda99-4e1f-5f14-a5e0-712d409a36d5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 48 year old woman presents with tiredness, weight gain, constipation and feeling cold all the time. Her TSH is 18 mU/L and free T4 is 7 pmol/L (normal 9-25). She has no cardiac history. What is the SINGLE most appropriate management?', 'A raised TSH with a low free T4 is primary hypothyroidism, most commonly Hashimoto''s thyroiditis in the UK. Treatment is levothyroxine (often 1.6 micrograms/kg/day in younger patients without heart disease, and a lower starting dose in older people or those with cardiac disease). TSH is checked 6-8 weeks after each dose change. Levothyroxine should be taken on an empty stomach, separated from iron and calcium supplements.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a0511479-9a99-594c-887e-6fc4df20ce9b', '384bda99-4e1f-5f14-a5e0-712d409a36d5', 'A', 'Carbimazole', false, 0),
  ('240f4dc4-e9ce-5a9d-ae66-6adad50de365', '384bda99-4e1f-5f14-a5e0-712d409a36d5', 'B', 'Repeat TFTs in 6 months without treatment', false, 1),
  ('d573775a-d0e7-59a2-9a3d-a906bfb2b7e5', '384bda99-4e1f-5f14-a5e0-712d409a36d5', 'C', 'Levothyroxine, with TSH rechecked in 6-8 weeks', true, 2),
  ('bce40938-c6a7-593d-90c7-99d2e3d99f8d', '384bda99-4e1f-5f14-a5e0-712d409a36d5', 'D', 'Radioactive iodine', false, 3),
  ('a19008b1-2252-588a-834c-afbff99db560', '384bda99-4e1f-5f14-a5e0-712d409a36d5', 'E', 'Liothyronine as first-line', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('06fbdd0b-113e-5542-b256-7a88139b1541', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 32 year old woman presents with weight loss despite a good appetite, palpitations, heat intolerance and a tremor. She has a smooth, non-tender diffuse goitre, bilateral proptosis and lid retraction. Her TSH is undetectable and free T4 is raised. What is the SINGLE most likely diagnosis?', 'Hyperthyroidism with a diffuse goitre and thyroid eye disease (proptosis, ophthalmoplegia) is diagnostic of Graves'' disease, an autoimmune disorder caused by TSH receptor-stimulating antibodies (TRAb). Eye disease is specific to Graves''. Treatment is beta-blockers for symptoms, carbimazole (with a warning about agranulocytosis: report sore throat or fever), radioactive iodine or surgery. Smoking worsens the eye disease. De Quervain''s thyroiditis causes a painful, tender goitre.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2cf78ea8-70a5-5310-bd5c-810608caf660', '06fbdd0b-113e-5542-b256-7a88139b1541', 'A', 'Graves'' disease', true, 0),
  ('3a35843f-9cb3-5fe2-93b3-97606794aec0', '06fbdd0b-113e-5542-b256-7a88139b1541', 'B', 'Toxic adenoma', false, 1),
  ('6dc0ccf8-ee49-51ca-8e3f-56b7b074653e', '06fbdd0b-113e-5542-b256-7a88139b1541', 'C', 'Toxic multinodular goitre', false, 2),
  ('68d5c925-4dd1-58b9-96bb-96b2805715ad', '06fbdd0b-113e-5542-b256-7a88139b1541', 'D', 'Hashimoto''s thyroiditis', false, 3),
  ('8d0cb1a6-15c0-57c6-9d5c-ebef589cb4c1', '06fbdd0b-113e-5542-b256-7a88139b1541', 'E', 'Subacute (de Quervain''s) thyroiditis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2e3737df-1093-504e-92fd-0796c488e97d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 36 year old woman with known Addison''s disease is brought to the Emergency Department with vomiting and diarrhoea for 2 days. She has been unable to keep her hydrocortisone down. She is confused, her blood pressure is 76/40 mmHg, sodium 124 mmol/L, potassium 6.1 mmol/L and glucose 3.4 mmol/L. What is the SINGLE most appropriate immediate treatment?', 'This is an adrenal crisis: shock, hyponatraemia, hyperkalaemia and hypoglycaemia in a patient with adrenal insufficiency who cannot take oral steroids. Give hydrocortisone 100 mg IV or IM immediately, then 200 mg over 24 hours, with rapid IV 0.9% saline and glucose as needed. Do not delay steroids to wait for investigations. All patients should carry a steroid emergency card and an IM injection kit, and follow sick day rules.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('872b8b98-1d67-580d-adfb-dd6070e6a2a9', '2e3737df-1093-504e-92fd-0796c488e97d', 'A', 'IV fludrocortisone', false, 0),
  ('aac7c473-4bce-5d6c-a011-cf6144332db1', '2e3737df-1093-504e-92fd-0796c488e97d', 'B', 'Oral hydrocortisone at double her usual dose', false, 1),
  ('ae872ca4-02e5-5d00-88af-60c06a510bcc', '2e3737df-1093-504e-92fd-0796c488e97d', 'C', 'IV dexamethasone 1 mg only', false, 2),
  ('d1de7807-46cd-586b-a54e-472617cd907e', '2e3737df-1093-504e-92fd-0796c488e97d', 'D', 'IV hydrocortisone 100 mg and IV 0.9% sodium chloride', true, 3),
  ('d75b7925-4c7e-5285-89ba-47b29eec2986', '2e3737df-1093-504e-92fd-0796c488e97d', 'E', 'IV insulin and glucose for the hyperkalaemia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8bb8381f-1527-5a9a-8466-4592b021177b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 42 year old woman presents with weight gain around her trunk, purple abdominal striae, easy bruising, proximal muscle weakness and new hypertension. She takes no steroid medication. What is the SINGLE most appropriate first-line investigation?', 'This is suspected Cushing''s syndrome. First-line screening tests are the overnight (1 mg) low-dose dexamethasone suppression test, 24-hour urinary free cortisol or late-night salivary cortisol. Random cortisol is unhelpful because of diurnal variation. Once confirmed, ACTH levels and high-dose dexamethasone testing help find the cause before imaging. The Synacthen test is used for adrenal insufficiency. Exogenous steroids are the most common cause overall.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('12fcfd38-5318-52e8-bf5d-04677c5204ac', '8bb8381f-1527-5a9a-8466-4592b021177b', 'A', 'Overnight dexamethasone suppression test', true, 0),
  ('bdb9e266-1bb9-576d-a848-53e651e6f033', '8bb8381f-1527-5a9a-8466-4592b021177b', 'B', 'Synacthen test', false, 1),
  ('b352b87a-ebe7-51df-adef-4b106e835ff7', '8bb8381f-1527-5a9a-8466-4592b021177b', 'C', 'Random serum cortisol', false, 2),
  ('9fa9d2cb-943b-5bd4-8444-5223aaa27907', '8bb8381f-1527-5a9a-8466-4592b021177b', 'D', 'Pituitary MRI', false, 3),
  ('0f1a6846-9d28-5c37-8b6f-80743c3603ce', '8bb8381f-1527-5a9a-8466-4592b021177b', 'E', 'CT of the adrenal glands', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7450455a-cf03-579f-8a57-4f4c03d48d4f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 59 year old woman has an incidental finding on routine blood tests: adjusted calcium 2.86 mmol/L, phosphate 0.70 mmol/L and parathyroid hormone 9.8 pmol/L (normal 1.6-6.9). She has had two kidney stones. Her eGFR is normal. What is the SINGLE most likely diagnosis?', 'High calcium with a raised or inappropriately normal PTH and low phosphate is primary hyperparathyroidism, usually caused by a single parathyroid adenoma. Features are described as ''bones, stones, abdominal groans and psychic moans''. Kidney stones are an indication for parathyroidectomy. In malignancy, PTH is suppressed. Secondary hyperparathyroidism (such as in CKD or vitamin D deficiency) has a low or normal calcium.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2eb62733-b9e3-51c6-8e34-f095e8d75e72', '7450455a-cf03-579f-8a57-4f4c03d48d4f', 'A', 'Familial hypocalciuric hypercalcaemia', false, 0),
  ('fadcd07a-eef1-5427-af3d-7b0ecf853e21', '7450455a-cf03-579f-8a57-4f4c03d48d4f', 'B', 'Primary hyperparathyroidism', true, 1),
  ('91455cdc-93cb-5f12-9563-d3fb5640b541', '7450455a-cf03-579f-8a57-4f4c03d48d4f', 'C', 'Vitamin D toxicity', false, 2),
  ('3873f6ee-07b3-57fb-bd1d-8c44e74e7abf', '7450455a-cf03-579f-8a57-4f4c03d48d4f', 'D', 'Hypercalcaemia of malignancy', false, 3),
  ('98a66f87-1f9a-5733-8237-7462a86f9b0a', '7450455a-cf03-579f-8a57-4f4c03d48d4f', 'E', 'Secondary hyperparathyroidism', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('01cee9c0-8938-553b-97f7-727486aedff7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 56 year old man with a BMI of 32 kg/m2 is found to have an HbA1c of 58 mmol/mol on two occasions. He has no cardiovascular disease, heart failure or chronic kidney disease. His eGFR is 78 mL/min/1.73m2. He has tried lifestyle changes. What is the SINGLE most appropriate first-line drug?', 'Type 2 diabetes is diagnosed with an HbA1c of 48 mmol/mol or above. NICE recommends standard-release metformin as first-line, titrated to reduce GI side effects (modified-release if not tolerated). An SGLT2 inhibitor is added alongside metformin if he has heart failure or established cardiovascular disease, or should be considered if his QRISK is over 10%. The usual HbA1c target on metformin alone is 48 mmol/mol.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ca5ca98e-5930-5476-91df-e055b7fa25c8', '01cee9c0-8938-553b-97f7-727486aedff7', 'A', 'Gliclazide', false, 0),
  ('4680a082-187c-59b4-bbd1-31f04f423e0d', '01cee9c0-8938-553b-97f7-727486aedff7', 'B', 'Insulin glargine', false, 1),
  ('2679c058-a3e0-56ce-80f5-9056ac3e93c2', '01cee9c0-8938-553b-97f7-727486aedff7', 'C', 'Metformin', true, 2),
  ('651a76d1-e32f-5dd3-9b32-69e1f520164e', '01cee9c0-8938-553b-97f7-727486aedff7', 'D', 'Pioglitazone', false, 3),
  ('7300bf8d-3f6f-503f-b762-7d8ad7f396a2', '01cee9c0-8938-553b-97f7-727486aedff7', 'E', 'Sitagliptin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8589f73a-e365-52c3-8370-2a8320e5566e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 68 year old woman with metastatic breast cancer presents with confusion, constipation, polyuria and abdominal pain. Her adjusted calcium is 3.6 mmol/L and she is clinically dehydrated. What is the SINGLE most appropriate initial management?', 'Severe symptomatic hypercalcaemia (above 3.5 mmol/L) needs aggressive IV rehydration with 0.9% saline (often 3-4 L in 24 hours), followed by an IV bisphosphonate such as zoledronic acid once rehydrated. Bisphosphonates take 2-4 days to work. Loop diuretics are not routinely recommended and are only used for fluid overload. In malignancy, hypercalcaemia is usually caused by PTHrP or bone metastases.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f7835479-c717-5e0b-8a48-c4e13729e1b7', '8589f73a-e365-52c3-8370-2a8320e5566e', 'A', 'IV calcium gluconate', false, 0),
  ('c7266a29-faf8-5076-8a6e-5ce48b5c06cc', '8589f73a-e365-52c3-8370-2a8320e5566e', 'B', 'Oral calcium-free diet only', false, 1),
  ('5080e7b2-df8f-52fb-9dc4-a00118dfd5d0', '8589f73a-e365-52c3-8370-2a8320e5566e', 'C', 'IV furosemide as first-line', false, 2),
  ('e02a548f-28cc-5e4d-bbef-4ecfe6246950', '8589f73a-e365-52c3-8370-2a8320e5566e', 'D', 'Oral prednisolone alone', false, 3),
  ('3ed04a42-45dd-56c5-a12d-625e7f43b345', '8589f73a-e365-52c3-8370-2a8320e5566e', 'E', 'IV 0.9% sodium chloride rehydration, followed by IV bisphosphonate', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7fa8e6db-a39f-511f-9271-984cbf5a802c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 68 year old man with type 2 diabetes is admitted confused and very dehydrated after 5 days of polyuria. His glucose is 48 mmol/L, serum osmolality 360 mOsmol/kg, ketones 0.8 mmol/L and pH 7.36. What is the SINGLE most likely diagnosis?', 'HHS is marked hyperglycaemia (often over 30 mmol/L), hyperosmolality (over 320 mOsmol/kg) and hypovolaemia without significant ketosis or acidosis, usually in older people with type 2 diabetes. Management is cautious IV 0.9% saline, aiming for a gradual fall in osmolality, with insulin only if ketones are raised or glucose stops falling. VTE prophylaxis is important because of the high thrombosis risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('479ddc27-5e22-5eb7-b3fb-14263d878cfa', '7fa8e6db-a39f-511f-9271-984cbf5a802c', 'A', 'Hypoglycaemia', false, 0),
  ('5ff76e07-be74-594e-875d-8fe29bdfe29a', '7fa8e6db-a39f-511f-9271-984cbf5a802c', 'B', 'Hyperosmolar hyperglycaemic state', true, 1),
  ('fda75751-94ac-5040-a6af-7d177f02735f', '7fa8e6db-a39f-511f-9271-984cbf5a802c', 'C', 'Lactic acidosis', false, 2),
  ('2bf4c1ce-30ab-5623-be25-eaab2dc8f932', '7fa8e6db-a39f-511f-9271-984cbf5a802c', 'D', 'Diabetic ketoacidosis', false, 3),
  ('b0c9b31f-9b0c-5720-90e3-af5c4ea07d54', '7fa8e6db-a39f-511f-9271-984cbf5a802c', 'E', 'SIADH', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b48ecc7c-3096-5bdc-a15c-e236e78381a4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 55 year old man with type 2 diabetes takes metformin 1 g twice daily. His HbA1c is 62 mmol/mol. He has established ischaemic heart disease. What is the SINGLE most appropriate additional drug?', 'NICE recommends adding an SGLT2 inhibitor with proven cardiovascular benefit for people with type 2 diabetes and established atherosclerotic cardiovascular disease or heart failure (and considering it if QRISK is over 10%). Patients should be warned about genital infections, euglycaemic DKA (sick day rules) and Fournier''s gangrene. GLP-1 agonists are another option.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d7ddda0c-d9fa-546b-84d3-9ce0ea2dce2a', 'b48ecc7c-3096-5bdc-a15c-e236e78381a4', 'A', 'Pioglitazone', false, 0),
  ('b8f61a7d-7bc4-5d86-9616-ab555ee33fcd', 'b48ecc7c-3096-5bdc-a15c-e236e78381a4', 'B', 'Insulin glargine', false, 1),
  ('f9dce836-3dbc-576f-8887-9e26a2af60e6', 'b48ecc7c-3096-5bdc-a15c-e236e78381a4', 'C', 'Acarbose', false, 2),
  ('85e6bdad-7364-584b-88ac-8e6dcb59d4ad', 'b48ecc7c-3096-5bdc-a15c-e236e78381a4', 'D', 'An SGLT2 inhibitor (e.g. empagliflozin or dapagliflozin)', true, 3),
  ('813816fd-6e2f-532f-89bc-b8f72a2b96d9', 'b48ecc7c-3096-5bdc-a15c-e236e78381a4', 'E', 'Gliclazide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('587292d3-221c-5771-88e9-c0e17c373465', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 52 year old woman with type 2 diabetes has a BMI of 37 kg/m2. Her HbA1c remains 70 mmol/mol on triple oral therapy (metformin, sitagliptin, gliclazide). What is the SINGLE most appropriate next step?', 'NICE suggests a GLP-1 receptor agonist when triple therapy fails, for people with a BMI of 35 or above (adjusted for ethnicity), or in whom weight loss would benefit other conditions. It is continued only if HbA1c falls by at least 11 mmol/mol and weight falls by at least 3% in 6 months. GLP-1 agonists cause GI upset and carry a pancreatitis warning. DPP-4 inhibitors should not be combined with GLP-1 agonists.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('75ce9343-0395-579b-9072-d5d711b1ce02', '587292d3-221c-5771-88e9-c0e17c373465', 'A', 'Add acarbose', false, 0),
  ('5637f430-8899-5578-b9e8-dd65ea3b7522', '587292d3-221c-5771-88e9-c0e17c373465', 'B', 'Add a second sulfonylurea', false, 1),
  ('6270fbb5-3f1e-5e75-ab83-57921940d97e', '587292d3-221c-5771-88e9-c0e17c373465', 'C', 'Switch one drug to a GLP-1 receptor agonist (e.g. semaglutide)', true, 2),
  ('8f63483c-1125-522e-a642-62a61dfc9a6b', '587292d3-221c-5771-88e9-c0e17c373465', 'D', 'Add pioglitazone', false, 3),
  ('ad03edb7-b99d-5300-90e2-f2e7552b2717', '587292d3-221c-5771-88e9-c0e17c373465', 'E', 'Stop all medications', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e938cf90-c2aa-5a1d-851f-1814cd00b145', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 24 year old woman with type 1 diabetes has recurrent hypoglycaemia without warning symptoms. Her HbA1c is 46 mmol/mol. What is the SINGLE most appropriate intervention?', 'Impaired awareness of hypoglycaemia increases the risk of severe hypoglycaemia. Management includes avoiding hypoglycaemia for several weeks (relaxing targets), real-time CGM (now recommended for all people with type 1 diabetes), structured education (DAFNE) and reviewing insulin. Patients with impaired awareness must tell the DVLA and may not be allowed to drive.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e258a38f-0063-58ac-9b71-ed0e6e50d787', 'e938cf90-c2aa-5a1d-851f-1814cd00b145', 'A', 'Advise driving more', false, 0),
  ('d0b920fa-2c25-59d8-be94-7ca12925ad9c', 'e938cf90-c2aa-5a1d-851f-1814cd00b145', 'B', 'Start gliclazide', false, 1),
  ('0bc62299-ab54-5d2b-87fd-163d308af2b2', 'e938cf90-c2aa-5a1d-851f-1814cd00b145', 'C', 'Increase insulin', false, 2),
  ('6b0e0fd6-1e67-504c-95e6-3d86cdfe8480', 'e938cf90-c2aa-5a1d-851f-1814cd00b145', 'D', 'Offer continuous glucose monitoring and structured education, and relax glucose targets temporarily', true, 3),
  ('47af9b64-5072-5252-bf1a-2adbee4b00d8', 'e938cf90-c2aa-5a1d-851f-1814cd00b145', 'E', 'Stop insulin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a267611e-0d29-505f-907a-f597b19d56d3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 28 year old man with type 1 diabetes has a flu-like illness with reduced appetite. He asks whether to stop his insulin as he is not eating. What is the SINGLE most appropriate advice?', 'Sick day rules for type 1 diabetes: never stop basal insulin, check glucose every 2-4 hours and ketones regularly, drink plenty of fluids, take extra correction doses as guided, and seek urgent help if ketones are raised (over 1.5 mmol/L), vomiting persists or glucose stays high. Stopping insulin risks DKA.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1181dab2-74b8-5a1e-8b5e-bb336eea29c6', 'a267611e-0d29-505f-907a-f597b19d56d3', 'A', 'Halve basal insulin and stop testing', false, 0),
  ('5d96174b-96f9-5db7-8518-1320ea3c9e81', 'a267611e-0d29-505f-907a-f597b19d56d3', 'B', 'Never stop basal insulin; monitor glucose and ketones more often and take extra insulin as per sick day rules', true, 1),
  ('a0672630-00e8-5cd8-917e-78bdc0729c95', 'a267611e-0d29-505f-907a-f597b19d56d3', 'C', 'Stop rapid-acting insulin only and do nothing else', false, 2),
  ('f8df459b-43a9-5c7e-b472-f67105aa212e', 'a267611e-0d29-505f-907a-f597b19d56d3', 'D', 'Stop all insulin while not eating', false, 3),
  ('bada3d3c-1765-5a0b-8a92-cdacd4d4ebbd', 'a267611e-0d29-505f-907a-f597b19d56d3', 'E', 'Switch to tablets', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0113e15a-a9a6-57a7-93bf-66acddf67d80', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 34 year old woman has type 1 diabetes. During her annual review, her urine albumin:creatinine ratio is 8 mg/mmol on two occasions. Her BP is 128/78 mmHg. What is the SINGLE most appropriate management?', 'Diabetic kidney disease is detected by a raised urine ACR (3 mg/mmol or more is significant). An ACE inhibitor (or ARB) titrated to maximum tolerated dose is recommended to slow progression, even if BP is normal. Annual ACR and eGFR screening is part of diabetes care. SGLT2 inhibitors are also used in type 2 diabetes with CKD.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ed685fdf-20dc-5a37-b518-249a706c45ea', '0113e15a-a9a6-57a7-93bf-66acddf67d80', 'A', 'Start an ACE inhibitor (e.g. ramipril)', true, 0),
  ('7402a62a-7442-5944-ac11-b2baab569608', '0113e15a-a9a6-57a7-93bf-66acddf67d80', 'B', 'Start a beta-blocker', false, 1),
  ('c1909f21-21de-52d0-accd-e40c9306161e', '0113e15a-a9a6-57a7-93bf-66acddf67d80', 'C', 'Start a calcium channel blocker', false, 2),
  ('a433d927-472a-5de7-8f70-f23ae66bf47e', '0113e15a-a9a6-57a7-93bf-66acddf67d80', 'D', 'Restrict protein to 20 g a day', false, 3),
  ('8e1f3793-f8c6-5684-8024-0c21a132a4b5', '0113e15a-a9a6-57a7-93bf-66acddf67d80', 'E', 'No action as BP is normal', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('56e4abd1-5b08-55ee-9475-aefc1b5735aa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 63 year old man with type 2 diabetes has a painless ulcer under his first metatarsal head. The foot is warm with bounding pulses. Probing reaches bone. What is the SINGLE most appropriate management?', 'A diabetic foot ulcer, especially one where probe-to-bone suggests osteomyelitis, needs urgent referral to the multidisciplinary foot care service (within 1 working day) for offloading, debridement, X-ray or MRI, antibiotics and vascular assessment. Neuropathic ulcers are painless and occur at pressure points. Sudden swelling, redness and warmth of a neuropathic foot suggests Charcot arthropathy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5cf9edd3-ba9f-5f90-8cef-20fb71d55b08', '56e4abd1-5b08-55ee-9475-aefc1b5735aa', 'A', 'Reassure as it is painless', false, 0),
  ('722887a5-a706-5674-bd69-ebea92e31ab8', '56e4abd1-5b08-55ee-9475-aefc1b5735aa', 'B', 'Topical antiseptic and review in 2 weeks', false, 1),
  ('54dab37c-b155-55f3-935c-d1fcc3d1a726', '56e4abd1-5b08-55ee-9475-aefc1b5735aa', 'C', 'Below-knee amputation', false, 2),
  ('7d3b00b2-da79-50bf-bcb5-068421ff4776', '56e4abd1-5b08-55ee-9475-aefc1b5735aa', 'D', 'Urgent referral to the multidisciplinary diabetic foot service (within 1 working day)', true, 3),
  ('41b0cade-ec17-5f73-ad53-2eb8c044e2f6', '56e4abd1-5b08-55ee-9475-aefc1b5735aa', 'E', 'Oral flucloxacillin and discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c54b8030-a263-5a55-ac66-76f1ba0898ec', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 58 year old man with diabetes has a hot, swollen, red but painless left foot. There is no ulcer and he is afebrile. His CRP is normal. X-ray shows fragmentation of the midfoot. What is the SINGLE most likely diagnosis?', 'Charcot foot is a destructive arthropathy in neuropathic feet. It presents as a hot, swollen, red foot that is often painless, with normal inflammatory markers. Early X-rays may be normal, and MRI helps. Management is urgent offloading in a total contact cast or non-removable boot to prevent deformity (rocker-bottom foot). Misdiagnosis as cellulitis delays treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('61cdb534-28cf-56d7-9b4d-c1e1c6299d6f', 'c54b8030-a263-5a55-ac66-76f1ba0898ec', 'A', 'Osteomyelitis', false, 0),
  ('0e437280-65cc-5ad7-9596-36da14c98dae', 'c54b8030-a263-5a55-ac66-76f1ba0898ec', 'B', 'Charcot neuroarthropathy', true, 1),
  ('91ea74d1-3b05-5c4d-9175-83527cd39054', 'c54b8030-a263-5a55-ac66-76f1ba0898ec', 'C', 'Gout', false, 2),
  ('9320a367-6dc8-54cb-904e-a43050e1b0a1', 'c54b8030-a263-5a55-ac66-76f1ba0898ec', 'D', 'Cellulitis', false, 3),
  ('040aa07a-99fd-5885-b307-43e5549d5c13', 'c54b8030-a263-5a55-ac66-76f1ba0898ec', 'E', 'DVT', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('61677f59-9555-5f92-a384-43b7cce529c2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 30 year old woman has fatigue, weight loss, abdominal pain, salt craving and dizziness on standing. She has pigmentation of her palmar creases and buccal mucosa. Her sodium is 128 mmol/L and potassium 5.6 mmol/L. What is the SINGLE most appropriate diagnostic test?', 'Primary adrenal insufficiency (Addison''s disease, usually autoimmune in the UK) causes fatigue, weight loss, hyperpigmentation (from high ACTH), hypotension, hyponatraemia and hyperkalaemia. The short Synacthen (ACTH stimulation) test is diagnostic: cortisol fails to rise. A high ACTH confirms a primary cause. Treatment is hydrocortisone and fludrocortisone, with sick day rules.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('07bdc089-4a62-5a85-827c-cf34c1571157', '61677f59-9555-5f92-a384-43b7cce529c2', 'A', 'CT adrenals first', false, 0),
  ('f7ee7757-6480-529d-a6c8-71c3651ed0ff', '61677f59-9555-5f92-a384-43b7cce529c2', 'B', 'Random cortisol only', false, 1),
  ('060692e4-943e-55a5-85da-1bdbb931837c', '61677f59-9555-5f92-a384-43b7cce529c2', 'C', 'Overnight dexamethasone suppression test', false, 2),
  ('3ff58053-4923-5131-8db3-91626a42d304', '61677f59-9555-5f92-a384-43b7cce529c2', 'D', 'Short Synacthen test', true, 3),
  ('45999a2b-40ee-5399-80d6-a767b115b34e', '61677f59-9555-5f92-a384-43b7cce529c2', 'E', 'Aldosterone-to-renin ratio', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('83090240-178a-51c8-b3ab-059d8dae7010', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 38 year old man has had headaches and sweating, and his shoe and ring size have increased. He has coarse facial features, a prominent jaw and large hands. His BP is raised and he has impaired glucose tolerance. What is the SINGLE most appropriate diagnostic test?', 'Acromegaly is caused by excess growth hormone, usually from a pituitary adenoma. Screening is with serum IGF-1, and the diagnosis is confirmed by failure of GH to suppress on an OGTT. Then a pituitary MRI is done. Treatment is transsphenoidal surgery, with somatostatin analogues or pegvisomant if needed. Complications include cardiomyopathy, diabetes, sleep apnoea and colorectal polyps.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b592b662-25c6-5c1c-91f0-80753370864e', '83090240-178a-51c8-b3ab-059d8dae7010', 'A', 'Serum prolactin', false, 0),
  ('49a47471-257a-5db8-88c3-fb0d04523a4c', '83090240-178a-51c8-b3ab-059d8dae7010', 'B', 'CT head', false, 1),
  ('e65204ee-cd3a-5d87-97b6-571fc43772a4', '83090240-178a-51c8-b3ab-059d8dae7010', 'C', 'Serum IGF-1, confirmed by an oral glucose tolerance test with growth hormone measurement', true, 2),
  ('0919e986-f803-5471-b11b-b525c20a5f66', '83090240-178a-51c8-b3ab-059d8dae7010', 'D', 'Random growth hormone', false, 3),
  ('0ac41b31-b479-5f9b-89b5-3742c435c9cf', '83090240-178a-51c8-b3ab-059d8dae7010', 'E', 'Dexamethasone suppression test', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('34fb0fa6-37b6-5310-86b5-7f4a090e3583', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 45 year old woman has had polyuria and polydipsia, drinking 8 L a day, for 2 months after a head injury. Her glucose is normal. Her serum sodium is 147 mmol/L and urine osmolality is low. During a water deprivation test, her urine remains dilute but concentrates after desmopressin. What is the SINGLE most likely diagnosis?', 'Cranial DI (AVP deficiency) is reduced ADH secretion (after head injury, surgery, tumours or idiopathic), with large volumes of dilute urine. On water deprivation, urine stays dilute but concentrates after desmopressin. In nephrogenic DI (lithium, hypercalcaemia, hypokalaemia), urine does not concentrate even after desmopressin. Treatment is desmopressin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('31a9e98e-284e-512a-80d1-412424bf8a28', '34fb0fa6-37b6-5310-86b5-7f4a090e3583', 'A', 'Cranial diabetes insipidus (arginine vasopressin deficiency)', true, 0),
  ('abbe5bbf-da22-532b-9275-274231ea91fc', '34fb0fa6-37b6-5310-86b5-7f4a090e3583', 'B', 'Primary polydipsia', false, 1),
  ('5085de5c-85d3-5321-b4a4-39d9036fd842', '34fb0fa6-37b6-5310-86b5-7f4a090e3583', 'C', 'Diabetes mellitus', false, 2),
  ('4a0ff4eb-8d88-5e60-bd65-221e9c4acfe8', '34fb0fa6-37b6-5310-86b5-7f4a090e3583', 'D', 'SIADH', false, 3),
  ('c0612e7d-8381-51c6-b601-deb59b2046ce', '34fb0fa6-37b6-5310-86b5-7f4a090e3583', 'E', 'Nephrogenic diabetes insipidus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fc5ea514-d007-55e1-a3e4-5b91616f34cc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 72 year old woman has hyponatraemia of 126 mmol/L. She is clinically euvolaemic and has no symptoms. Serum osmolality is low, urine osmolality is 380 mOsmol/kg and urine sodium is 45 mmol/L. TFTs and cortisol are normal. She takes no medication. What is the SINGLE most appropriate initial management?', 'Asymptomatic or mild euvolaemic hyponatraemia from SIADH is first treated with fluid restriction and investigating the cause (lung or CNS pathology, malignancy, drugs). Sodium must be corrected slowly (no more than 8-10 mmol/L in 24 hours) to avoid osmotic demyelination. Hypertonic saline is for severe symptoms (seizures, reduced consciousness). Tolvaptan or demeclocycline are second-line.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('84dd38a9-ac2e-59af-bab5-4e61e8e2717e', 'fc5ea514-d007-55e1-a3e4-5b91616f34cc', 'A', 'Oral demeclocycline as first-line', false, 0),
  ('d9bb4f48-2951-5d9c-9c60-3d9456f272a5', 'fc5ea514-d007-55e1-a3e4-5b91616f34cc', 'B', 'Fluid restriction (e.g. 1 L/day) and investigate the cause of SIADH', true, 1),
  ('f662700a-a0d3-57eb-ae79-28b3a2ae51a4', 'fc5ea514-d007-55e1-a3e4-5b91616f34cc', 'C', 'IV 3% saline bolus', false, 2),
  ('2e25f339-ce8e-5d34-a162-017e73596977', 'fc5ea514-d007-55e1-a3e4-5b91616f34cc', 'D', 'IV 0.9% saline rapidly', false, 3),
  ('b73a5157-704f-5a62-9745-97b4e29ed6ff', 'fc5ea514-d007-55e1-a3e4-5b91616f34cc', 'E', 'No action', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2b0da65a-06cd-5624-aa74-eb98fb81b6d9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 70 year old man on bendroflumethiazide has a serum sodium of 119 mmol/L. He is confused and had a seizure 20 minutes ago. What is the SINGLE most appropriate initial treatment?', 'Severe symptomatic hyponatraemia (seizures, reduced GCS) is a medical emergency. A bolus of hypertonic saline (such as 150 mL of 2.7% or 3%) is given to raise sodium by 4-6 mmol/L, repeated if needed, with frequent sodium checks. The total rise should be limited to 10 mmol/L in the first 24 hours to avoid osmotic demyelination syndrome. Thiazides are a common cause in older people.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('54359a29-cbf6-553b-930b-80bd4e2a1169', '2b0da65a-06cd-5624-aa74-eb98fb81b6d9', 'A', 'Oral salt tablets', false, 0),
  ('f81c61ed-ff89-5246-8fc9-af777ce14e96', '2b0da65a-06cd-5624-aa74-eb98fb81b6d9', 'B', 'IV 5% glucose', false, 1),
  ('d1e39f03-f592-5d05-b98d-f938c3f3dbfb', '2b0da65a-06cd-5624-aa74-eb98fb81b6d9', 'C', 'IV furosemide alone', false, 2),
  ('57036613-e6d6-5674-b2de-da896846d7e2', '2b0da65a-06cd-5624-aa74-eb98fb81b6d9', 'D', 'Fluid restriction only', false, 3),
  ('64a80ba8-ae4e-52da-a85d-41bfc3ccfad4', '2b0da65a-06cd-5624-aa74-eb98fb81b6d9', 'E', 'IV hypertonic (2.7% or 3%) saline bolus with close monitoring', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c9d76b0f-7933-58a5-a0bf-a702db5428e7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 32 year old woman has been tired and constipated for 3 months, with polyuria. She has had two kidney stones. Her adjusted calcium is 2.8 mmol/L and PTH is normal (not suppressed). Her 24-hour urinary calcium excretion is very low. Her father had similar results. What is the SINGLE most likely diagnosis?', 'FHH is an autosomal dominant inactivating mutation of the calcium-sensing receptor (CASR), causing mild hypercalcaemia with an inappropriately normal PTH and low urinary calcium (calcium:creatinine clearance ratio under 0.01). It is benign and does not need parathyroidectomy, so it is important to distinguish it from primary hyperparathyroidism.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('afcb4bc0-67ae-5f0d-b7f6-60d1936b6827', 'c9d76b0f-7933-58a5-a0bf-a702db5428e7', 'A', 'Sarcoidosis', false, 0),
  ('09a2d66f-8fc3-5713-918d-6df497aa916a', 'c9d76b0f-7933-58a5-a0bf-a702db5428e7', 'B', 'Familial hypocalciuric hypercalcaemia', true, 1),
  ('19529212-4729-5a23-bcd9-bd2b11bd104a', 'c9d76b0f-7933-58a5-a0bf-a702db5428e7', 'C', 'Malignancy', false, 2),
  ('992a31fc-6658-542d-9095-0efd78e4ee49', 'c9d76b0f-7933-58a5-a0bf-a702db5428e7', 'D', 'Primary hyperparathyroidism', false, 3),
  ('be1c30e6-5455-56f0-92c4-9e3d79a8f602', 'c9d76b0f-7933-58a5-a0bf-a702db5428e7', 'E', 'Vitamin D toxicity', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('24465952-919c-503d-a791-705afb34219c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 45 year old woman with chronic kidney disease stage 4 has bone pain. Her calcium is low-normal, phosphate is high, and PTH is markedly raised. What is the SINGLE most likely diagnosis?', 'In CKD, phosphate retention and reduced vitamin D activation cause hypocalcaemia, which drives up PTH (secondary hyperparathyroidism), leading to renal bone disease. Management is dietary phosphate restriction, phosphate binders, activated vitamin D (alfacalcidol) and calcimimetics. Tertiary hyperparathyroidism is autonomous PTH secretion with high calcium after long-standing secondary disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7622b273-8c3a-54b8-b323-009dae39a720', '24465952-919c-503d-a791-705afb34219c', 'A', 'Tertiary hyperparathyroidism', false, 0),
  ('9a007a84-d7e9-5f33-a47f-2aa9390416e2', '24465952-919c-503d-a791-705afb34219c', 'B', 'Primary hyperparathyroidism', false, 1),
  ('b1027dd8-ce7b-5dbd-a6e5-8a3a351c6a2c', '24465952-919c-503d-a791-705afb34219c', 'C', 'Familial hypocalciuric hypercalcaemia', false, 2),
  ('9b17bc00-3eeb-5485-88aa-9511ff87f81f', '24465952-919c-503d-a791-705afb34219c', 'D', 'Hypoparathyroidism', false, 3),
  ('4533903f-edd1-584e-a69b-ccfd25265f16', '24465952-919c-503d-a791-705afb34219c', 'E', 'Secondary hyperparathyroidism', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('530136b0-827f-5dcb-8f8d-e8d3883c797c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 25 year old woman had a total thyroidectomy for Graves'' disease 3 months ago. She now has perioral numbness and her adjusted calcium is 1.85 mmol/L. Her PTH is low. What is the SINGLE most appropriate long-term treatment?', 'Permanent hypoparathyroidism after thyroid surgery causes hypocalcaemia with low PTH. Long-term treatment is an activated vitamin D analogue (alfacalcidol or calcitriol), which does not need PTH for activation, plus calcium supplements. Calcium should be monitored to avoid hypercalciuria and kidney stones. Acute severe hypocalcaemia needs IV calcium gluconate.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('34de8fcc-ed1c-5bd5-ad8d-9891f698f1ae', '530136b0-827f-5dcb-8f8d-e8d3883c797c', 'A', 'Thiazide alone', false, 0),
  ('6cd8e9a6-0711-58cb-9115-01ec3d7aeff7', '530136b0-827f-5dcb-8f8d-e8d3883c797c', 'B', 'Cinacalcet', false, 1),
  ('ef92b1c0-2675-5671-96c5-0f08f2f8951f', '530136b0-827f-5dcb-8f8d-e8d3883c797c', 'C', 'Oral levothyroxine increase', false, 2),
  ('486bce6c-2bbc-5837-9d3b-5acb272c0e8e', '530136b0-827f-5dcb-8f8d-e8d3883c797c', 'D', 'Alfacalcidol (or calcitriol) with calcium supplements', true, 3),
  ('efab4110-0419-5f59-9b75-07bbb49909b5', '530136b0-827f-5dcb-8f8d-e8d3883c797c', 'E', 'Bisphosphonate', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('58a11ca4-a7ce-56fc-a78d-117afc391ff6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 45 year old woman has had palpitations and a tremor. She has a single palpable thyroid nodule. TSH is suppressed and free T4 raised. A technetium scan shows a single ''hot'' nodule with suppression of the rest of the gland. What is the SINGLE most likely diagnosis?', 'A toxic adenoma is a single autonomous hyperfunctioning nodule, showing as a hot nodule with suppressed uptake elsewhere. Toxic multinodular goitre shows patchy uptake, and Graves'' shows diffuse increased uptake. Thyroiditis shows reduced uptake. Radioiodine is often the treatment of choice for toxic nodular disease. Hot nodules are rarely malignant.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4296168b-6393-52f8-8282-cefb537c7e35', '58a11ca4-a7ce-56fc-a78d-117afc391ff6', 'A', 'Toxic adenoma', true, 0),
  ('3f33d881-6615-5681-9e87-8c15ec43941e', '58a11ca4-a7ce-56fc-a78d-117afc391ff6', 'B', 'Thyroid cancer', false, 1),
  ('868f8d5e-af4d-5588-aefc-094ccff3761b', '58a11ca4-a7ce-56fc-a78d-117afc391ff6', 'C', 'Hashimoto''s thyroiditis', false, 2),
  ('beda31ac-7582-5b00-85e8-e998e6637bff', '58a11ca4-a7ce-56fc-a78d-117afc391ff6', 'D', 'Graves'' disease', false, 3),
  ('0c843d84-4f88-57cd-bfc6-7de186e72932', '58a11ca4-a7ce-56fc-a78d-117afc391ff6', 'E', 'Subacute thyroiditis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4f28c6b8-d7e1-52ce-880c-a94a27165e44', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 30 year old woman is 8 weeks pregnant and has newly diagnosed hyperthyroidism from Graves'' disease. Which antithyroid drug is preferred in the first trimester?', 'Propylthiouracil is preferred in the first trimester because carbimazole is linked to congenital abnormalities (aplasia cutis, choanal atresia). Carbimazole is preferred after that, because propylthiouracil can cause severe hepatotoxicity. The lowest effective dose is used, aiming for free T4 in the upper normal range. Radioiodine is contraindicated in pregnancy. TRAb crosses the placenta and can cause fetal thyrotoxicosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('132450e4-2b96-574b-b651-bb747d10fabe', '4f28c6b8-d7e1-52ce-880c-a94a27165e44', 'A', 'Propylthiouracil', true, 0),
  ('227a86e7-fd85-54d8-b670-bc35e0da6072', '4f28c6b8-d7e1-52ce-880c-a94a27165e44', 'B', 'Levothyroxine', false, 1),
  ('1fbd6535-ad0a-5f7d-a485-2d3e03f0d1b0', '4f28c6b8-d7e1-52ce-880c-a94a27165e44', 'C', 'Radioactive iodine', false, 2),
  ('75ab5adc-c22f-574b-a5bd-0a36172743e7', '4f28c6b8-d7e1-52ce-880c-a94a27165e44', 'D', 'Lithium', false, 3),
  ('ecb6f98e-100d-51ad-9da5-da59c1ebaba3', '4f28c6b8-d7e1-52ce-880c-a94a27165e44', 'E', 'Carbimazole', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('459d4ded-355d-5ccd-a90a-7b53a19f9053', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 42 year old woman on carbimazole for 4 weeks has a sore throat and fever of 38.6°C. What is the SINGLE most appropriate immediate action?', 'Carbimazole can cause agranulocytosis, usually in the first 3 months. Patients must be told to report any sore throat, mouth ulcers, fever or signs of infection, and to stop the drug pending an urgent FBC. Neutropenic sepsis needs urgent IV antibiotics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('744e6474-55d6-5cf0-9bb9-a9985cd5e008', '459d4ded-355d-5ccd-a90a-7b53a19f9053', 'A', 'Throat swab only and review in 1 week', false, 0),
  ('73b59590-0791-5c95-8a76-a39b30de5b7d', '459d4ded-355d-5ccd-a90a-7b53a19f9053', 'B', 'Increase carbimazole', false, 1),
  ('69a400dc-ed2f-5556-8a7b-604596a73c0c', '459d4ded-355d-5ccd-a90a-7b53a19f9053', 'C', 'Stop carbimazole and check an urgent full blood count', true, 2),
  ('2ef4fefa-b098-541f-a635-58ad089dee6d', '459d4ded-355d-5ccd-a90a-7b53a19f9053', 'D', 'Switch to radioactive iodine immediately', false, 3),
  ('acea2a34-5fc1-54d1-bb93-af6f6d7a67fa', '459d4ded-355d-5ccd-a90a-7b53a19f9053', 'E', 'Continue carbimazole and give antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0617533c-3c26-55e4-a2c3-1e06bd8a7c0a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 70 year old woman has had fatigue and weight gain. Her TSH is 7.2 mU/L with a normal free T4 on two occasions 3 months apart. She has no symptoms of hypothyroidism and her TPO antibodies are negative. What is the SINGLE most appropriate management?', 'Subclinical hypothyroidism is a raised TSH with a normal free T4. In people over 65 with a TSH under 10, NICE suggests watchful waiting. Treatment is considered for a TSH of 10 or above on two occasions, or in younger people with symptoms. Positive TPO antibodies increase the risk of progression. Non-thyroidal illness should be excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('01ae3e9e-4883-5881-b442-527df16ce05a', '0617533c-3c26-55e4-a2c3-1e06bd8a7c0a', 'A', 'Radioactive iodine', false, 0),
  ('daa34b93-22d9-57d0-abe2-5cb8a4c7f07f', '0617533c-3c26-55e4-a2c3-1e06bd8a7c0a', 'B', 'Thyroidectomy', false, 1),
  ('c13b031b-d8ce-584d-ba00-c4d59d528c01', '0617533c-3c26-55e4-a2c3-1e06bd8a7c0a', 'C', 'Monitor TFTs (e.g. every 6-12 months); no treatment needed', true, 2),
  ('b3e36c6f-8a87-5c95-b926-1532f7171535', '0617533c-3c26-55e4-a2c3-1e06bd8a7c0a', 'D', 'Start carbimazole', false, 3),
  ('5edc1199-917f-520c-a593-b5c6483f35be', '0617533c-3c26-55e4-a2c3-1e06bd8a7c0a', 'E', 'Start levothyroxine 100 micrograms', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a9cb9570-b934-5ee8-b26b-e98f0681964a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 72 year old man in a nursing home is drowsy and hypothermic (temperature 32°C). He has a slow pulse, hypoventilation, hyponatraemia and hypoglycaemia. He has a thyroidectomy scar and his family say he stopped his tablets months ago. What is the SINGLE most appropriate treatment?', 'Myxoedema coma is a life-threatening decompensation of hypothyroidism, often triggered by infection or cold, causing reduced consciousness, hypothermia, bradycardia, hypoventilation, hyponatraemia and hypoglycaemia. Treatment is in ICU with IV thyroid hormone, IV hydrocortisone (given first, until adrenal insufficiency is excluded), passive rewarming and supportive care.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('93e20e4b-cd4b-5fbe-ada4-6a76d8b67865', 'a9cb9570-b934-5ee8-b26b-e98f0681964a', 'A', 'IV insulin', false, 0),
  ('81d31812-d26e-5667-99ab-7adbe0461be7', 'a9cb9570-b934-5ee8-b26b-e98f0681964a', 'B', 'IV hydrocortisone, then IV thyroid hormone replacement (liothyronine or levothyroxine), with supportive care in ICU', true, 1),
  ('59be0b83-29a7-5fd9-b667-81334e5b571b', 'a9cb9570-b934-5ee8-b26b-e98f0681964a', 'C', 'Oral levothyroxine 25 micrograms and review in 6 weeks', false, 2),
  ('6bac2824-c270-5492-b80e-16d5eb2a737c', 'a9cb9570-b934-5ee8-b26b-e98f0681964a', 'D', 'Carbimazole', false, 3),
  ('a44ceba9-5144-5414-9e41-4ffa49333a6e', 'a9cb9570-b934-5ee8-b26b-e98f0681964a', 'E', 'Rapid active warming only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c933de91-d663-5334-8700-31410fb64bba', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 34 year old man with known Graves'' disease has had an infection and is now agitated and confused. His temperature is 40.1°C, he is in atrial fibrillation at 170 beats/minute, and he has vomiting and diarrhoea. What is the SINGLE most appropriate initial management?', 'Thyroid storm is a life-threatening exacerbation of thyrotoxicosis with fever, tachycardia, AF, agitation, GI symptoms and heart failure. Treatment is beta-blockade (propranolol), a thionamide (PTU or carbimazole), iodine given at least 1 hour after the thionamide, hydrocortisone (which reduces T4 to T3 conversion) and supportive care in ICU. Aspirin should be avoided because it displaces thyroid hormone from binding proteins.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('538ae184-30e7-5f19-8a6b-e145e36f31ee', 'c933de91-d663-5334-8700-31410fb64bba', 'A', 'Thyroidectomy immediately', false, 0),
  ('ee801f47-773b-5885-9f63-e12422e59dcc', 'c933de91-d663-5334-8700-31410fb64bba', 'B', 'Propranolol, propylthiouracil, then Lugol''s iodine, plus hydrocortisone and supportive care', true, 1),
  ('f0c3319e-0e70-5951-95fd-9d0306c795ef', 'c933de91-d663-5334-8700-31410fb64bba', 'C', 'Radioactive iodine immediately', false, 2),
  ('f22249b5-e652-547b-8d8b-66e875e4dcb6', 'c933de91-d663-5334-8700-31410fb64bba', 'D', 'Levothyroxine', false, 3),
  ('aeaa6983-839e-5e8a-82c2-11113e24b4b3', 'c933de91-d663-5334-8700-31410fb64bba', 'E', 'Aspirin for the fever', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b3b935cc-b33f-552a-91cd-2edd2b27e80b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 28 year old woman has 3 months of headaches and bitemporal hemianopia. She has secondary amenorrhoea, galactorrhoea and a raised prolactin of 6,000 mU/L. MRI shows a 2 cm pituitary adenoma. What is the SINGLE most appropriate first-line treatment?', 'Even large prolactinomas (macroprolactinomas) causing visual field defects usually shrink with dopamine agonist treatment (cabergoline or bromocriptine), which is first-line, with close visual field monitoring. Surgery is for patients who do not respond, cannot tolerate treatment, or have pituitary apoplexy. Very high prolactin levels suggest a prolactinoma rather than stalk compression.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e52ca91a-873e-5c99-8292-49ac89d7c887', 'b3b935cc-b33f-552a-91cd-2edd2b27e80b', 'A', 'Transsphenoidal surgery as first-line', false, 0),
  ('1c621860-fe87-5eab-992f-b15a1cf08994', 'b3b935cc-b33f-552a-91cd-2edd2b27e80b', 'B', 'Octreotide', false, 1),
  ('4208a1f0-f24a-5589-b71d-fe89384db070', 'b3b935cc-b33f-552a-91cd-2edd2b27e80b', 'C', 'Radiotherapy', false, 2),
  ('63965cae-72bc-5d6f-96f0-bd976e11e762', 'b3b935cc-b33f-552a-91cd-2edd2b27e80b', 'D', 'Cabergoline', true, 3),
  ('efa361ce-0b2f-55d1-b835-cae342004d32', 'b3b935cc-b33f-552a-91cd-2edd2b27e80b', 'E', 'Hydrocortisone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2eb5fe40-6de4-544b-a6e0-b0dcd68ec547', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 52 year old woman with a pituitary macroadenoma has a sudden severe headache, vomiting, visual loss and ophthalmoplegia. She is hypotensive. What is the SINGLE most appropriate immediate treatment?', 'Pituitary apoplexy is haemorrhage or infarction of a pituitary tumour. It presents with a thunderclap headache, visual loss, ophthalmoplegia and acute hypopituitarism, especially life-threatening ACTH deficiency causing adrenal crisis. Give immediate IV hydrocortisone. MRI confirms it, and urgent neurosurgical decompression may be needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('aacf5ce2-4dbe-5af6-aa90-1bd5ed04121c', '2eb5fe40-6de4-544b-a6e0-b0dcd68ec547', 'A', 'IV hydrocortisone and urgent neurosurgical review', true, 0),
  ('c724ce4b-03c8-5ef5-ad1e-345a3f236924', '2eb5fe40-6de4-544b-a6e0-b0dcd68ec547', 'B', 'Oral cabergoline', false, 1),
  ('88072d67-67b8-50e2-98a8-92b70864d2ba', '2eb5fe40-6de4-544b-a6e0-b0dcd68ec547', 'C', 'Oral prednisolone 5 mg', false, 2),
  ('b35d9b3d-99c8-5b56-9fe2-8ba4eae502a5', '2eb5fe40-6de4-544b-a6e0-b0dcd68ec547', 'D', 'IV thrombolysis', false, 3),
  ('4102d721-6f83-5dc0-a6c2-9e6e61ca9edc', '2eb5fe40-6de4-544b-a6e0-b0dcd68ec547', 'E', 'Lumbar puncture', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7def0802-23e1-5389-b958-b0f52c2c1a9e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 26 year old woman has a BMI of 41 kg/m2 with type 2 diabetes and hypertension. She has tried diet and exercise and a weight management programme without success. What is the SINGLE most appropriate next option to discuss?', 'NICE recommends considering bariatric surgery for adults with a BMI of 40 or above, or 35-40 with significant comorbidity (such as type 2 diabetes or hypertension), if other measures have failed and they commit to long-term follow-up. Recent-onset type 2 diabetes with a BMI of 30-35 can also be assessed. GLP-1 agonists (semaglutide, tirzepatide) are options in specialist weight management services.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('03abaa0d-cc77-50a6-b7d2-a9d932fe00ac', '7def0802-23e1-5389-b958-b0f52c2c1a9e', 'A', 'Thyroxine for weight loss', false, 0),
  ('83742f65-c3df-53fb-9d94-60743626d24a', '7def0802-23e1-5389-b958-b0f52c2c1a9e', 'B', 'No further treatment', false, 1),
  ('3ea6526d-56dc-580b-947d-44192e17bc8a', '7def0802-23e1-5389-b958-b0f52c2c1a9e', 'C', 'Very-low-calorie diet for 1 year', false, 2),
  ('1c5559ef-135b-5419-baa0-df6e6770e996', '7def0802-23e1-5389-b958-b0f52c2c1a9e', 'D', 'Lifelong orlistat only', false, 3),
  ('aa443d88-e375-52a1-9a61-0ddc302bf877', '7def0802-23e1-5389-b958-b0f52c2c1a9e', 'E', 'Referral for bariatric surgery assessment (tier 4 services)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('736d4dc1-7ad9-56cd-973c-e28f9d87964c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 34 year old man has had episodes of sweating, tremor, palpitations and confusion before breakfast and after exercise. During an episode his glucose was 2.1 mmol/L, with high insulin and high C-peptide. He does not take diabetes medication. What is the SINGLE most likely diagnosis?', 'Whipple''s triad is symptoms of hypoglycaemia, documented low glucose, and relief with glucose. High insulin with high C-peptide means endogenous insulin (insulinoma or sulfonylurea use). Exogenous insulin causes high insulin with low C-peptide. A sulfonylurea screen distinguishes the two. Insulinomas are associated with MEN1. A 72-hour supervised fast confirms the diagnosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c1574fd3-f067-5236-b64a-6bc8b7663c3b', '736d4dc1-7ad9-56cd-973c-e28f9d87964c', 'A', 'Insulinoma', true, 0),
  ('9e340a9d-bc27-5c1e-9002-65b407cf512f', '736d4dc1-7ad9-56cd-973c-e28f9d87964c', 'B', 'Dumping syndrome', false, 1),
  ('7a6b63e0-8743-53e9-ba5a-88741b43cf02', '736d4dc1-7ad9-56cd-973c-e28f9d87964c', 'C', 'Factitious insulin injection', false, 2),
  ('c8229fa1-33cc-55e1-8167-9fcd9f662788', '736d4dc1-7ad9-56cd-973c-e28f9d87964c', 'D', 'Sulfonylurea overdose', false, 3),
  ('0064990d-3175-51d3-92c3-fb61c18c009d', '736d4dc1-7ad9-56cd-973c-e28f9d87964c', 'E', 'Addison''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('04427bad-95ca-51a6-8fbc-d8b673b54f2e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 23 year old man has hypertension, fatigue and a potassium of 2.7 mmol/L with metabolic alkalosis. Renin and aldosterone are both raised. He has no diuretic use. His BP returns to normal on an ACE inhibitor. Imaging shows a narrowed renal artery with a ''string of beads'' appearance. What is the SINGLE most likely diagnosis?', 'Renal artery stenosis causes renin-driven secondary hyperaldosteronism (high renin and aldosterone). In young women and men, fibromuscular dysplasia causes a string-of-beads appearance, while atherosclerosis is commoner in older people. Angioplasty is effective for FMD. ACE inhibitors can cause AKI in bilateral renal artery stenosis. Conn''s syndrome has high aldosterone with suppressed renin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('55122bb3-e33f-5166-b772-3f4f52d3764e', '04427bad-95ca-51a6-8fbc-d8b673b54f2e', 'A', 'Conn''s syndrome', false, 0),
  ('9780e4e9-7622-5d73-a7c7-7680a7571f25', '04427bad-95ca-51a6-8fbc-d8b673b54f2e', 'B', 'Liddle''s syndrome', false, 1),
  ('ac7a1109-958d-5203-9de8-2e17b2234ae8', '04427bad-95ca-51a6-8fbc-d8b673b54f2e', 'C', 'Cushing''s syndrome', false, 2),
  ('e1612f2c-b008-546c-897a-4bd83b1e88f7', '04427bad-95ca-51a6-8fbc-d8b673b54f2e', 'D', 'Fibromuscular dysplasia causing renal artery stenosis', true, 3),
  ('c6fec92c-c1b9-526a-9438-9a1555b11322', '04427bad-95ca-51a6-8fbc-d8b673b54f2e', 'E', 'Bartter syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ab6b6502-5e0f-596d-b176-716d5b2acb27', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 62 year old woman has had low back pain and a vertebral wedge fracture on X-ray after minimal trauma. Her calcium and phosphate are low, ALP is raised and 25-hydroxyvitamin D is very low. She covers her skin and rarely goes outdoors. What is the SINGLE most likely diagnosis?', 'Osteomalacia is defective bone mineralisation, usually from vitamin D deficiency. It causes bone pain, proximal myopathy and fractures (Looser''s zones), with low or normal calcium, low phosphate, raised ALP and low vitamin D. Treatment is vitamin D loading (such as colecalciferol 300,000 IU over 6-10 weeks) then maintenance. In osteoporosis, bone biochemistry is normal.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5d6f574b-e673-5d99-a2eb-d6ac94bc5a23', 'ab6b6502-5e0f-596d-b176-716d5b2acb27', 'A', 'Osteoporosis', false, 0),
  ('c468468d-6b37-5abc-acde-d7de761603a8', 'ab6b6502-5e0f-596d-b176-716d5b2acb27', 'B', 'Multiple myeloma', false, 1),
  ('7b8a82c3-e290-5196-8a0a-a097de121825', 'ab6b6502-5e0f-596d-b176-716d5b2acb27', 'C', 'Primary hyperparathyroidism', false, 2),
  ('bbce2d63-b502-5b14-8a9e-010c11336663', 'ab6b6502-5e0f-596d-b176-716d5b2acb27', 'D', 'Osteomalacia', true, 3),
  ('f9ae5dfe-deb4-5fea-ad7f-5d28b7dc6912', 'ab6b6502-5e0f-596d-b176-716d5b2acb27', 'E', 'Paget''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fc5426f5-0395-5328-a211-86392f9adcf5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 70 year old man has an incidentally raised ALP of 520 U/L with normal calcium, phosphate and LFTs. He has some bone pain in his pelvis and his hat feels tighter. X-ray shows a thickened skull and mixed lytic and sclerotic lesions of the pelvis. What is the SINGLE most likely diagnosis?', 'Paget''s disease is disordered bone remodelling causing enlarged, deformed bones (skull, pelvis, spine, femur), with an isolated raised ALP and normal calcium. Complications include bone pain, deafness (from nerve compression), fractures, high-output heart failure and, rarely, osteosarcoma. Bisphosphonates (such as zoledronate) are used to treat bone pain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('53a9e698-ed37-5f55-8663-c9d05b2763b4', 'fc5426f5-0395-5328-a211-86392f9adcf5', 'A', 'Osteomalacia', false, 0),
  ('0747ab2b-da32-5ae5-b202-c01f7260844e', 'fc5426f5-0395-5328-a211-86392f9adcf5', 'B', 'Prostate cancer metastases', false, 1),
  ('96e42e22-2020-510b-aab9-e75f885a1c08', 'fc5426f5-0395-5328-a211-86392f9adcf5', 'C', 'Paget''s disease of bone', true, 2),
  ('fc66aa7a-65a2-510b-9a25-ea8fee6b5dce', 'fc5426f5-0395-5328-a211-86392f9adcf5', 'D', 'Osteoporosis', false, 3),
  ('995d8d69-5588-551e-a936-c04ea3951833', 'fc5426f5-0395-5328-a211-86392f9adcf5', 'E', 'Multiple myeloma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0073c4f2-4ecc-5190-b536-5eb4c6da1921', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'An 18 year old woman has blurred vision for 24 hours and is seen in the Emergency Department. She has increased thirst and drinks 4 litres of water a day. She has lost 10 Kgs in weight in 6 weeks. Her temperature is 37.2°C, pulse rate 100 bpm, BP 90/50 mmHg, respiratory rate 30 breaths per minute and oxygen saturation 98% breathing air. Which is the most important initial investigation?', 'Polydipsia, weight loss, blurred vision, tachycardia, hypotension and Kussmaul-type tachypnoea in a young woman suggest new type 1 diabetes with diabetic ketoacidosis. The quickest and most important first test is capillary glucose, followed by ketones, a blood gas and electrolytes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eb0eb74d-949c-51bf-8317-1fb0c8555d55', '0073c4f2-4ecc-5190-b536-5eb4c6da1921', 'A', 'Arterial blood gases', false, 0),
  ('1a75ad8c-40b8-59df-9330-7624ba9c880a', '0073c4f2-4ecc-5190-b536-5eb4c6da1921', 'B', 'Blood cultures', false, 1),
  ('fcca71c0-8704-5d70-8c42-652e352dc4ca', '0073c4f2-4ecc-5190-b536-5eb4c6da1921', 'C', 'Capillary glucose', true, 2),
  ('a95304fd-deb9-5245-80de-86032a0e7222', '0073c4f2-4ecc-5190-b536-5eb4c6da1921', 'D', 'Full blood count', false, 3),
  ('ab569072-6fe7-550f-b985-6c56f0418e4e', '0073c4f2-4ecc-5190-b536-5eb4c6da1921', 'E', 'Serum electrolytes', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('113ef50c-b0cc-525e-b7d2-b1e5c43dac3b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 43 year old man has felt faint and fallen when trying to stand from a chair. He has had vomiting for 5 days. He has lung cancer. Recently he had a seizure and subsequent imaging showed a brain metastasis. He takes dexamethasone 6 mg every day and also cyclizine 50 mg if needed. Investigations: Sodium 119 mmol/L (135–146) Potassium 5.5 mmol/L (3.5–5.3) Urea 14.2 mmol/L (2.5–7.8) Creatinine 118 micromol/L (60–120) Urine osmolality 400 mOsmol/kg Urinary sodium 30 mmol/L Serum osmolality 260 mOsmol/kg (285–295) Which is the most likely cause for these results?', 'Hyponatraemia with low serum osmolality, inappropriately concentrated urine (over 100 mOsmol/kg) and urinary sodium over 30 mmol/L, with SCLC and a brain metastasis, suggests SIADH. Adrenal insufficiency is less likely because he takes dexamethasone. Vomiting and a raised urea suggest some volume depletion, but the urine sodium and osmolality favour SIADH.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d0f0adf4-eb00-564f-9989-985cd0ff635b', '113ef50c-b0cc-525e-b7d2-b1e5c43dac3b', 'A', 'Adrenal insufficiency', false, 0),
  ('a60dc2b7-1a6b-59fe-a5ac-d3f07f53856a', '113ef50c-b0cc-525e-b7d2-b1e5c43dac3b', 'B', 'Dehydration', false, 1),
  ('66a6770c-e129-5c0b-9e69-429f5abdc105', '113ef50c-b0cc-525e-b7d2-b1e5c43dac3b', 'C', 'Medication side-effects', false, 2),
  ('914f00da-f4c6-5c8b-b0a5-e5c2b0b23efd', '113ef50c-b0cc-525e-b7d2-b1e5c43dac3b', 'D', 'Stroke', false, 3),
  ('87e62e8b-8244-5508-a25b-0df47ee64a6a', '113ef50c-b0cc-525e-b7d2-b1e5c43dac3b', 'E', 'Syndrome of inappropriate ADH secretion', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('be0ae508-091a-5553-955c-4e5a0af1c4c8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 34 year old woman has had secondary amenorrhoea for 8 months. She has lost 6 kg in weight despite having a good appetite. Which is the most likely diagnosis?', 'Weight loss despite a good appetite, with secondary amenorrhoea, suggests hyperthyroidism, which can cause oligomenorrhoea or amenorrhoea. Investigation is TSH and free T4. PCOS and prolactinoma usually cause weight gain or no weight change. Pregnancy should always be excluded first in amenorrhoea.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f5068c85-76c3-5b3d-8347-5946302ceb23', 'be0ae508-091a-5553-955c-4e5a0af1c4c8', 'A', 'Hyperthyroidism', true, 0),
  ('d7eb4501-b6f6-50ad-b3b8-d7166928488a', 'be0ae508-091a-5553-955c-4e5a0af1c4c8', 'B', 'Hypogonadism', false, 1),
  ('5d0f6f16-8db4-5429-babd-01f6dc466a8f', 'be0ae508-091a-5553-955c-4e5a0af1c4c8', 'C', 'Polycystic ovary syndrome', false, 2),
  ('654f01d9-e9d2-5670-b03c-85083c4b7a49', 'be0ae508-091a-5553-955c-4e5a0af1c4c8', 'D', 'Premature ovarian failure', false, 3),
  ('5e0691da-86bd-5700-8380-4ddc261731f7', 'be0ae508-091a-5553-955c-4e5a0af1c4c8', 'E', 'Prolactinoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('27ba7f0d-1eba-5e7b-893d-528e6e7ca09e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 45 year old woman has had flu like symptoms, palpitations, anxiety and pain over her thyroid gland for 2 weeks. Her pulse rate is 92 bpm and regular. She has a fine tremor and is sweating. She is tender over her thyroid but there are no masses. Investigations: TSH 0.1 mU/L (0.3–4.2) Free T4 28.6 pmol/L (9–25) Isotope scan of thyroid shows global decreased uptake. Which is the most appropriate treatment?', 'A painful, tender thyroid after a viral illness, with hyperthyroidism and globally reduced uptake on the isotope scan, is subacute (de Quervain''s) thyroiditis. The hyperthyroid phase comes from release of stored hormone, so antithyroid drugs are ineffective. Treatment is a beta-blocker such as propranolol for symptoms and NSAIDs for pain, with steroids if severe.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6fd6087e-ab87-5b0c-9af7-7eb1865c04f2', '27ba7f0d-1eba-5e7b-893d-528e6e7ca09e', 'A', 'Carbimazole', false, 0),
  ('c793bbc6-b1a4-57ff-819e-f884c78e7351', '27ba7f0d-1eba-5e7b-893d-528e6e7ca09e', 'B', 'Prednisolone', false, 1),
  ('4772bd5a-3c21-5ef9-a324-68208e5b5b4f', '27ba7f0d-1eba-5e7b-893d-528e6e7ca09e', 'C', 'Propranolol', true, 2),
  ('467b84d7-4160-557a-98e9-2b5d3a625d1d', '27ba7f0d-1eba-5e7b-893d-528e6e7ca09e', 'D', 'Propylthiouracil', false, 3),
  ('fac43f8a-2cf0-5c50-b353-da5a532ada61', '27ba7f0d-1eba-5e7b-893d-528e6e7ca09e', 'E', 'Radioiodine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2e7a60e0-6a10-5140-bc93-76313c473c2a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 56 year old man with known alcohol-related cirrhosis presents with two episodes of large-volume haematemesis. His heart rate is 118 beats/minute and blood pressure 96/58 mmHg. Two large-bore cannulas are in place and blood has been requested. Endoscopy is planned within the next few hours. What is the SINGLE most appropriate drug treatment before endoscopy?', 'Suspected variceal bleeding in cirrhosis should be treated before endoscopy with terlipressin, which reduces portal pressure, and prophylactic broad-spectrum antibiotics, which reduce infection and mortality. Variceal band ligation at endoscopy is the definitive treatment. Propranolol is for primary or secondary prevention, not acute bleeding. Tranexamic acid is not recommended in GI bleeding (HALT-IT trial).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f6c8f97f-bf6d-5c1c-be5e-3754020099b3', '2e7a60e0-6a10-5140-bc93-76313c473c2a', 'A', 'IV omeprazole only', false, 0),
  ('0944831a-9987-5e7d-901c-8a6f62da0c91', '2e7a60e0-6a10-5140-bc93-76313c473c2a', 'B', 'Oral propranolol', false, 1),
  ('1063692d-dc4e-5dcf-a1b7-bdc890ec5259', '2e7a60e0-6a10-5140-bc93-76313c473c2a', 'C', 'Oral lactulose', false, 2),
  ('c198afe7-c1f2-5b20-a111-c3d49c5b12b1', '2e7a60e0-6a10-5140-bc93-76313c473c2a', 'D', 'IV terlipressin and IV antibiotics', true, 3),
  ('065300df-0108-54db-97fb-07a364a0fa4c', '2e7a60e0-6a10-5140-bc93-76313c473c2a', 'E', 'IV tranexamic acid', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c22e4522-328e-573a-ba8a-8b8d54720e81', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 27 year old woman attends her GP with 6 months of bloating, loose stools and tiredness. Blood tests show iron deficiency anaemia. She has type 1 diabetes. She eats a normal diet that includes gluten every day. What is the SINGLE most appropriate first-line investigation for the most likely diagnosis?', 'Coeliac disease is more common in people with type 1 diabetes and can cause iron deficiency. First-line testing is total IgA with IgA tTG antibodies, done while the patient is eating gluten (in more than one meal a day for at least 6 weeks). Total IgA is measured because IgA deficiency gives a false-negative result. Positive serology in adults is usually confirmed by duodenal biopsy. HLA typing is mainly useful for its negative predictive value.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2b59b98d-807d-5e09-9b10-1aab0e4872f4', 'c22e4522-328e-573a-ba8a-8b8d54720e81', 'A', 'Hydrogen breath test', false, 0),
  ('b7dba324-9557-5e4c-8d14-43b943b31f35', 'c22e4522-328e-573a-ba8a-8b8d54720e81', 'B', 'Duodenal biopsy at upper GI endoscopy', false, 1),
  ('9ef72dc3-935b-5aa0-aeb9-23b045827326', 'c22e4522-328e-573a-ba8a-8b8d54720e81', 'C', 'Faecal calprotectin', false, 2),
  ('72c40276-1b0b-5e21-8215-e9420421d592', 'c22e4522-328e-573a-ba8a-8b8d54720e81', 'D', 'HLA-DQ2/DQ8 genotyping', false, 3),
  ('910637b4-e578-5fee-81bd-95bc2a9b3253', 'c22e4522-328e-573a-ba8a-8b8d54720e81', 'E', 'Total IgA and IgA tissue transglutaminase (tTG) antibodies', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('27cdbc51-3a94-545f-b81a-08a3fa6e192c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 52 year old woman presents with severe epigastric pain radiating to her back and vomiting. Her serum amylase is 1,850 U/L. She drinks 4 units of alcohol a week. Ultrasound shows multiple gallstones in the gallbladder and a common bile duct of normal calibre. What is the SINGLE most likely cause of her condition?', 'Acute pancreatitis is diagnosed by typical pain plus amylase or lipase more than 3 times the upper limit of normal. Gallstones and alcohol are the two commonest causes in the UK. With gallstones on ultrasound and minimal alcohol intake, gallstones are the likely cause. Management is supportive: fluids, analgesia and nutrition. Cholecystectomy should be done during the same admission or within 2 weeks to prevent recurrence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6b72c938-65d2-5693-abba-fd4bece3fbc4', '27cdbc51-3a94-545f-b81a-08a3fa6e192c', 'A', 'Alcohol', false, 0),
  ('1a9c28ed-4eb1-5f3c-8d03-6f35f865a0aa', '27cdbc51-3a94-545f-b81a-08a3fa6e192c', 'B', 'Post-ERCP', false, 1),
  ('c187e066-3bcd-5482-b854-2a11f1df9ffd', '27cdbc51-3a94-545f-b81a-08a3fa6e192c', 'C', 'Drug-induced', false, 2),
  ('fb8ba615-06e6-5bd8-83e2-3adf322c4aa3', '27cdbc51-3a94-545f-b81a-08a3fa6e192c', 'D', 'Hypertriglyceridaemia', false, 3),
  ('8843ea19-6cc5-501c-9f57-4c3691839f1d', '27cdbc51-3a94-545f-b81a-08a3fa6e192c', 'E', 'Gallstones', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ae911382-e236-5ac9-9ef8-12b2adc980d1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 24 year old woman presents with 3 months of bloody diarrhoea, 6 times a day, with urgency and tenesmus. She is a non-smoker. Colonoscopy shows continuous inflammation from the rectum extending to the splenic flexure, and biopsies show crypt abscesses and mucosal inflammation without granulomas. What is the SINGLE most likely diagnosis?', 'Ulcerative colitis causes continuous mucosal inflammation that starts in the rectum and extends proximally, with crypt abscesses and no granulomas, and typically presents with bloody diarrhoea. Smoking is protective against UC but a risk factor for Crohn''s. Crohn''s disease causes skip lesions anywhere from mouth to anus, transmural inflammation and non-caseating granulomas. First-line induction for mild-moderate UC is an aminosalicylate such as mesalazine.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7aa07f7d-173d-5f60-8680-d4a58e470fc9', 'ae911382-e236-5ac9-9ef8-12b2adc980d1', 'A', 'Crohn''s disease', false, 0),
  ('7d9cf26f-666e-5ebc-998f-1ff658f5a3c5', 'ae911382-e236-5ac9-9ef8-12b2adc980d1', 'B', 'Microscopic colitis', false, 1),
  ('ecd93592-be0c-5b8c-9431-ede96e160837', 'ae911382-e236-5ac9-9ef8-12b2adc980d1', 'C', 'Coeliac disease', false, 2),
  ('aa748b19-5482-58b8-bda3-539db7acbe71', 'ae911382-e236-5ac9-9ef8-12b2adc980d1', 'D', 'Irritable bowel syndrome', false, 3),
  ('8c175ce1-6479-52f0-b40d-9c0e550fef19', 'ae911382-e236-5ac9-9ef8-12b2adc980d1', 'E', 'Ulcerative colitis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dfbb9905-bd85-54f8-a62f-e274c17256e2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 19 year old man presents with 18 hours of abdominal pain that began around the umbilicus and has moved to the right iliac fossa. He has anorexia and nausea. His temperature is 37.9°C. There is tenderness and guarding at McBurney''s point, and pressing the left iliac fossa causes pain in the right iliac fossa. WCC is 15 x 10^9/L. What is the SINGLE most appropriate management?', 'Periumbilical pain migrating to the RIF, anorexia, low-grade fever, RIF peritonism, a positive Rovsing''s sign and raised inflammatory markers are classic for acute appendicitis. In a young man with a typical picture, laparoscopic appendicectomy is standard. Imaging (ultrasound in children and young women, CT in older adults) helps when the diagnosis is uncertain. He should have IV antibiotics and analgesia before surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('40d69d11-54d7-5ebc-b2fe-73a6baea285a', 'dfbb9905-bd85-54f8-a62f-e274c17256e2', 'A', 'Laparotomy as first-line', false, 0),
  ('445e8722-0b20-5d16-96d2-5f00dfe3cba5', 'dfbb9905-bd85-54f8-a62f-e274c17256e2', 'B', 'Laparoscopic appendicectomy', true, 1),
  ('bda3fd18-a4f1-5df6-bef3-67285ee6bbc6', 'dfbb9905-bd85-54f8-a62f-e274c17256e2', 'C', 'Oral antibiotics and discharge', false, 2),
  ('f13e16af-84be-53c3-816b-4e6f5aa3acb6', 'dfbb9905-bd85-54f8-a62f-e274c17256e2', 'D', 'Colonoscopy', false, 3),
  ('059bf407-7001-5106-b3c7-81622e4f1209', 'dfbb9905-bd85-54f8-a62f-e274c17256e2', 'E', 'Watchful waiting at home', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c8482c08-5649-5963-82e5-34c7e556bf8e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 46 year old woman presents with 24 hours of constant right upper quadrant pain, fever of 38.4°C and vomiting. She stops inspiring during palpation of the right upper quadrant. She is not jaundiced. Her WCC is 16 x 10^9/L, and bilirubin and ALP are normal. What is the SINGLE most appropriate first-line imaging?', 'RUQ pain with fever, raised WCC and a positive Murphy''s sign suggests acute cholecystitis. Ultrasound is first-line and shows gallstones, a thickened gallbladder wall and pericholecystic fluid. Treatment is IV antibiotics and early laparoscopic cholecystectomy (within 1 week). MRCP is used if common bile duct stones are suspected and ultrasound is inconclusive. ERCP is therapeutic for CBD stones or cholangitis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('84422917-34dd-53cd-800b-7241d16fd871', 'c8482c08-5649-5963-82e5-34c7e556bf8e', 'A', 'ERCP', false, 0),
  ('cf5c393c-4c4c-5f93-94e6-8b99667c78cc', 'c8482c08-5649-5963-82e5-34c7e556bf8e', 'B', 'CT abdomen', false, 1),
  ('ef0ff231-a87a-51cf-96c2-98f1f26148d5', 'c8482c08-5649-5963-82e5-34c7e556bf8e', 'C', 'Plain abdominal X-ray', false, 2),
  ('89263bac-1af7-52a2-9d71-8b4ea7f218c7', 'c8482c08-5649-5963-82e5-34c7e556bf8e', 'D', 'MRCP', false, 3),
  ('a58f28ae-ba99-50f7-b91d-9920d8ba2e35', 'c8482c08-5649-5963-82e5-34c7e556bf8e', 'E', 'Abdominal ultrasound', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('adac1d35-3f9a-5691-8174-bfcb6a448cde', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 38 year old man has 2 months of epigastric discomfort after meals. He has no weight loss, dysphagia, vomiting, GI bleeding or anaemia. He takes no NSAIDs. A month of lifestyle advice and antacids has not helped. What is the SINGLE most appropriate next step?', 'For uninvestigated dyspepsia without alarm features in a patient under 55, NICE recommends either a full-dose PPI for 1 month or a ''test and treat'' approach for H. pylori. The urea breath test or stool antigen test is preferred. A PPI must be stopped for 2 weeks (and antibiotics for 4 weeks) before testing to avoid false negatives. Serology is not recommended because it cannot distinguish current from past infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8f28affa-5faf-53c5-a2f7-236cebeec11c', 'adac1d35-3f9a-5691-8174-bfcb6a448cde', 'A', 'Serum H. pylori antibody test', false, 0),
  ('20ed2c38-1020-5df6-9059-141019f2ad2e', 'adac1d35-3f9a-5691-8174-bfcb6a448cde', 'B', 'Urgent 2-week-wait upper GI endoscopy', false, 1),
  ('d0a8d250-f1ea-552a-a4b6-4db4014c2073', 'adac1d35-3f9a-5691-8174-bfcb6a448cde', 'C', 'Test for Helicobacter pylori (carbon-13 urea breath test or stool antigen) after a 2-week PPI washout', true, 2),
  ('f1cf3b95-5152-5734-999c-ed886ea60517', 'adac1d35-3f9a-5691-8174-bfcb6a448cde', 'D', 'Barium swallow', false, 3),
  ('532507e5-d3d2-5494-8410-02600fe60e3e', 'adac1d35-3f9a-5691-8174-bfcb6a448cde', 'E', 'Lifelong full-dose PPI without testing', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ad04beaf-723b-5a02-8ca5-1c724cf40f6f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 29 year old man has routine blood tests before starting a new job in healthcare. His hepatitis B results are: HBsAg negative, anti-HBc negative and anti-HBs positive. He has no symptoms. What is the SINGLE most likely interpretation?', 'Anti-HBs alone, with negative anti-HBc, means immunity from vaccination, because the vaccine contains only surface antigen. Anti-HBc (to the core antigen) appears only after natural infection. Positive anti-HBc and anti-HBs with negative HBsAg means past infection that has cleared. HBsAg persisting for over 6 months means chronic infection, and IgM anti-HBc means acute infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4d282952-b026-5932-9c3c-41c74e23f5ba', 'ad04beaf-723b-5a02-8ca5-1c724cf40f6f', 'A', 'Immunity from vaccination', true, 0),
  ('916da8aa-3edc-5d55-b614-5130387b6d4d', 'ad04beaf-723b-5a02-8ca5-1c724cf40f6f', 'B', 'Chronic hepatitis B infection', false, 1),
  ('7eb8cd30-f041-511b-850e-ec622a026337', 'ad04beaf-723b-5a02-8ca5-1c724cf40f6f', 'C', 'Acute hepatitis B infection', false, 2),
  ('fe526beb-d6b2-523f-a20e-10031759f1d0', 'ad04beaf-723b-5a02-8ca5-1c724cf40f6f', 'D', 'Immunity from past natural infection', false, 3),
  ('84731f69-cff7-5579-a619-5a5a7899d50b', 'ad04beaf-723b-5a02-8ca5-1c724cf40f6f', 'E', 'Susceptible, never infected or vaccinated', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e12ef45b-206f-5212-921e-e73bb34a23b8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 79 year old woman on a care-of-the-elderly ward develops profuse watery diarrhoea 5 days after starting co-amoxiclav for a chest infection. Stool testing is positive for Clostridioides difficile toxin. She is clinically stable, her WCC is 12 x 10^9/L and creatinine is at baseline. What is the SINGLE most appropriate first-line treatment?', 'NICE (NG199) recommends oral vancomycin 125 mg four times a day for 10 days for a first episode of C. difficile infection, with oral fidaxomicin as second-line. The causative antibiotic should be stopped if possible, and antimotility drugs such as loperamide avoided. IV vancomycin does not reach the colon. She should be isolated with contact precautions and hand-washing with soap and water, because alcohol gel does not kill spores.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cf960614-d2fc-5ccd-ab9f-c8b337e9449b', 'e12ef45b-206f-5212-921e-e73bb34a23b8', 'A', 'IV vancomycin', false, 0),
  ('32e0736a-1a34-5a9a-b4a5-ac67ebfaab74', 'e12ef45b-206f-5212-921e-e73bb34a23b8', 'B', 'IV metronidazole alone', false, 1),
  ('ef50cd88-5e58-556a-a728-3ea3120a3fc4', 'e12ef45b-206f-5212-921e-e73bb34a23b8', 'C', 'Oral vancomycin for 10 days', true, 2),
  ('bc799321-2afb-5736-976c-57cf071c93f8', 'e12ef45b-206f-5212-921e-e73bb34a23b8', 'D', 'Oral co-amoxiclav for a further 7 days', false, 3),
  ('a17b0276-eba9-5f01-a272-1b59dcb6d5f4', 'e12ef45b-206f-5212-921e-e73bb34a23b8', 'E', 'Oral loperamide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d31fdda6-5b05-5b11-83cf-6b18fceda27e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 48 year old man has had heartburn and acid regurgitation for 4 months, worse when lying down. He has no dysphagia, weight loss, anaemia or vomiting. What is the SINGLE most appropriate initial management?', 'Uncomplicated GORD without alarm features is managed with lifestyle advice (weight loss, stopping smoking, raising the head of the bed, avoiding late meals) and a full-dose PPI for 4-8 weeks, then stepping down to the lowest effective dose. Endoscopy is for alarm features or when treatment fails. Fundoplication is for refractory disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('38780280-dc70-5ec3-a5c9-e7dcd4757ad7', 'd31fdda6-5b05-5b11-83cf-6b18fceda27e', 'A', 'Urgent endoscopy', false, 0),
  ('78b0765b-b45c-56f8-be3e-0052474b8ca2', 'd31fdda6-5b05-5b11-83cf-6b18fceda27e', 'B', 'Barium swallow', false, 1),
  ('c9c943ae-7988-5f26-93f1-791e95159179', 'd31fdda6-5b05-5b11-83cf-6b18fceda27e', 'C', 'Lifelong H2 blocker without review', false, 2),
  ('a8de1f98-db5c-5eb1-b4cd-6ca8235c1700', 'd31fdda6-5b05-5b11-83cf-6b18fceda27e', 'D', 'Full-dose PPI for 4-8 weeks with lifestyle advice', true, 3),
  ('085ad82e-169f-5cb0-a537-3ee6e94e8182', 'd31fdda6-5b05-5b11-83cf-6b18fceda27e', 'E', 'Fundoplication', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d463d526-e89c-5fc1-905d-a21313eabf0a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 58 year old man has had worsening dysphagia for 3 months, first for solids and now for liquids. He has lost 7 kg. He has smoked for 40 years. What is the SINGLE most appropriate action?', 'Progressive dysphagia (solids then liquids) with weight loss suggests oesophageal cancer. NICE recommends urgent direct-access upper GI endoscopy (suspected cancer pathway) for anyone with dysphagia, or for people aged 55 and over with weight loss plus upper abdominal pain, reflux or dyspepsia. Squamous cell carcinoma is linked to smoking and alcohol, and adenocarcinoma to Barrett''s oesophagus.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('410f8e5b-deb7-5d19-a297-ac6f2a64e631', 'd463d526-e89c-5fc1-905d-a21313eabf0a', 'A', 'Trial of PPI for 8 weeks', false, 0),
  ('4538cd35-e408-501f-a6ae-1c710ad3e4c7', 'd463d526-e89c-5fc1-905d-a21313eabf0a', 'B', 'Speech therapy assessment', false, 1),
  ('2537a792-cc34-5542-8bc8-a45e3020047a', 'd463d526-e89c-5fc1-905d-a21313eabf0a', 'C', 'Barium swallow in 3 months', false, 2),
  ('51691a83-b631-5ae6-8e42-01b0bea11bdf', 'd463d526-e89c-5fc1-905d-a21313eabf0a', 'D', 'Reassure', false, 3),
  ('bc1e172b-3d7d-56eb-a4fa-ca915bf1790d', 'd463d526-e89c-5fc1-905d-a21313eabf0a', 'E', 'Suspected cancer pathway referral for urgent upper GI endoscopy (within 2 weeks)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9ecde107-f815-55ac-aa91-111cb43f835f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 34 year old woman has had dysphagia for both solids and liquids from the start, for 1 year, with regurgitation of undigested food and weight loss. A barium swallow shows a dilated oesophagus tapering to a ''bird''s beak''. What is the SINGLE most appropriate investigation to confirm the diagnosis?', 'Achalasia is failure of the lower oesophageal sphincter to relax, with absent peristalsis. It causes dysphagia for both solids and liquids from onset, and regurgitation. Manometry (high resolution) is diagnostic. Endoscopy is needed to exclude pseudoachalasia from a tumour at the cardia. Treatment is pneumatic dilatation, Heller myotomy, POEM or botulinum toxin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ea68c41d-834f-5937-bf0f-7c7f90d03af1', '9ecde107-f815-55ac-aa91-111cb43f835f', 'A', 'Upper GI endoscopy only', false, 0),
  ('8869d395-e152-534d-b76f-79f0a9e0803d', '9ecde107-f815-55ac-aa91-111cb43f835f', 'B', 'Chest X-ray', false, 1),
  ('b524d454-5265-5771-9897-fef1f8e602ad', '9ecde107-f815-55ac-aa91-111cb43f835f', 'C', 'pH monitoring', false, 2),
  ('a5d6d7c6-8b93-5948-8778-e648cef57baf', '9ecde107-f815-55ac-aa91-111cb43f835f', 'D', 'Oesophageal manometry', true, 3),
  ('0aa4e27e-19af-5ed6-bbc3-32bf6766cbe4', '9ecde107-f815-55ac-aa91-111cb43f835f', 'E', 'CT chest', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('08e322fa-2aa5-50d1-be44-2e5fa3d4a1b7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 55 year old man with long-standing reflux has an endoscopy showing salmon-pink mucosa extending 4 cm above the gastro-oesophageal junction. Biopsy confirms intestinal metaplasia without dysplasia. What is the SINGLE most appropriate management?', 'Barrett''s oesophagus is metaplasia from squamous to columnar epithelium caused by chronic reflux, and it is a precursor to adenocarcinoma. Without dysplasia, it is managed with a PPI and endoscopic surveillance (interval depends on length: every 2-3 years for 3 cm or more). Dysplasia is treated with endoscopic resection and/or radiofrequency ablation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7d64bbe6-ba90-5dee-a842-7d7e4c8e8752', '08e322fa-2aa5-50d1-be44-2e5fa3d4a1b7', 'A', 'Oesophagectomy', false, 0),
  ('9ce3b49c-c4b8-551f-977f-e3334e07b822', '08e322fa-2aa5-50d1-be44-2e5fa3d4a1b7', 'B', 'No follow-up', false, 1),
  ('5215b830-dde4-5164-badc-0fd9d30c0da2', '08e322fa-2aa5-50d1-be44-2e5fa3d4a1b7', 'C', 'Fundoplication immediately', false, 2),
  ('b508154e-d0e1-5bc3-a022-633012c0dcc9', '08e322fa-2aa5-50d1-be44-2e5fa3d4a1b7', 'D', 'High-dose PPI and endoscopic surveillance every 2-3 years', true, 3),
  ('514c680d-8c48-5590-bb87-557fd4c7261c', '08e322fa-2aa5-50d1-be44-2e5fa3d4a1b7', 'E', 'Radiofrequency ablation for all', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('010c99f4-ee4b-5163-b05b-81652f78d474', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 72 year old man has had melaena and vomited blood once. He takes naproxen for osteoarthritis. His heart rate is 110 beats/minute, BP 104/70 mmHg and urea 18 mmol/L. His Glasgow-Blatchford score is high. After resuscitation, what is the SINGLE most appropriate timing of endoscopy?', 'NICE recommends endoscopy within 24 hours for all patients with acute upper GI bleeding, and immediately after resuscitation for unstable patients with severe bleeding. A PPI is given after endoscopy (not before). The Glasgow-Blatchford score helps identify low-risk patients (score 0) who may be managed as outpatients. NSAIDs should be stopped.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('354b9677-3c6d-550e-a88f-11d3c1ff4ecd', '010c99f4-ee4b-5163-b05b-81652f78d474', 'A', 'Not needed if he is stable', false, 0),
  ('6a9311e1-0b0c-537a-8da6-2487f3087f94', '010c99f4-ee4b-5163-b05b-81652f78d474', 'B', 'Within 24 hours of admission (immediately after resuscitation if unstable)', true, 1),
  ('b3c5dc09-abbe-5bbd-aca4-27d1dcf2270b', '010c99f4-ee4b-5163-b05b-81652f78d474', 'C', 'Within 1 week as an outpatient', false, 2),
  ('0725d403-c013-5932-b73a-0a6953ca1fcc', '010c99f4-ee4b-5163-b05b-81652f78d474', 'D', 'Only if he rebleeds', false, 3),
  ('68692b9a-a14d-5dd7-bdb4-bf67f6e24b67', '010c99f4-ee4b-5163-b05b-81652f78d474', 'E', 'Within 6 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('05bdbc66-5f60-58e4-871c-3fbe7dcf06ac', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 34 year old woman has had recurrent abdominal pain relieved by defecation, bloating and alternating constipation and diarrhoea for 9 months. She has no weight loss, rectal bleeding or anaemia. Her FBC, CRP, coeliac serology and faecal calprotectin are normal. What is the SINGLE most likely diagnosis?', 'IBS is diagnosed by abdominal pain or discomfort relieved by defecation, or associated with altered stool frequency or form, with at least two of: altered passage, bloating, worse after eating or mucus. Red flags must be excluded. Management is diet (regular meals, fibre adjustment, low FODMAP with a dietitian), antispasmodics, laxatives (not lactulose) or loperamide, and low-dose TCAs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7ad2e04d-4eb6-5239-b73c-434975fea573', '05bdbc66-5f60-58e4-871c-3fbe7dcf06ac', 'A', 'Coeliac disease', false, 0),
  ('18ff4275-94b2-59ee-8d56-b50415d06736', '05bdbc66-5f60-58e4-871c-3fbe7dcf06ac', 'B', 'Irritable bowel syndrome', true, 1),
  ('ca4c269f-0622-514e-94b6-aa18cdd9129e', '05bdbc66-5f60-58e4-871c-3fbe7dcf06ac', 'C', 'Colorectal cancer', false, 2),
  ('018da96a-9a3e-553c-8441-403423f86921', '05bdbc66-5f60-58e4-871c-3fbe7dcf06ac', 'D', 'Crohn''s disease', false, 3),
  ('f63a4a83-762c-5df7-963b-e375b4a4a0d0', '05bdbc66-5f60-58e4-871c-3fbe7dcf06ac', 'E', 'Ulcerative colitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f3cfde20-5c36-562c-9e10-7ab12655f96c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 24 year old man has had right iliac fossa pain, diarrhoea without blood, weight loss and mouth ulcers for 3 months. He smokes. Colonoscopy shows skip lesions with cobblestoning in the terminal ileum. Biopsy shows transmural inflammation with non-caseating granulomas. What is the SINGLE most appropriate first-line treatment to induce remission?', 'Crohn''s disease affects anywhere from mouth to anus with skip lesions and transmural granulomatous inflammation, most often in the terminal ileum. NICE recommends a conventional glucocorticoid to induce remission of a first presentation or single flare. Budesonide is an option for distal ileal or right colon disease. Azathioprine or mercaptopurine maintains remission. Stopping smoking is very important.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('04ebf08f-261c-5721-aa33-ddf82056bee8', 'f3cfde20-5c36-562c-9e10-7ab12655f96c', 'A', 'Oral mesalazine as monotherapy', false, 0),
  ('baea97d0-a8e2-5794-860e-fc4effba244e', 'f3cfde20-5c36-562c-9e10-7ab12655f96c', 'B', 'Oral corticosteroid (prednisolone)', true, 1),
  ('b5dfdaaf-5989-5131-add9-a6a5ff381799', 'f3cfde20-5c36-562c-9e10-7ab12655f96c', 'C', 'Oral azathioprine alone', false, 2),
  ('2af19cd9-bf5a-5f34-92f7-071c2536b44e', 'f3cfde20-5c36-562c-9e10-7ab12655f96c', 'D', 'Surgical resection as first-line', false, 3),
  ('6037f685-dd77-585a-8834-d5cf24f86f98', 'f3cfde20-5c36-562c-9e10-7ab12655f96c', 'E', 'Oral antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c386d8ec-56ad-5c16-92da-e1a04fc5f4b9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 32 year old woman with known ulcerative colitis has 9 bloody stools a day, a heart rate of 104 beats/minute, a temperature of 38°C, Hb 98 g/L and CRP 85 mg/L. What is the SINGLE most appropriate management?', 'Truelove and Witts criteria: 6 or more bloody stools a day plus systemic toxicity (HR over 90, temperature over 37.8°C, Hb under 105, ESR over 30) indicate acute severe UC. She needs admission, IV hydrocortisone, LMWH (VTE risk), stool cultures and an abdominal X-ray for toxic megacolon. If there is no response at 72 hours, ciclosporin, infliximab or colectomy is considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ca1aae2b-d39b-50bc-ac6f-20d802233f7c', 'c386d8ec-56ad-5c16-92da-e1a04fc5f4b9', 'A', 'Admit for IV corticosteroids (hydrocortisone) and VTE prophylaxis', true, 0),
  ('d3a0f6df-326a-5c67-a306-15daedc8d9b3', 'c386d8ec-56ad-5c16-92da-e1a04fc5f4b9', 'B', 'Immediate colectomy without medical treatment', false, 1),
  ('219da05b-fbdc-5e7f-b719-a99d148559b1', 'c386d8ec-56ad-5c16-92da-e1a04fc5f4b9', 'C', 'Oral loperamide', false, 2),
  ('de94859a-25a8-5cc8-a102-24c02ce847d0', 'c386d8ec-56ad-5c16-92da-e1a04fc5f4b9', 'D', 'Oral antibiotics and discharge', false, 3),
  ('8896e798-e763-5add-bebd-6692893e0410', 'c386d8ec-56ad-5c16-92da-e1a04fc5f4b9', 'E', 'Oral mesalazine at home', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cde8a89c-86ab-5560-b3aa-fd33c3524de2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 54 year old woman has had itching and fatigue for 6 months. Her ALP is raised with normal ALT. Anti-mitochondrial antibodies (M2 subtype) are positive. Ultrasound shows normal bile ducts. What is the SINGLE most appropriate treatment?', 'Primary biliary cholangitis is autoimmune destruction of the small intrahepatic bile ducts, mainly in middle-aged women. It causes pruritus, fatigue, raised ALP and positive AMA. First-line treatment is ursodeoxycholic acid. Colestyramine helps the itch. Patients need monitoring for osteoporosis and fat-soluble vitamin deficiency. Liver transplantation is for end-stage disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('311327f3-d46b-5be1-bb26-f3c6dccb859b', 'cde8a89c-86ab-5560-b3aa-fd33c3524de2', 'A', 'Prednisolone', false, 0),
  ('a314bade-a110-550f-a2ca-5612a7dd20d5', 'cde8a89c-86ab-5560-b3aa-fd33c3524de2', 'B', 'Cholecystectomy', false, 1),
  ('53c1edf0-d5d4-5a4e-bbdf-d3f22fd3a6b1', 'cde8a89c-86ab-5560-b3aa-fd33c3524de2', 'C', 'Ursodeoxycholic acid', true, 2),
  ('84b0dd4d-a8ab-58f5-993e-9c64e1ada2df', 'cde8a89c-86ab-5560-b3aa-fd33c3524de2', 'D', 'ERCP and stenting', false, 3),
  ('0f1f5c28-540c-5a47-a168-4cd8fc28b877', 'cde8a89c-86ab-5560-b3aa-fd33c3524de2', 'E', 'Interferon', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cee83e8f-9793-519d-bf91-4df39ea6fe0b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 32 year old man with ulcerative colitis has had abnormal LFTs on routine blood tests, with a raised ALP. MRCP shows multifocal strictures and dilatation of the intrahepatic and extrahepatic bile ducts (''beaded'' appearance). What is the SINGLE most likely diagnosis?', 'Primary sclerosing cholangitis is strongly associated with UC (about 80% have IBD). It causes inflammation and fibrosis of the intra- and extrahepatic bile ducts, giving a beaded appearance on MRCP. It increases the risk of cholangiocarcinoma and colorectal cancer, so annual colonoscopy is needed. There is no proven medical treatment, and transplantation is for end-stage disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cdd2856e-d73a-5c7c-99f5-148758f1781d', 'cee83e8f-9793-519d-bf91-4df39ea6fe0b', 'A', 'Primary biliary cholangitis', false, 0),
  ('67634cf7-3b77-5f30-95cf-3768fc63a68a', 'cee83e8f-9793-519d-bf91-4df39ea6fe0b', 'B', 'Cholangiocarcinoma only', false, 1),
  ('f909616d-f547-5338-918b-06706532681f', 'cee83e8f-9793-519d-bf91-4df39ea6fe0b', 'C', 'Choledocholithiasis', false, 2),
  ('42f3256a-038f-54a2-9222-e6fd9708db26', 'cee83e8f-9793-519d-bf91-4df39ea6fe0b', 'D', 'Primary sclerosing cholangitis', true, 3),
  ('44614f54-cbe2-50f3-af9a-51ea11a78b91', 'cee83e8f-9793-519d-bf91-4df39ea6fe0b', 'E', 'Autoimmune hepatitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('41d640fa-5c83-5b7e-9c63-b86a39c0411b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 50 year old man has diabetes, fatigue and raised LFTs. His skin looks bronzed and he has arthritis in his second and third MCP joints. His serum ferritin is 1,800 micrograms/L and transferrin saturation is 72%. What is the SINGLE most appropriate treatment?', 'Hereditary haemochromatosis (usually HFE C282Y homozygosity, autosomal recessive) causes iron overload, leading to liver cirrhosis, diabetes (''bronze diabetes''), skin pigmentation, arthropathy, cardiomyopathy and hypogonadism. A raised transferrin saturation and ferritin, then genetic testing, confirm it. First-line treatment is regular venesection, with ferritin monitoring. First-degree relatives should be screened.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('97d9a159-2a3a-5871-bf2d-2a384681679c', '41d640fa-5c83-5b7e-9c63-b86a39c0411b', 'A', 'Iron supplements', false, 0),
  ('cb910613-281c-55d7-96e8-ea928f494825', '41d640fa-5c83-5b7e-9c63-b86a39c0411b', 'B', 'Venesection', true, 1),
  ('14f83dba-bbbf-5b39-9e76-04582bac82c3', '41d640fa-5c83-5b7e-9c63-b86a39c0411b', 'C', 'Ursodeoxycholic acid', false, 2),
  ('867363cd-4b8c-535c-ab7d-54084b626634', '41d640fa-5c83-5b7e-9c63-b86a39c0411b', 'D', 'Penicillamine', false, 3),
  ('5467bf26-c37d-527a-911b-0a5f745005c3', '41d640fa-5c83-5b7e-9c63-b86a39c0411b', 'E', 'Desferrioxamine as first-line', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f4ad4998-a9e8-501e-bfea-72c4784904e2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 45 year old man with alcohol-related liver disease has abdominal distension. Shifting dullness is present. A diagnostic ascitic tap shows a serum-ascites albumin gradient (SAAG) of 15 g/L and a neutrophil count of 380 cells/mm3. He has a mild fever and abdominal discomfort. What is the SINGLE most appropriate treatment?', 'An ascitic neutrophil count over 250 cells/mm3 indicates spontaneous bacterial peritonitis. Treatment is IV antibiotics (such as cefotaxime or piperacillin-tazobactam per local policy) and IV albumin to reduce hepatorenal syndrome. A SAAG of 11 g/L or more indicates portal hypertension. After SBP, long-term prophylaxis with ciprofloxacin or co-trimoxazole is given.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4affce18-5e90-5b99-b3e3-3f7517c6b1d2', 'f4ad4998-a9e8-501e-bfea-72c4784904e2', 'A', 'Large-volume paracentesis only', false, 0),
  ('4fee2de5-2e94-5160-a5ee-0f60ceb48948', 'f4ad4998-a9e8-501e-bfea-72c4784904e2', 'B', 'Spironolactone only', false, 1),
  ('bc49cfd1-514c-50d3-970f-b8fcf83d27e0', 'f4ad4998-a9e8-501e-bfea-72c4784904e2', 'C', 'Oral metronidazole', false, 2),
  ('f1287136-cc20-56b9-b9b6-e8b19ee824e2', 'f4ad4998-a9e8-501e-bfea-72c4784904e2', 'D', 'IV antibiotics (such as a third-generation cephalosporin) for spontaneous bacterial peritonitis', true, 3),
  ('1cb97aa1-8bf6-530d-9faa-e1b08ab7e198', 'f4ad4998-a9e8-501e-bfea-72c4784904e2', 'E', 'Emergency laparotomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('935166a9-0fa3-5b8b-af3a-2b512bb4190c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 58 year old woman with cirrhosis is confused and drowsy. She has a flapping tremor (asterixis). She has been constipated for 4 days. Her blood glucose is normal. What is the SINGLE most appropriate first-line treatment?', 'Hepatic encephalopathy is triggered by constipation, infection, GI bleeding, electrolyte disturbance, sedatives and dehydration. Lactulose reduces ammonia absorption and is first-line, with rifaximin added to prevent recurrence. Sedatives should be avoided. Protein restriction is no longer recommended. A full septic screen is needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('97876ed9-8d7f-53f9-987b-ac8a6bd13050', '935166a9-0fa3-5b8b-af3a-2b512bb4190c', 'A', 'Oral metronidazole as first-line', false, 0),
  ('da601575-5008-5708-9900-148fceb6903d', '935166a9-0fa3-5b8b-af3a-2b512bb4190c', 'B', 'Lactulose (aiming for 2-3 soft stools a day), plus treating the precipitant', true, 1),
  ('bf11569e-ef24-5560-9075-bb20ee7fbfaf', '935166a9-0fa3-5b8b-af3a-2b512bb4190c', 'C', 'Protein-free diet', false, 2),
  ('fc1f6119-90ef-5784-8817-70a10ba04328', '935166a9-0fa3-5b8b-af3a-2b512bb4190c', 'D', 'IV benzodiazepine for agitation', false, 3),
  ('bf02a86b-60b6-5a4e-a91f-f7d92bffc344', '935166a9-0fa3-5b8b-af3a-2b512bb4190c', 'E', 'Haloperidol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1c6ac5a5-54b9-5ebc-b3b9-0a568376c37d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 42 year old woman has had fatigue and jaundice for 2 months. Her ALT is 900 U/L. She has hypothyroidism and vitiligo. IgG is raised and anti-smooth muscle antibodies are positive. Viral hepatitis serology is negative. What is the SINGLE most appropriate treatment?', 'Autoimmune hepatitis mainly affects women and is associated with other autoimmune diseases. It shows raised transaminases and IgG, with ANA or anti-smooth muscle antibodies (type 1) or anti-LKM1 (type 2). Liver biopsy shows interface hepatitis. Treatment is corticosteroids with azathioprine. Most patients need long-term maintenance.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('250e641b-6023-5195-bf0f-5268486224a1', '1c6ac5a5-54b9-5ebc-b3b9-0a568376c37d', 'A', 'Ursodeoxycholic acid', false, 0),
  ('78c58a55-c214-5fd3-8031-1de62ec5aa0f', '1c6ac5a5-54b9-5ebc-b3b9-0a568376c37d', 'B', 'Interferon alfa', false, 1),
  ('7ae53c46-4387-5302-9018-350c13484888', '1c6ac5a5-54b9-5ebc-b3b9-0a568376c37d', 'C', 'Venesection', false, 2),
  ('29517d7f-7737-5b32-8a89-de6fd0eaa3cb', '1c6ac5a5-54b9-5ebc-b3b9-0a568376c37d', 'D', 'Penicillamine', false, 3),
  ('8af7223b-876f-5deb-88eb-7d1cd1abf9f7', '1c6ac5a5-54b9-5ebc-b3b9-0a568376c37d', 'E', 'Prednisolone (with azathioprine)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7de20cf0-67c4-5792-9619-b59591cd6a2a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 40 year old man has had a raised ALT for 6 months. He has type 2 diabetes and a BMI of 34 kg/m2. He drinks 6 units of alcohol a week. Ultrasound shows a bright, fatty liver. Viral and autoimmune screens are negative. What is the SINGLE most appropriate next step?', 'NAFLD (now termed MASLD) is the commonest cause of abnormal LFTs, linked to metabolic syndrome. NICE recommends assessing fibrosis with non-invasive tests (FIB-4, then an ELF test or FibroScan) to find advanced fibrosis needing specialist referral. Management is weight loss, exercise and cardiovascular risk control.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a99a10b3-c069-5b82-99c9-6add1e592743', '7de20cf0-67c4-5792-9619-b59591cd6a2a', 'A', 'Refer for liver transplant', false, 0),
  ('11e5f895-ff24-5793-8c4b-d87650a8b86d', '7de20cf0-67c4-5792-9619-b59591cd6a2a', 'B', 'Liver biopsy for all', false, 1),
  ('5d7baa45-3494-583f-aa6e-da63a77eed3d', '7de20cf0-67c4-5792-9619-b59591cd6a2a', 'C', 'Start ursodeoxycholic acid', false, 2),
  ('0e3c20fd-b2bf-5771-bb9f-549188a50483', '7de20cf0-67c4-5792-9619-b59591cd6a2a', 'D', 'Reassure; no follow-up', false, 3),
  ('897942df-f068-500f-8c08-cded5d00a1a5', '7de20cf0-67c4-5792-9619-b59591cd6a2a', 'E', 'Calculate a FIB-4 score (and ELF test if indeterminate) to assess for advanced fibrosis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('847cdafc-c033-56bd-b9bf-659f3429230f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 31 year old man has had fever, malaise, nausea and dark urine for 1 week, followed by jaundice. He returned from Pakistan 4 weeks ago. His ALT is 2,400 U/L. What is the SINGLE most likely diagnosis?', 'Hepatitis A spreads by the faecal-oral route, often in travellers to endemic areas, with an incubation of 2-6 weeks. It causes a prodrome, then jaundice with very high transaminases. Anti-HAV IgM confirms it. It is self-limiting and never chronic, with supportive treatment. It is notifiable, and vaccination is available for travellers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('192e9564-34ab-596c-8543-5a4bb4aa50ac', '847cdafc-c033-56bd-b9bf-659f3429230f', 'A', 'Chronic hepatitis B', false, 0),
  ('6bfa6203-34bc-511f-b000-b30adddc51f7', '847cdafc-c033-56bd-b9bf-659f3429230f', 'B', 'Acute hepatitis A', true, 1),
  ('9f2752df-3ebe-5c02-96e0-0c1e7a4b46ed', '847cdafc-c033-56bd-b9bf-659f3429230f', 'C', 'Haemochromatosis', false, 2),
  ('c9b84bdb-dd36-5b4c-9fc9-87aa9b147e9c', '847cdafc-c033-56bd-b9bf-659f3429230f', 'D', 'Hepatitis C', false, 3),
  ('b6ac9e9b-f745-5c7c-af43-9fae36b0999d', '847cdafc-c033-56bd-b9bf-659f3429230f', 'E', 'Gilbert''s syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4678e592-4363-59f0-a7da-43af3f0ad310', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 35 year old man who previously injected drugs has a raised ALT. His hepatitis C antibody is positive and HCV RNA is detectable. What is the SINGLE most appropriate treatment?', 'Chronic hepatitis C is now curable in over 95% of cases with oral direct-acting antivirals (pangenotypic regimens such as sofosbuvir/velpatasvir) for 8-12 weeks. Patients should have fibrosis assessment and harm reduction advice, and be vaccinated against hepatitis A and B. There is no vaccine for HCV. Cirrhosis needs hepatocellular carcinoma surveillance.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2c61fd00-8694-5b3a-94c7-9d0e68bb8d68', '4678e592-4363-59f0-a7da-43af3f0ad310', 'A', 'No treatment; monitor only', false, 0),
  ('3ef11369-9271-5b03-90cc-f49ca82f70a9', '4678e592-4363-59f0-a7da-43af3f0ad310', 'B', 'Liver transplant', false, 1),
  ('d859b1a7-f807-5933-9990-f8cf83288829', '4678e592-4363-59f0-a7da-43af3f0ad310', 'C', 'Direct-acting antivirals (e.g. sofosbuvir-based regimen) for 8-12 weeks', true, 2),
  ('4495de3b-33fe-573a-9f89-ba51fdc452b1', '4678e592-4363-59f0-a7da-43af3f0ad310', 'D', 'Lamivudine', false, 3),
  ('ef25cb4a-cf05-52f7-8023-9ad4f17c859b', '4678e592-4363-59f0-a7da-43af3f0ad310', 'E', 'Interferon and ribavirin for 48 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6885d1a0-2199-5e65-96cd-45dfc7cc9ea1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 18 year old man is mildly jaundiced during a bout of flu and after a period of fasting. He is otherwise well. His bilirubin is 48 micromol/L (unconjugated). LFTs, FBC, reticulocytes and blood film are normal. What is the SINGLE most likely diagnosis?', 'Gilbert''s syndrome is a common benign condition with reduced UDP-glucuronyl transferase activity, causing mild unconjugated hyperbilirubinaemia during fasting, illness or exercise. Other LFTs and haemolysis screens are normal. No treatment is needed apart from reassurance.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cc029d51-7aac-5f06-9ad5-421aff18d62b', '6885d1a0-2199-5e65-96cd-45dfc7cc9ea1', 'A', 'Hepatitis A', false, 0),
  ('986ae6e0-9743-5cb6-b2ee-28c46331d1b8', '6885d1a0-2199-5e65-96cd-45dfc7cc9ea1', 'B', 'Gilbert''s syndrome', true, 1),
  ('61c3df46-cae6-5aba-976e-d26da84f0408', '6885d1a0-2199-5e65-96cd-45dfc7cc9ea1', 'C', 'Haemolytic anaemia', false, 2),
  ('98c697d0-c4e7-5e5f-913f-b72365a08427', '6885d1a0-2199-5e65-96cd-45dfc7cc9ea1', 'D', 'Dubin-Johnson syndrome', false, 3),
  ('10659090-3ed9-5b23-ad45-ffe272cb594b', '6885d1a0-2199-5e65-96cd-45dfc7cc9ea1', 'E', 'Crigler-Najjar syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e14ff7f5-7a30-5a91-8b7f-455d5498c9c8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 67 year old man with cirrhosis attends for routine surveillance. Ultrasound shows a new 3 cm liver lesion. Alpha-fetoprotein is markedly raised. What is the SINGLE most likely diagnosis?', 'HCC usually develops in cirrhosis (hepatitis B or C, alcohol, NAFLD, haemochromatosis). People with cirrhosis are offered 6-monthly ultrasound, with or without AFP, for surveillance. Diagnosis is by multiphase contrast CT or MRI (arterial enhancement with washout). Treatment options include resection, transplant, ablation and TACE.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('38fe9260-1829-52bc-b4b8-9d7c393456c9', 'e14ff7f5-7a30-5a91-8b7f-455d5498c9c8', 'A', 'Liver abscess', false, 0),
  ('3a167788-ecc3-5f33-a0ab-f821964131a4', 'e14ff7f5-7a30-5a91-8b7f-455d5498c9c8', 'B', 'Focal nodular hyperplasia', false, 1),
  ('918f0e08-ca11-5efc-8306-9c2042760a36', 'e14ff7f5-7a30-5a91-8b7f-455d5498c9c8', 'C', 'Simple liver cyst', false, 2),
  ('958dfc67-ae4b-5933-993b-e464dfeada94', 'e14ff7f5-7a30-5a91-8b7f-455d5498c9c8', 'D', 'Hepatocellular carcinoma', true, 3),
  ('9074ba28-4e3f-5baa-ba05-162534892bed', 'e14ff7f5-7a30-5a91-8b7f-455d5498c9c8', 'E', 'Haemangioma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('627149b7-287f-5ef0-a2da-eac54e0d2ebc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 76 year old woman has had diarrhoea and abdominal pain for 6 months. She has had chronic watery diarrhoea and takes lansoprazole and sertraline. Colonoscopy is macroscopically normal, but biopsies show a thickened subepithelial collagen band. What is the SINGLE most likely diagnosis?', 'Microscopic colitis (collagenous or lymphocytic) causes chronic watery diarrhoea in older women. The colon looks normal but biopsies are abnormal. It is linked to drugs (PPIs, NSAIDs, SSRIs) and autoimmune disease. Management is stopping triggers and oral budesonide.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dcba36d8-c2af-55b4-b879-65ee4bc94279', '627149b7-287f-5ef0-a2da-eac54e0d2ebc', 'A', 'Irritable bowel syndrome', false, 0),
  ('4a9be36d-73bd-5974-b716-e7a8ee06938e', '627149b7-287f-5ef0-a2da-eac54e0d2ebc', 'B', 'Microscopic (collagenous) colitis', true, 1),
  ('6adffdc6-0608-5466-bfca-139da2b91fe7', '627149b7-287f-5ef0-a2da-eac54e0d2ebc', 'C', 'Ischaemic colitis', false, 2),
  ('cc39147b-a83f-5671-a7c3-8f85c1e0169b', '627149b7-287f-5ef0-a2da-eac54e0d2ebc', 'D', 'Ulcerative colitis', false, 3),
  ('f33007d1-3525-5047-9dbc-5ae905aa75e8', '627149b7-287f-5ef0-a2da-eac54e0d2ebc', 'E', 'Colorectal cancer', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c41449be-a401-5fd2-b8f5-b272aab1b3e5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 70 year old woman has had sudden left-sided abdominal pain and bloody diarrhoea after an episode of hypotension. Colonoscopy shows patchy mucosal oedema and ulceration in the splenic flexure, a ''watershed'' area. What is the SINGLE most likely diagnosis?', 'Ischaemic colitis is caused by reduced colonic blood flow and affects watershed areas (splenic flexure, rectosigmoid junction). It presents with abdominal pain and bloody diarrhoea in older patients with vascular disease, or after hypotension. Most cases resolve with supportive care. Gangrene or perforation needs surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4d521307-2de5-5d24-ba4a-95911d685d02', 'c41449be-a401-5fd2-b8f5-b272aab1b3e5', 'A', 'Diverticulitis', false, 0),
  ('71aec394-b3dc-59db-ac17-c651fbce35ba', 'c41449be-a401-5fd2-b8f5-b272aab1b3e5', 'B', 'Colorectal cancer', false, 1),
  ('afd02075-fc3c-5159-82ac-bb53ab0e0f99', 'c41449be-a401-5fd2-b8f5-b272aab1b3e5', 'C', 'Ischaemic colitis', true, 2),
  ('799750be-6d1c-5862-a1b7-30cd2bbc9403', 'c41449be-a401-5fd2-b8f5-b272aab1b3e5', 'D', 'Ulcerative colitis', false, 3),
  ('ff68f9c8-0a0a-5257-bfad-81edf7e37635', 'c41449be-a401-5fd2-b8f5-b272aab1b3e5', 'E', 'Infectious colitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e8a87eb0-25ca-507a-9197-8519ebc71dc4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 30 year old woman has had bloating, flatulence and watery diarrhoea after drinking milk, starting after a gastrointestinal infection. She has no weight loss and coeliac serology is negative. What is the SINGLE most likely diagnosis?', 'Lactose intolerance (lactase deficiency) can be primary or secondary to gut infection or coeliac disease. It causes bloating and osmotic diarrhoea after dairy. A hydrogen breath test can confirm it, or a trial of lactose withdrawal. Management is reducing lactose and using lactase supplements.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f73e664c-deef-54b3-9119-634ca23f184a', 'e8a87eb0-25ca-507a-9197-8519ebc71dc4', 'A', 'Small bowel lymphoma', false, 0),
  ('43d308a1-b2ae-51ba-b073-41e820e29ac2', 'e8a87eb0-25ca-507a-9197-8519ebc71dc4', 'B', 'Irritable bowel syndrome', false, 1),
  ('696ad38e-0dd8-5356-8207-bfaeb8a711df', 'e8a87eb0-25ca-507a-9197-8519ebc71dc4', 'C', 'Coeliac disease', false, 2),
  ('a34ce773-2f17-58bf-b2a3-c231b7687335', 'e8a87eb0-25ca-507a-9197-8519ebc71dc4', 'D', 'Crohn''s disease', false, 3),
  ('1771b1a7-b2f9-5eb2-97fb-6bb4bcd01b08', 'e8a87eb0-25ca-507a-9197-8519ebc71dc4', 'E', 'Lactose intolerance', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7ea6cebc-6eb0-58bd-8cf4-84bab9450e8e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 64 year old man with chronic alcohol use has had recurrent epigastric pain radiating to his back, steatorrhoea and weight loss. He has new diabetes. A CT shows pancreatic calcification. Faecal elastase is low. What is the SINGLE most appropriate treatment for his steatorrhoea?', 'Chronic pancreatitis (most often from alcohol) causes chronic pain, exocrine insufficiency (steatorrhoea, low faecal elastase) and endocrine insufficiency (diabetes). CT shows calcification. Management is stopping alcohol and smoking, analgesia, pancreatic enzyme replacement with meals, and fat-soluble vitamin supplements.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ff7e0174-3e44-53d1-b2ab-e55e8e78019c', '7ea6cebc-6eb0-58bd-8cf4-84bab9450e8e', 'A', 'Metronidazole', false, 0),
  ('855382e3-f5cd-5ef9-9709-16a592fdd13d', '7ea6cebc-6eb0-58bd-8cf4-84bab9450e8e', 'B', 'Loperamide', false, 1),
  ('9fdc3528-7b93-5d04-a48c-59fe2b0d0c12', '7ea6cebc-6eb0-58bd-8cf4-84bab9450e8e', 'C', 'Pancreatic enzyme replacement (Creon) with meals', true, 2),
  ('323d3fb4-f858-5e3c-9b38-f6a35296ae02', '7ea6cebc-6eb0-58bd-8cf4-84bab9450e8e', 'D', 'Ursodeoxycholic acid', false, 3),
  ('9abbfbfb-d29f-559e-84f2-65fd170ddfb5', '7ea6cebc-6eb0-58bd-8cf4-84bab9450e8e', 'E', 'Low-fat diet only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6cc59c65-c8c6-5e45-882f-3eef23cb0119', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 66 year old man has had a 3-month change in bowel habit to looser stools and has lost weight. He has no rectal bleeding and an abdominal examination is normal. His FIT (faecal immunochemical test) result is 52 micrograms Hb/g faeces. What is the SINGLE most appropriate next step?', 'NICE (DG56/NG12) recommends a FIT for adults with symptoms that may suggest colorectal cancer. A FIT of 10 micrograms Hb/g or more should prompt a suspected cancer pathway referral (colonoscopy or CT colonography). Patients with a rectal or abdominal mass, or anal ulceration, should be referred regardless of the FIT result.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9381c412-9864-5fdc-925f-13bdf668e092', '6cc59c65-c8c6-5e45-882f-3eef23cb0119', 'A', 'Reassure and repeat FIT in 1 year', false, 0),
  ('4a6397de-328e-5a47-9d06-e10dbc84c856', '6cc59c65-c8c6-5e45-882f-3eef23cb0119', 'B', 'Prescribe loperamide', false, 1),
  ('068e80c5-db14-5db4-8f03-12e9482fc4c5', '6cc59c65-c8c6-5e45-882f-3eef23cb0119', 'C', 'Abdominal ultrasound', false, 2),
  ('1e5613a1-bfc4-5853-bc54-0a99ab077c71', '6cc59c65-c8c6-5e45-882f-3eef23cb0119', 'D', 'Routine gastroenterology referral', false, 3),
  ('a39d1b71-f59e-5a8e-921b-2a371b0eea4d', '6cc59c65-c8c6-5e45-882f-3eef23cb0119', 'E', 'Suspected cancer pathway referral for colorectal cancer', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c1c4ab1-cec4-5900-a87b-25f33532aa0b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 60 year old man has a sigmoid colon cancer. CT staging shows no metastases. After resection, histology shows T3N1 disease (Dukes C). What is the SINGLE most appropriate further management?', 'Colorectal cancer staging uses TNM (historically Dukes). Lymph node-positive disease (stage III, Dukes C) is offered adjuvant chemotherapy (such as CAPOX or FOLFOX) to reduce recurrence. Rectal cancers may receive neoadjuvant chemoradiotherapy. Follow-up includes CEA and CT surveillance, and colonoscopy at 1 year.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2378a8ef-9bc3-5ff2-8245-d774a160dd03', '9c1c4ab1-cec4-5900-a87b-25f33532aa0b', 'A', 'Adjuvant chemotherapy', true, 0),
  ('92ab8eb8-e214-5366-835e-b6c1992dd308', '9c1c4ab1-cec4-5900-a87b-25f33532aa0b', 'B', 'Radiotherapy to the pelvis', false, 1),
  ('aa671cf9-e20a-59ac-92b1-1bdbae612b1a', '9c1c4ab1-cec4-5900-a87b-25f33532aa0b', 'C', 'Hormone therapy', false, 2),
  ('1aac5a6d-d399-50e9-b89e-44818f7e3369', '9c1c4ab1-cec4-5900-a87b-25f33532aa0b', 'D', 'Repeat surgery', false, 3),
  ('07817b6c-8986-5c85-b381-8ef171466058', '9c1c4ab1-cec4-5900-a87b-25f33532aa0b', 'E', 'No further treatment', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('04dba26d-fc73-5995-a5a1-7ba07d8ba136', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 35 year old woman''s mother was diagnosed with colon cancer aged 42 and her maternal uncle with endometrial cancer aged 48. Tumour testing in her mother showed loss of mismatch repair proteins. What is the SINGLE most likely inherited syndrome?', 'Lynch syndrome is autosomal dominant, caused by mismatch repair gene mutations (MLH1, MSH2, MSH6, PMS2). It increases the risk of colorectal (often right-sided), endometrial, ovarian, gastric and urinary tract cancers. NICE recommends testing all colorectal and endometrial cancers for MMR deficiency. Carriers have 2-yearly colonoscopy from age 25 and aspirin chemoprevention.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
