  ('504166e7-7ced-595d-8903-bd47824dd3e6', '04dba26d-fc73-5995-a5a1-7ba07d8ba136', 'A', 'Peutz-Jeghers syndrome', false, 0),
  ('282fad4a-3820-5cf6-b0f8-ce9dde30213c', '04dba26d-fc73-5995-a5a1-7ba07d8ba136', 'B', 'Lynch syndrome (hereditary non-polyposis colorectal cancer)', true, 1),
  ('a227f536-aa9b-5d9c-92af-1069cfa2244a', '04dba26d-fc73-5995-a5a1-7ba07d8ba136', 'C', 'Li-Fraumeni syndrome', false, 2),
  ('da75dfb8-a503-504e-b335-c74d746d6d43', '04dba26d-fc73-5995-a5a1-7ba07d8ba136', 'D', 'Familial adenomatous polyposis', false, 3),
  ('64811ec3-69c7-5bcb-9d34-03498277aebf', '04dba26d-fc73-5995-a5a1-7ba07d8ba136', 'E', 'BRCA1', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e02937d1-aa1d-5af2-ae08-0d5172b4ad3b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 6 year old boy has had painless, bright red rectal bleeding with iron deficiency anaemia. A technetium-99m pertechnetate scan shows uptake in the right lower abdomen. What is the SINGLE most likely diagnosis?', 'Meckel''s diverticulum (the ''rule of 2s'': 2% of people, 2 feet from the ileocaecal valve, 2 inches long, 2 types of ectopic tissue) can contain gastric mucosa that ulcerates and bleeds painlessly. A Meckel''s scan detects ectopic gastric mucosa. Treatment is surgical resection. It can also cause intussusception, obstruction or diverticulitis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
