  ('6f641d27-10b0-5ad7-8740-bd79659ca7b9', 'e02937d1-aa1d-5af2-ae08-0d5172b4ad3b', 'A', 'Meckel''s diverticulum', true, 0),
  ('9ebaf057-e36e-56f9-a759-7e626db4843e', 'e02937d1-aa1d-5af2-ae08-0d5172b4ad3b', 'B', 'Crohn''s disease', false, 1),
  ('6353252a-f990-5c78-b00f-accc347ccbae', 'e02937d1-aa1d-5af2-ae08-0d5172b4ad3b', 'C', 'Haemorrhoids', false, 2),
  ('90bc53f6-cedf-5a32-b36c-76dbe646e8f5', 'e02937d1-aa1d-5af2-ae08-0d5172b4ad3b', 'D', 'Intussusception', false, 3),
  ('e1781ad4-5803-5607-bd2d-60280e5d0d12', 'e02937d1-aa1d-5af2-ae08-0d5172b4ad3b', 'E', 'Juvenile polyp', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('292da655-90a2-54c4-bd29-65eefeb82bed', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 26 year old woman has had bloody diarrhoea for 3 days after eating undercooked chicken at a barbecue. She has fever and abdominal cramps. Stool culture grows a curved Gram-negative rod. What is the SINGLE most likely organism?', 'Campylobacter is the commonest cause of bacterial gastroenteritis in the UK, linked to undercooked poultry. It causes fever, cramping abdominal pain and bloody diarrhoea. Most cases are self-limiting. A macrolide (clarithromycin) is used for severe cases or immunocompromise. It can trigger Guillain-Barré syndrome and reactive arthritis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
