  ('920a1531-bbd6-58b1-8774-6e1165e9f48c', '292da655-90a2-54c4-bd29-65eefeb82bed', 'A', 'Shigella sonnei', false, 0),
  ('3cd2282c-1808-5d01-8247-48733a3f806e', '292da655-90a2-54c4-bd29-65eefeb82bed', 'B', 'Campylobacter jejuni', true, 1),
  ('39401553-1f95-5ad6-8402-8d23a5e18b78', '292da655-90a2-54c4-bd29-65eefeb82bed', 'C', 'Clostridium perfringens', false, 2),
  ('e5fccb82-0dd7-5e7e-a41f-ac5d98032488', '292da655-90a2-54c4-bd29-65eefeb82bed', 'D', 'Bacillus cereus', false, 3),
  ('dbfd1c53-6083-59b6-b383-ba5b2cd6f8c4', '292da655-90a2-54c4-bd29-65eefeb82bed', 'E', 'Salmonella typhi', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('708ccae9-a5b4-5324-aee3-9927351e6415', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 45 year old woman has had diarrhoea, weight loss and abdominal pain after a trip to India. She has had flatulence and greasy, offensive stools for 3 weeks. Stool microscopy shows cysts. What is the SINGLE most likely organism?', 'Giardiasis causes persistent diarrhoea with bloating, flatulence, steatorrhoea and malabsorption, often after travel or exposure to contaminated water. It is diagnosed by stool antigen, PCR or microscopy. Treatment is metronidazole (or tinidazole). Entamoeba histolytica causes bloody dysentery and liver abscess.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
