  ('ff064c29-003a-56fd-bd08-98a2d2009dc7', '708ccae9-a5b4-5324-aee3-9927351e6415', 'A', 'Vibrio cholerae', false, 0),
  ('873eed37-47f6-5f2e-a0c1-59b22d3ac09e', '708ccae9-a5b4-5324-aee3-9927351e6415', 'B', 'Giardia lamblia', true, 1),
  ('70b0bf49-826e-58d7-a3cb-660f41350fae', '708ccae9-a5b4-5324-aee3-9927351e6415', 'C', 'Campylobacter jejuni', false, 2),
  ('6dc9de7c-ca37-5d7f-95fd-640280045c93', '708ccae9-a5b4-5324-aee3-9927351e6415', 'D', 'Entamoeba histolytica', false, 3),
  ('4cc8df16-cb7a-5097-99c1-c6910ddd30bb', '708ccae9-a5b4-5324-aee3-9927351e6415', 'E', 'Clostridium difficile', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('821d7077-0914-5f74-beab-1abeac96e29d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 26 year old woman has had diarrhoea, weight loss, palpitations and anxiety. She has a smooth goitre and lid lag. Coeliac serology is negative. Which test is MOST likely to explain her diarrhoea?', 'Hyperthyroidism increases gut motility and can cause diarrhoea and weight loss. Endocrine causes of chronic diarrhoea also include diabetes (autonomic neuropathy), Addison''s disease and, rarely, neuroendocrine tumours. Thyroid function tests are part of the basic workup for chronic diarrhoea.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
