  ('c374d24a-d873-5ab4-b3fa-6b3470137d31', '821d7077-0914-5f74-beab-1abeac96e29d', 'A', 'Faecal calprotectin', false, 0),
  ('35f2076b-ff52-55e0-80d7-cc284aedfb2b', '821d7077-0914-5f74-beab-1abeac96e29d', 'B', 'Colonoscopy', false, 1),
  ('c0c6f752-4d69-50e2-8147-1304318c582e', '821d7077-0914-5f74-beab-1abeac96e29d', 'C', 'Thyroid function tests', true, 2),
  ('a45ccdae-8594-513a-aba4-53a120d7f616', '821d7077-0914-5f74-beab-1abeac96e29d', 'D', 'Stool culture', false, 3),
  ('187c6b15-b9ec-51d4-8096-4c0c9bc453d1', '821d7077-0914-5f74-beab-1abeac96e29d', 'E', 'Abdominal CT', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('560c98fb-c9a8-5fc6-84af-8b72ea12c929', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 52 year old man has had episodes of facial flushing, watery diarrhoea and wheeze. He has an enlarged, nodular liver on examination. Echocardiography shows tricuspid regurgitation. What is the SINGLE most appropriate diagnostic test?', 'Carcinoid syndrome happens when a neuroendocrine tumour (usually small bowel) has spread to the liver and serotonin reaches the systemic circulation. It causes flushing, diarrhoea, bronchospasm and right-sided valve disease. Diagnosis is by raised urinary 5-HIAA (or plasma chromogranin A). Treatment includes somatostatin analogues (octreotide) and resection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4a1f46c2-6c4c-5ea1-bd54-75350884ecd2', '560c98fb-c9a8-5fc6-84af-8b72ea12c929', 'A', 'Serum gastrin', false, 0),
  ('c90f9d4c-9de5-5eb8-852d-b8e41c6c6533', '560c98fb-c9a8-5fc6-84af-8b72ea12c929', 'B', 'Short Synacthen test', false, 1),
  ('a8d46011-a449-5b7e-b5d0-75890f26a503', '560c98fb-c9a8-5fc6-84af-8b72ea12c929', 'C', 'Urinary catecholamines', false, 2),
  ('292ff3b8-e806-5c33-9d5e-47c1672fcbb6', '560c98fb-c9a8-5fc6-84af-8b72ea12c929', 'D', 'Serum calcitonin', false, 3),
  ('90e346da-29c8-5364-893e-5a3595aab64c', '560c98fb-c9a8-5fc6-84af-8b72ea12c929', 'E', '24-hour urinary 5-hydroxyindoleacetic acid (5-HIAA)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('08692ee4-6493-51ed-8168-42b3fbb99c50', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 44 year old man has had recurrent peptic ulcers, including in the jejunum, despite H. pylori eradication. He has chronic diarrhoea. His fasting serum gastrin is markedly raised while off PPI. What is the SINGLE most likely diagnosis?', 'Gastrinomas (often in the pancreas or duodenum, and associated with MEN1) secrete gastrin, causing excess acid, severe and recurrent ulcers in unusual sites, and diarrhoea. Diagnosis is a raised fasting gastrin with low gastric pH. Treatment is high-dose PPI and surgical resection where possible. Calcium should be checked for MEN1.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b106b419-7fac-5af3-a610-9410871e51f6', '08692ee4-6493-51ed-8168-42b3fbb99c50', 'A', 'Zollinger-Ellison syndrome (gastrinoma)', true, 0),
  ('2473d3c7-aa51-5aba-83f0-c6dcd0d1c92c', '08692ee4-6493-51ed-8168-42b3fbb99c50', 'B', 'Crohn''s disease', false, 1),
  ('10b87d22-49c4-5ece-ba8d-7de4b17524c0', '08692ee4-6493-51ed-8168-42b3fbb99c50', 'C', 'Carcinoid syndrome', false, 2),
  ('2330e85f-3b3b-53c3-9206-b06fa110488c', '08692ee4-6493-51ed-8168-42b3fbb99c50', 'D', 'Coeliac disease', false, 3),
  ('936d368a-3965-5a4f-9dc6-ea5536bf1cd5', '08692ee4-6493-51ed-8168-42b3fbb99c50', 'E', 'VIPoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8102cb5b-c3af-5bba-b403-8e722972eb96', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 76 year old man with a history of gastrectomy has fatigue, glossitis and peripheral paraesthesia. His MCV is 116 fL. What is the SINGLE most likely deficiency?', 'Gastrectomy removes the parietal cells that produce intrinsic factor, so B12 cannot be absorbed in the terminal ileum. This causes macrocytic anaemia and neurological complications (peripheral neuropathy, subacute combined degeneration of the cord). Patients need lifelong IM hydroxocobalamin after total gastrectomy. Terminal ileal resection or Crohn''s also causes B12 deficiency.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('593f28ab-2536-5243-9470-0047f77ccb18', '8102cb5b-c3af-5bba-b403-8e722972eb96', 'A', 'Vitamin D', false, 0),
  ('ce9e0024-b44d-5767-b229-e9fc70c34b51', '8102cb5b-c3af-5bba-b403-8e722972eb96', 'B', 'Iron', false, 1),
  ('0bd13aac-9229-5fd2-aecd-dd452f8c6c8f', '8102cb5b-c3af-5bba-b403-8e722972eb96', 'C', 'Folate only', false, 2),
  ('3125e103-815e-5952-80de-077f0f356441', '8102cb5b-c3af-5bba-b403-8e722972eb96', 'D', 'Vitamin B12', true, 3),
  ('2503b8ab-96b3-5912-988b-467ea49ea1e3', '8102cb5b-c3af-5bba-b403-8e722972eb96', 'E', 'Vitamin C', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('883b1dd4-983d-5589-825a-556bc0993994', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 48 year old woman has a 2-week history of RUQ pain, fever with rigors and jaundice. Her temperature is 39.2°C, and she has raised bilirubin and ALP. Ultrasound shows a dilated common bile duct with stones. What is the SINGLE most appropriate management?', 'Fever, jaundice and RUQ pain (Charcot''s triad) indicate ascending cholangitis, usually from a common bile duct stone. Adding confusion and hypotension makes Reynolds'' pentad. Management is resuscitation, IV broad-spectrum antibiotics and biliary decompression by ERCP with sphincterotomy and stone extraction (or a stent). Cholecystectomy follows later.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('84be0148-457d-593a-93cc-98fb71ee70a4', '883b1dd4-983d-5589-825a-556bc0993994', 'A', 'IV antibiotics and urgent ERCP for biliary drainage', true, 0),
  ('d56f880a-2d5f-52ce-8b7f-1c4836c95488', '883b1dd4-983d-5589-825a-556bc0993994', 'B', 'Elective cholecystectomy in 6 months', false, 1),
  ('0bf3fbb0-cf3e-5054-ac58-deff87ae6de7', '883b1dd4-983d-5589-825a-556bc0993994', 'C', 'Oral antibiotics and discharge', false, 2),
  ('c201081b-28e3-5e31-8d8e-0f079b6b2ea7', '883b1dd4-983d-5589-825a-556bc0993994', 'D', 'Analgesia only', false, 3),
  ('91e66bf5-e4fc-5e94-b1c2-498cfca13fa0', '883b1dd4-983d-5589-825a-556bc0993994', 'E', 'MRCP and outpatient review', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0dfda429-6a91-54d2-a974-e90ee48db897', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 55 year old man has diarrhoea and weight loss for 9 months. He has an intensely itchy red rash on his buttocks and thighs. Investigations: Haemoglobin 108 g/L (130–175) Blood film: anisocytosis Which is the most likely histological appearance on small bowel biopsy?', 'An intensely itchy blistering rash on the buttocks and extensor surfaces is dermatitis herpetiformis, the skin manifestation of coeliac disease. With diarrhoea, weight loss and anaemia showing anisocytosis (mixed iron and folate deficiency), the diagnosis is coeliac disease. Duodenal biopsy shows villous atrophy, crypt hyperplasia and increased intraepithelial lymphocytes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('47084af8-0b21-5b82-8b86-9f4d49c5a771', '0dfda429-6a91-54d2-a974-e90ee48db897', 'A', 'Hyperplasia of Brunner’s glands', false, 0),
  ('0623e592-0261-530b-8ca0-5f25fdec6067', '0dfda429-6a91-54d2-a974-e90ee48db897', 'B', 'Increased intraepithelial macrophages', false, 1),
  ('64d67042-e4fe-5bfe-93c0-5c1329b7ce2c', '0dfda429-6a91-54d2-a974-e90ee48db897', 'C', 'Increased lymphocytes in submucosa', false, 2),
  ('379f7e8f-2d96-5860-a026-b96567761ea6', '0dfda429-6a91-54d2-a974-e90ee48db897', 'D', 'Ulceration', false, 3),
  ('e6ee9f13-e265-51af-bb36-cb903ba121c0', '0dfda429-6a91-54d2-a974-e90ee48db897', 'E', 'Villous atrophy', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('536236eb-54a5-56f3-84d7-2190c93c0f5f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 74 year old man has painless jaundice and pale faeces for 1 week. He has lost 4 kg in weight in 3 months. His temperature is 37.4°C, pulse rate 90 bpm, BP 138/76 mmHg, respiratory rate 18 breaths per minute. His sclera and skin are yellow. Chest and abdominal examinations are normal. Which is the most appropriate investigation?', 'Painless obstructive jaundice with weight loss in an older patient suggests pancreatic or biliary malignancy. NICE recommends a CT scan of the abdomen (pancreatic protocol) for people aged 40 and over with jaundice, because it stages the cancer and identifies the level of obstruction. ERCP is for treatment (stenting) or tissue sampling, and MRCP is mainly used for stones.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0c19d48e-8394-5182-a22d-0802f83436e7', '536236eb-54a5-56f3-84d7-2190c93c0f5f', 'A', 'CT scan of abdomen', true, 0),
  ('77f5cf29-d26e-5385-ade7-b5d6be3933a7', '536236eb-54a5-56f3-84d7-2190c93c0f5f', 'B', 'Endoscopic retrograde cholangio-pancreatography', false, 1),
  ('bdbc02ee-5e96-5cc3-af47-811c9aad5f50', '536236eb-54a5-56f3-84d7-2190c93c0f5f', 'C', 'MR cholangio-pancreatography', false, 2),
  ('2f60908d-2185-507f-9e4d-7b89c8016536', '536236eb-54a5-56f3-84d7-2190c93c0f5f', 'D', 'PET scan of abdomen', false, 3),
  ('977c5cd5-bade-52bd-9cd3-886ca5e189d1', '536236eb-54a5-56f3-84d7-2190c93c0f5f', 'E', 'Ultrasound scan of the abdomen', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2f37115a-b496-58bb-8dff-4bdaa78fb377', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 48 year old man has moderate epigastric pain for 2 days and is seen at his GP surgery. He had a duodenal ulcer 6 months ago and was treated with Helicobacter pylori eradication therapy. Which is the most appropriate test to confirm Helicobacter pylori eradication?', 'To confirm H. pylori eradication, NICE recommends a carbon-13 urea breath test (at least 4 weeks after antibiotics and 2 weeks after stopping a PPI). Serology is unsuitable because antibodies stay positive after eradication. A stool antigen test is an alternative, but the urea breath test is the preferred test of cure.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('62b3652c-6c10-58ba-960c-4bf5da66f9b1', '2f37115a-b496-58bb-8dff-4bdaa78fb377', 'A', 'C13 urea breath test', true, 0),
  ('dc999574-cbb8-5e37-b899-1e59359d06a6', '2f37115a-b496-58bb-8dff-4bdaa78fb377', 'B', 'Faecal Helicobacter antigen', false, 1),
  ('e8697c2d-0e7f-59ed-92da-cefbb6157c6c', '2f37115a-b496-58bb-8dff-4bdaa78fb377', 'C', 'Gastric aspirate urease test', false, 2),
  ('87d0c28c-b148-5059-a0d8-4d6bc34198b0', '2f37115a-b496-58bb-8dff-4bdaa78fb377', 'D', 'Helicobacter pylori serology', false, 3),
  ('82e5c8d4-f928-56ff-8c6a-8cf90eb7967b', '2f37115a-b496-58bb-8dff-4bdaa78fb377', 'E', 'Repeat endoscopy and biopsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3cec2306-5409-540e-a6be-dc3fe0c91da7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 23 year old woman has worsening diarrhoea with blood and mucus for 2 months and is seen in the GP surgery. She has abdominal pain and bloating. She has no weight loss. Her abdomen is soft and there is mild left-sided tenderness on deep palpation. She has active bowel sounds. Investigations: Haemoglobin 102 g/L (115–150) White cell count 11.2 x10⁹/L (4.0–11.0) Platelets 395 x10⁹/L (150–400) CRP 78 mg/L (<5) Which is the most appropriate diagnostic investigation?', 'Bloody diarrhoea with mucus for 2 months, anaemia, raised CRP and thrombocytosis in a young woman suggest inflammatory bowel disease, likely ulcerative colitis. Colonoscopy with biopsies is the diagnostic investigation. Faecal calprotectin is a screening test, mainly used to tell IBD from IBS. Stool cultures exclude infection but do not diagnose IBD.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8835a3c2-a051-57b7-a3c1-e0adaea660e7', '3cec2306-5409-540e-a6be-dc3fe0c91da7', 'A', 'Colonoscopy', true, 0),
  ('5b564daf-2660-57ac-9839-b5246caf6ac9', '3cec2306-5409-540e-a6be-dc3fe0c91da7', 'B', 'Faecal calprotectin', false, 1),
  ('925df523-ee16-510d-a7a5-f1a83c565fb5', '3cec2306-5409-540e-a6be-dc3fe0c91da7', 'C', 'Faecal occult blood', false, 2),
  ('6d8dc6bf-22c2-53ac-aa9b-c88900be6b9e', '3cec2306-5409-540e-a6be-dc3fe0c91da7', 'D', 'Helicobacter pylori stool antigen', false, 3),
  ('84d0f9d4-9c79-50e5-a69c-c61296553f89', '3cec2306-5409-540e-a6be-dc3fe0c91da7', 'E', 'Stool culture and sensitivity', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d5efb149-8661-5b90-a456-249d86620eee', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 35 year old woman has recurrent retrosternal discomfort after eating food for the last 3 months and attends her GP surgery. He has occasional nausea but no vomiting. She takes no medication. He drinks 5 glasses of wine each week. She has not lost anyweight. Which is the most appropriate management approach?', 'The GMC answer is upper GI endoscopy. NICE recommends urgent direct-access endoscopy for dyspepsia with alarm features, or for people aged 55 and over. For dyspepsia without alarm features in a younger patient, test-and-treat for H. pylori or a PPI trial is usually first-line, so check the stem carefully in exam questions.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a6edcbb6-d9ff-5e69-a909-0f2f3786fd96', 'd5efb149-8661-5b90-a456-249d86620eee', 'A', 'Barium swallow', false, 0),
  ('2f1dd50e-98eb-5836-866d-9503e64bd4b3', 'd5efb149-8661-5b90-a456-249d86620eee', 'B', 'Chest X-ray', false, 1),
  ('e24ab158-1b19-5a0c-ad05-f6352c17bed3', 'd5efb149-8661-5b90-a456-249d86620eee', 'C', 'CT scan of thorax', false, 2),
  ('1436fac8-c7df-57b3-91e1-03aec00951a3', 'd5efb149-8661-5b90-a456-249d86620eee', 'D', 'Gastroenterology clinic referral', false, 3),
  ('64136cf8-94ae-5854-b9ca-16ceb6a41b18', 'd5efb149-8661-5b90-a456-249d86620eee', 'E', 'Upper gastrointestinal endoscopy', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bb34aefc-b13d-576c-9c5a-f4f2c33d542a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 55 year old woman attends a health check. She is a non-smoker with no history of cardiovascular disease, diabetes or kidney disease. Her blood pressure is 134/82 mmHg and total cholesterol is 6.1 mmol/L. Her QRISK3 score is 14%. She has already tried diet and exercise changes for 3 months. What is the SINGLE most appropriate management?', 'For primary prevention of cardiovascular disease, NICE recommends offering atorvastatin 20 mg to people with a QRISK3 of 10% or more once lifestyle factors have been addressed. Atorvastatin 80 mg is the dose for secondary prevention, after an established cardiovascular event. Lipids, LFTs and adherence should be checked at about 3 months, aiming for a reduction in non-HDL cholesterol of more than 40%.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fde9e34d-818c-5d8f-b8f7-34e6cd04795a', 'bb34aefc-b13d-576c-9c5a-f4f2c33d542a', 'A', 'Lifestyle advice only and repeat QRISK3 in 5 years', false, 0),
  ('6f0f8788-06a4-5702-9402-8effce01c825', 'bb34aefc-b13d-576c-9c5a-f4f2c33d542a', 'B', 'Offer atorvastatin 80 mg daily', false, 1),
  ('307a772c-e959-5777-ac58-49b8078ef77a', 'bb34aefc-b13d-576c-9c5a-f4f2c33d542a', 'C', 'Offer simvastatin 40 mg daily', false, 2),
  ('41c2e560-ed49-5b7f-bc3c-2f497f2b001d', 'bb34aefc-b13d-576c-9c5a-f4f2c33d542a', 'D', 'Offer ezetimibe 10 mg daily', false, 3),
  ('4bfc2d7a-a61d-53e8-90c9-cb1c82e0f996', 'bb34aefc-b13d-576c-9c5a-f4f2c33d542a', 'E', 'Offer atorvastatin 20 mg daily', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0a89367f-084f-5df6-bf9f-d050f358de5e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 29 year old woman attends her GP with 2 days of dysuria, urinary frequency and suprapubic discomfort. She is not pregnant, has no fever, no loin pain and no vaginal discharge. Urine dipstick is positive for nitrites and leukocytes. She has no allergies and normal kidney function. What is the SINGLE most appropriate treatment?', 'This is an uncomplicated lower UTI in a non-pregnant woman. NICE recommends nitrofurantoin for 3 days first-line (if eGFR is at least 45), or trimethoprim for 3 days if resistance is unlikely. Seven-day courses are for men and pregnant women. Amoxicillin has high resistance rates. Quinolones such as ciprofloxacin are not used for uncomplicated cystitis because of side effects and resistance concerns.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b0689e1f-fd2c-59f3-8ac4-7351d15c9b4c', '0a89367f-084f-5df6-bf9f-d050f358de5e', 'A', 'Amoxicillin for 7 days', false, 0),
  ('b4fe0ee7-7b51-59e6-bc49-b3c1ecc22d1d', '0a89367f-084f-5df6-bf9f-d050f358de5e', 'B', 'Ciprofloxacin for 3 days', false, 1),
  ('eb049236-8ee7-58e7-af91-0785436d2e1a', '0a89367f-084f-5df6-bf9f-d050f358de5e', 'C', 'Nitrofurantoin for 3 days', true, 2),
  ('bf75a58e-10b0-5f93-8d59-82699df56bd4', '0a89367f-084f-5df6-bf9f-d050f358de5e', 'D', 'No antibiotic; review in 2 weeks', false, 3),
  ('3d63a419-eb6e-590c-9994-7096c2e7186d', '0a89367f-084f-5df6-bf9f-d050f358de5e', 'E', 'Trimethoprim for 7 days', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('32cbca6f-47f7-55d9-8098-c26ee6e9e965', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 46 year old man has had pain on the outer side of his right elbow for 6 weeks. He works as a carpenter. Pain is reproduced by resisted extension of the wrist and middle finger, and the lateral epicondyle is tender. Range of movement is full. What is the SINGLE most likely diagnosis?', 'Lateral elbow pain with tenderness over the lateral epicondyle and pain on resisted wrist extension is lateral epicondylitis, an overuse injury of the common extensor origin. Management is rest from aggravating activities, analgesia, physiotherapy and a brace. Most cases resolve within 1-2 years. Steroid injections give short-term relief but may worsen long-term outcomes. Medial epicondylitis is pain on resisted wrist flexion.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('33d084e5-aae5-51f5-94ae-e921e6f26154', '32cbca6f-47f7-55d9-8098-c26ee6e9e965', 'A', 'Olecranon bursitis', false, 0),
  ('77323d1e-156d-51a5-8689-0c0c397cbc15', '32cbca6f-47f7-55d9-8098-c26ee6e9e965', 'B', 'Medial epicondylitis (golfer''s elbow)', false, 1),
  ('e2a9da5e-4491-567d-a237-aae675bf8167', '32cbca6f-47f7-55d9-8098-c26ee6e9e965', 'C', 'Cubital tunnel syndrome', false, 2),
  ('9fede3df-118b-532d-a3d7-66bb4acd2482', '32cbca6f-47f7-55d9-8098-c26ee6e9e965', 'D', 'Lateral epicondylitis (tennis elbow)', true, 3),
  ('d10854b1-e33a-55c9-9ec8-ab9ee7528803', '32cbca6f-47f7-55d9-8098-c26ee6e9e965', 'E', 'Elbow osteoarthritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e8344e70-a290-52d2-b3a5-dda4e75129b0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 39 year old woman with no past medical history has a BP of 162/102 mmHg in clinic. Repeat measurement is 158/100 mmHg. She has no symptoms. Fundoscopy is normal and she has no signs of target organ damage. What is the SINGLE most appropriate next step?', 'NICE recommends confirming hypertension with ABPM (or home BP monitoring if ABPM is not tolerated) when clinic BP is 140/90 mmHg or higher. Same-day specialist referral is needed for BP of 180/120 mmHg or higher with signs of accelerated hypertension (retinal haemorrhages or papilloedema) or life-threatening symptoms. While waiting, assess cardiovascular risk and check for target organ damage (urine ACR, U&Es, HbA1c, lipids, ECG). In a young person, consider secondary causes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eb092606-5e18-57b3-bd83-0f4df3e0022d', 'e8344e70-a290-52d2-b3a5-dda4e75129b0', 'A', 'Start amlodipine immediately', false, 0),
  ('136f5872-0f89-5b20-9f55-2425563d57e1', 'e8344e70-a290-52d2-b3a5-dda4e75129b0', 'B', 'Arrange ambulatory blood pressure monitoring (ABPM) to confirm the diagnosis', true, 1),
  ('8deae68a-692d-5678-af80-cb2b50993c40', 'e8344e70-a290-52d2-b3a5-dda4e75129b0', 'C', 'Same-day referral to the medical team', false, 2),
  ('49bb826a-6699-5fa8-9b7b-86c6bb9b8521', 'e8344e70-a290-52d2-b3a5-dda4e75129b0', 'D', 'Recheck BP in 1 year', false, 3),
  ('98a1ec5f-bef4-5bac-9f07-1bc609504664', 'e8344e70-a290-52d2-b3a5-dda4e75129b0', 'E', 'Start ramipril and bendroflumethiazide together', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dcccbe74-8799-5c00-a835-f41bf1dc7d76', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 30 year old woman has had a red, sticky left eye for 2 days with yellow discharge and crusting of her eyelids in the morning. Her vision is normal, there is no pain or photophobia, and she does not wear contact lenses. Her pupil is normal. What is the SINGLE most appropriate initial management?', 'Infective conjunctivitis is usually self-limiting within 1-2 weeks. NICE CKS recommends cleaning the eyelids, avoiding sharing towels, and considering topical chloramphenicol or fusidic acid if it is severe or persists. Red flags needing same-day ophthalmology referral include reduced vision, significant pain, photophobia, contact lens wear (risk of keratitis) and an abnormal pupil. Steroids should never be used without specialist advice.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('80b1ba15-8de6-50d1-bf64-13d4e1d866cd', 'dcccbe74-8799-5c00-a835-f41bf1dc7d76', 'A', 'Self-care advice (cleaning the eyelids, hygiene); topical antibiotic only if severe or persistent', true, 0),
  ('d69e3600-f207-5343-b916-caa59f2532a8', 'dcccbe74-8799-5c00-a835-f41bf1dc7d76', 'B', 'Topical steroid drops', false, 1),
  ('cb5fe43a-7880-5716-acad-f846fc9b4d1b', 'dcccbe74-8799-5c00-a835-f41bf1dc7d76', 'C', 'Oral co-amoxiclav', false, 2),
  ('421c57c2-b4e4-548f-b1ba-206fbfd5c554', 'dcccbe74-8799-5c00-a835-f41bf1dc7d76', 'D', 'Urgent same-day ophthalmology referral', false, 3),
  ('b5b70bd0-4193-5294-bb44-3cf2f06030ef', 'dcccbe74-8799-5c00-a835-f41bf1dc7d76', 'E', 'Topical aciclovir', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('551f3497-57c0-520e-aeea-a42a9783fd06', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 35 year old man has 3 weeks of low back pain after lifting a heavy box. The pain does not radiate below the knee. He has no weight loss, fever, night pain, saddle anaesthesia or bladder symptoms, and no history of cancer. Neurological examination is normal. What is the SINGLE most appropriate management?', 'This is non-specific (mechanical) low back pain with no red flags. NICE recommends reassurance, encouragement to keep active and continue normal activities, an oral NSAID (with a PPI if needed) at the lowest effective dose, and exercise programmes. Imaging is not recommended in primary care without red flags. Paracetamol alone and opioids are not recommended for acute low back pain without sciatica.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7b3c8f4a-f3ce-5689-b2c4-94b27ad77794', '551f3497-57c0-520e-aeea-a42a9783fd06', 'A', 'Lumbar spine X-ray', false, 0),
  ('259ba45c-29b4-5e4b-ae28-74b8fc60d687', '551f3497-57c0-520e-aeea-a42a9783fd06', 'B', 'Urgent MRI of the lumbar spine', false, 1),
  ('134cb161-fb47-591b-82e9-f6e715ef5eeb', '551f3497-57c0-520e-aeea-a42a9783fd06', 'C', 'Reassurance, advice to stay active, and an oral NSAID if needed', true, 2),
  ('de43dbba-e806-5e85-a20d-d3860acfc693', '551f3497-57c0-520e-aeea-a42a9783fd06', 'D', 'Strong opioids for 3 months', false, 3),
  ('3a8da2d0-5e7a-5b75-9175-9345a0e9ae8e', '551f3497-57c0-520e-aeea-a42a9783fd06', 'E', 'Bed rest for 2 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9cc6b5f5-68a4-57cd-9cd2-864d309736df', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 35 year old man asks his GP about the NHS Health Check. At what age range is the NHS Health Check offered?', 'The NHS Health Check is offered to adults aged 40-74 without existing vascular disease, every 5 years. It assesses the risk of heart disease, stroke, kidney disease, type 2 diabetes and dementia, measuring BP, cholesterol, BMI and QRISK, and giving lifestyle advice. Cervical screening is offered at 25-64 (in England now 5-yearly for those testing HPV negative).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('95846bf7-d4ea-5992-bca4-a3ba6c8f387c', '9cc6b5f5-68a4-57cd-9cd2-864d309736df', 'A', 'Only people over 75', false, 0),
  ('fd507c59-2e7a-5648-a76b-7de7374c8256', '9cc6b5f5-68a4-57cd-9cd2-864d309736df', 'B', 'Everyone from age 18 annually', false, 1),
  ('d7ed358f-39a4-50a5-8b62-8fa81333ce8e', '9cc6b5f5-68a4-57cd-9cd2-864d309736df', 'C', 'Everyone aged 25-64 every 3 years', false, 2),
  ('a8e67bc8-0f03-5300-a6e9-89e61ede604e', '9cc6b5f5-68a4-57cd-9cd2-864d309736df', 'D', 'Adults aged 40-74 without pre-existing cardiovascular disease, every 5 years', true, 3),
  ('ba1fdb0c-877f-5f6f-b07e-7f7462244227', '9cc6b5f5-68a4-57cd-9cd2-864d309736df', 'E', 'Only smokers', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('966a0da9-46b5-521f-ac72-d7f9f4d37ef2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 42 year old woman has had fatigue for 3 months. She is not sleeping well and is stressed at work. Examination is normal. What is the SINGLE most appropriate initial set of investigations?', 'Tiredness is a common presentation. A careful history (sleep, mood, alcohol, medication, weight change, red flags) guides investigation. A sensible initial panel is FBC, ferritin, U&E, LFTs, TFTs, HbA1c, CRP or ESR, and coeliac serology, with others guided by symptoms. Depression, sleep problems and lifestyle factors are common causes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('45f464f2-9bd5-5f23-9a51-8013146eb6d2', '966a0da9-46b5-521f-ac72-d7f9f4d37ef2', 'A', 'No tests', false, 0),
  ('f3d3428a-2b34-55a0-9764-00aaab925ca4', '966a0da9-46b5-521f-ac72-d7f9f4d37ef2', 'B', 'Whole-body CT', false, 1),
  ('4d6c0621-7cd8-5157-b648-de4508d19f1a', '966a0da9-46b5-521f-ac72-d7f9f4d37ef2', 'C', 'MRI brain', false, 2),
  ('ef7e14dd-8ca2-5384-b625-b327fa48cd5e', '966a0da9-46b5-521f-ac72-d7f9f4d37ef2', 'D', 'Bone marrow biopsy', false, 3),
  ('57c027d4-56e4-538d-afb3-f30864218b9a', '966a0da9-46b5-521f-ac72-d7f9f4d37ef2', 'E', 'FBC, ferritin, U&E, LFT, TFT, HbA1c (glucose), CRP and coeliac serology as indicated', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8a02c4df-bcb0-52d2-a8a0-dbca6b52011d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 66 year old woman asks about vaccinations. She is otherwise well. Which vaccines are routinely offered at age 65 in the UK?', 'At 65, adults are offered the pneumococcal vaccine (one-off), the annual flu vaccine and the shingles vaccine (Shingrix, two doses, from 65). The RSV vaccine is offered at 75-79, and COVID boosters are seasonal for older people. Immunosuppressed adults may be offered these earlier.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
