  ('b80397c2-ccd8-5d97-a4f9-2889925cc0c1', '8a02c4df-bcb0-52d2-a8a0-dbca6b52011d', 'A', 'MMR booster', false, 0),
  ('65d387e9-4899-5ada-b09b-e579a2bd5c52', '8a02c4df-bcb0-52d2-a8a0-dbca6b52011d', 'B', 'HPV vaccine', false, 1),
  ('6ccab983-069a-5c9f-a319-414458eb0427', '8a02c4df-bcb0-52d2-a8a0-dbca6b52011d', 'C', 'BCG and hepatitis B', false, 2),
  ('f89512eb-39c7-56e6-b3af-9cc8e97331bd', '8a02c4df-bcb0-52d2-a8a0-dbca6b52011d', 'D', 'Typhoid vaccine', false, 3),
  ('0005fff2-46d1-5165-8b31-67731251d4a5', '8a02c4df-bcb0-52d2-a8a0-dbca6b52011d', 'E', 'Pneumococcal polysaccharide vaccine (PPV23), annual influenza, and shingles vaccine', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f128d50f-c893-567e-abbc-42a577aaff89', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A mother brings her 8 week old baby for routine immunisations. Which vaccines are given at 8 weeks in the UK schedule?', 'At 8 weeks: the 6-in-1 vaccine, MenB and rotavirus. At 12 weeks: the 6-in-1, pneumococcal (PCV) and rotavirus. At 16 weeks: the 6-in-1 and MenB. At 1 year: Hib/MenC, MMR, PCV booster and MenB booster. The schedule is periodically updated, and recent changes include varicella being added to MMR as MMRV. Paracetamol is advised after MenB at 8 and 16 weeks to reduce fever.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
