  ('652541db-7214-57f2-9ce3-097af72f23b0', 'f128d50f-c893-567e-abbc-42a577aaff89', 'B', '6-in-1 (DTaP/IPV/Hib/HepB), MenB and rotavirus', true, 1),
  ('82d712c5-de2c-5393-adc4-84943bfc6faa', 'f128d50f-c893-567e-abbc-42a577aaff89', 'C', 'HPV', false, 2),
  ('54d9e3d3-3f3a-57cd-b899-dc80417130db', 'f128d50f-c893-567e-abbc-42a577aaff89', 'D', 'MMR and Hib/MenC', false, 3),
