insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('498975be-eb77-5361-9fa4-36d94f318df3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 25 year old woman has had urinary frequency and dysuria for 2 days. She is 12 weeks pregnant. Urine dipstick shows nitrites. What is the SINGLE most appropriate management?', 'UTI in pregnancy needs treatment (even asymptomatic bacteriuria) because of the risk of pyelonephritis and preterm labour. NICE recommends nitrofurantoin for 7 days (avoiding it at term, because of neonatal haemolysis), with amoxicillin or cefalexin as alternatives based on sensitivities. Trimethoprim is avoided in the first trimester (a folate antagonist). A culture is sent before and after treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('07620f1b-dd5d-5023-a427-32a671076c43', '498975be-eb77-5361-9fa4-36d94f318df3', 'A', 'No treatment until culture', false, 0),
  ('dd3961b1-1ef3-5b99-ba3b-a6b488389646', '498975be-eb77-5361-9fa4-36d94f318df3', 'B', 'Ciprofloxacin', false, 1),
  ('b83da809-df27-587f-9aa3-d7f2f094c62e', '498975be-eb77-5361-9fa4-36d94f318df3', 'C', 'Trimethoprim for 3 days', false, 2),
  ('726fd2e5-ed96-5d0e-9890-7bb98e89fe39', '498975be-eb77-5361-9fa4-36d94f318df3', 'D', 'Amoxicillin for 3 days without culture', false, 3),
  ('d8e00e10-eb6a-5e91-9095-79a08d6832dd', '498975be-eb77-5361-9fa4-36d94f318df3', 'E', 'Send urine culture and start nitrofurantoin for 7 days', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('372e7c2a-5cd6-549f-821a-6b1003c52db1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 72 year old man asks about bowel cancer screening. What does the NHS Bowel Cancer Screening Programme in England currently offer?', 'The NHS Bowel Cancer Screening Programme in England sends home FIT kits every 2 years to people aged 50-74 (having been extended from 60). An abnormal result leads to colonoscopy (or CT colonography). People over 74 can request a kit. Screening reduces colorectal cancer mortality.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
