  ('92e160b0-09d6-5e7d-891a-daf847ebd011', '372e7c2a-5cd6-549f-821a-6b1003c52db1', 'A', 'Colonoscopy every year from 40', false, 0),
  ('21981ff9-7eb8-5659-a13c-ffe4de5b7b84', '372e7c2a-5cd6-549f-821a-6b1003c52db1', 'B', 'CT colonography every 5 years', false, 1),
  ('7488140d-cc7a-5a82-8b4b-bfe693d095c4', '372e7c2a-5cd6-549f-821a-6b1003c52db1', 'C', 'A home FIT kit every 2 years for people aged 50-74', true, 2),
  ('5cb482db-eeba-54d2-b2f3-21c05c4403e9', '372e7c2a-5cd6-549f-821a-6b1003c52db1', 'D', 'Blood test for CEA', false, 3),
  ('d9c0fd6e-0278-550b-8f29-4c84e842df58', '372e7c2a-5cd6-549f-821a-6b1003c52db1', 'E', 'Flexible sigmoidoscopy for everyone at 30', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('52267c3a-62a0-542f-8ec1-9d82bd521edc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 30 year old man has had a red, painful, swollen lower eyelid margin with a small pustule at the base of an eyelash for 2 days. His vision is normal. What is the SINGLE most appropriate management?', 'An external hordeolum (stye) is an acute staphylococcal infection of an eyelash follicle. It usually resolves with warm compresses. Antibiotics are only needed if there is spreading periorbital cellulitis. A persistent, painless lump is likely a chalazion.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
