  ('6f6654fd-bb2c-5f9e-9115-b2db7f738498', '52267c3a-62a0-542f-8ec1-9d82bd521edc', 'A', 'Topical steroid', false, 0),
  ('ad42e5c0-cf33-5ae3-9962-db64718a6a54', '52267c3a-62a0-542f-8ec1-9d82bd521edc', 'B', 'Oral antibiotics', false, 1),
  ('332d3582-9e48-5086-b2c0-6759f3ad1731', '52267c3a-62a0-542f-8ec1-9d82bd521edc', 'C', 'Incision in the GP surgery for all', false, 2),
  ('2cdbcdc1-b159-5f0b-b3c0-a415108af6c4', '52267c3a-62a0-542f-8ec1-9d82bd521edc', 'D', 'Warm compresses; most styes resolve spontaneously', true, 3),
  ('6d4e0426-8cbd-5671-835f-8e8eb164ceb8', '52267c3a-62a0-542f-8ec1-9d82bd521edc', 'E', 'Urgent ophthalmology referral', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8346256e-fb95-53a0-9b2a-bc60d1d227e7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 50 year old man has had heartburn controlled on lansoprazole for 5 years. He has no alarm features. What is the SINGLE most appropriate review action?', 'NICE recommends an annual review of long-term PPI use, trying to step down to the lowest effective dose or on-demand use where possible. Long-term PPIs are linked to hypomagnesaemia, C. difficile infection, fractures, B12 deficiency and pneumonia. Lifestyle measures should be reinforced.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
