  ('166b3b57-efb0-5fd7-b8be-7da8af63d801', '8346256e-fb95-53a0-9b2a-bc60d1d227e7', 'A', 'Increase the dose', false, 0),
  ('9b3770ee-21f4-5c45-9a65-dc68958fa0c2', '8346256e-fb95-53a0-9b2a-bc60d1d227e7', 'B', 'Continue indefinitely without review', false, 1),
  ('3c892403-548c-5c1c-94f2-89f0ff92e4c9', '8346256e-fb95-53a0-9b2a-bc60d1d227e7', 'C', 'Add an H2 blocker', false, 2),
  ('582e87d4-6a3e-561d-84ba-c53d302d7ec3', '8346256e-fb95-53a0-9b2a-bc60d1d227e7', 'D', 'Refer for fundoplication', false, 3),
  ('638d1e8a-d898-5cc1-8d4a-abdb59a70c04', '8346256e-fb95-53a0-9b2a-bc60d1d227e7', 'E', 'Review the need for ongoing PPI and try stepping down to the lowest effective dose or ''as required'' use', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8f528f1f-8615-5778-a5f1-10c64d002e13', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 33 year old woman has had a headache on most days for 3 months. She takes co-codamol most days for her headaches. Examination is normal. What is the SINGLE most likely diagnosis?', 'Medication overuse headache occurs on 15 or more days a month with regular use of analgesics (opioids or combination analgesics on 10 or more days a month, simple analgesics on 15 or more days). Management is stopping the overused medication abruptly (opioids may be withdrawn gradually), warning that symptoms may worsen first, and treating the underlying headache disorder with prophylaxis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2d47f61a-eaa7-541d-baee-3c4f202f81a0', '8f528f1f-8615-5778-a5f1-10c64d002e13', 'A', 'Medication overuse headache', true, 0),
  ('52ff5ad6-69bb-59a0-8d4b-e85ef815e5f8', '8f528f1f-8615-5778-a5f1-10c64d002e13', 'B', 'Cluster headache', false, 1),
  ('c44bc2d9-b6de-5c33-8780-1a569d482c01', '8f528f1f-8615-5778-a5f1-10c64d002e13', 'C', 'Temporal arteritis', false, 2),
  ('85ffc94e-4a9a-5ccb-ae1a-0e814cd9297d', '8f528f1f-8615-5778-a5f1-10c64d002e13', 'D', 'Idiopathic intracranial hypertension', false, 3),
  ('b02e1bef-8001-51ad-91f3-84a89f61d95b', '8f528f1f-8615-5778-a5f1-10c64d002e13', 'E', 'Brain tumour', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('55a85b01-9fb3-5a4f-8c88-735fb334fb61', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 26 year old man has had sneezing, itchy watery eyes and a runny nose every spring and summer for several years. What is the SINGLE most appropriate first-line treatment?', 'Seasonal allergic rhinitis (hay fever) is treated with allergen avoidance, non-sedating antihistamines and intranasal steroids, which are the most effective for nasal symptoms when used regularly. Antihistamine eye drops help ocular symptoms. Decongestants should be limited to 7 days because of rebound congestion. Immunotherapy is for severe cases.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d017bd27-2879-502c-949a-d83baedd5cf3', '55a85b01-9fb3-5a4f-8c88-735fb334fb61', 'A', 'Long-term oral prednisolone', false, 0),
  ('c79a55ad-38eb-5874-894b-d0e473783f55', '55a85b01-9fb3-5a4f-8c88-735fb334fb61', 'B', 'Nasal decongestant for months', false, 1),
  ('34dc93bc-b088-53b2-914d-9529c0bfc262', '55a85b01-9fb3-5a4f-8c88-735fb334fb61', 'C', 'Antibiotics', false, 2),
  ('5af82660-b650-5f2d-8158-744f93f118e4', '55a85b01-9fb3-5a4f-8c88-735fb334fb61', 'D', 'IM depot steroid injection routinely', false, 3),
  ('43e1c21b-1f18-50fe-84ad-03668c46675d', '55a85b01-9fb3-5a4f-8c88-735fb334fb61', 'E', 'Intranasal corticosteroid and/or non-sedating oral antihistamine', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('eaf298dd-ecd2-5225-af23-1d7fce34a5f6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 44 year old woman asks for a ''fit note'' for 3 days of work missed because of gastroenteritis. What is the SINGLE most appropriate response?', 'In the UK, employees can self-certify sickness for the first 7 calendar days. A fit note (statement of fitness for work) is needed after 7 days and can be issued by doctors, nurses, pharmacists, OTs and physiotherapists. It can say ''not fit for work'' or ''may be fit for work'' with adjustments.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6b982219-1e41-502c-9b49-55ecc9b04a1e', 'eaf298dd-ecd2-5225-af23-1d7fce34a5f6', 'A', 'She can self-certify for up to 7 days; a fit note is not needed', true, 0),
  ('a230397f-a8c0-55b6-85cf-3508321321b6', 'eaf298dd-ecd2-5225-af23-1d7fce34a5f6', 'B', 'Refuse and advise she returns to work', false, 1),
  ('6ee341bc-096a-578a-b4de-96c1aa914ca8', 'eaf298dd-ecd2-5225-af23-1d7fce34a5f6', 'C', 'Refer to occupational health', false, 2),
  ('aea19006-75b2-5ce7-b369-49ed84e17d39', 'eaf298dd-ecd2-5225-af23-1d7fce34a5f6', 'D', 'Issue a fit note for 3 days', false, 3),
  ('54de5249-d5b9-5a2b-a1c7-fad36bb69408', 'eaf298dd-ecd2-5225-af23-1d7fce34a5f6', 'E', 'Issue a fit note for 1 month', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3030479f-c077-5596-b126-afe431411e8b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 55 year old man has had erectile dysfunction, fatigue, low libido and reduced muscle mass. His morning testosterone is low on two occasions. What is the SINGLE most appropriate next step?', 'Low testosterone confirmed on two early-morning samples needs LH and FSH. High LH and FSH means primary (testicular) failure, as in Klinefelter syndrome or orchitis. Low or normal LH and FSH means secondary (pituitary or hypothalamic) failure, which needs prolactin, other pituitary hormones and MRI. Obesity, opioids and chronic illness can suppress testosterone.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a1383ff0-267f-5bee-b48b-b7f9243ad211', '3030479f-c077-5596-b126-afe431411e8b', 'A', 'Reassure', false, 0),
  ('53448fbc-8241-5a36-b839-fee50e07384d', '3030479f-c077-5596-b126-afe431411e8b', 'B', 'Refer for vasectomy', false, 1),
  ('1b6888f6-705b-5698-8ffe-de021e4d82b5', '3030479f-c077-5596-b126-afe431411e8b', 'C', 'Measure LH, FSH and prolactin to distinguish primary from secondary hypogonadism', true, 2),
  ('5980cc36-b9a4-54c4-9407-0a65422dd35b', '3030479f-c077-5596-b126-afe431411e8b', 'D', 'Start testosterone immediately without further tests', false, 3),
  ('139e06e8-0c51-580d-9b72-42193ddc7c4c', '3030479f-c077-5596-b126-afe431411e8b', 'E', 'Start sildenafil only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b5dc004a-ac14-5a77-bc79-80f1aa642f92', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 32 year old woman has had palpitations, anxiety and a fine tremor, with weight loss. She gave birth 4 months ago. TSH is suppressed, free T4 raised, and her thyroid is non-tender. TRAb is negative and isotope uptake is low. What is the SINGLE most likely diagnosis?', 'Postpartum thyroiditis occurs within a year of delivery. There is often a hyperthyroid phase (1-4 months, with low isotope uptake and negative TRAb), then a hypothyroid phase, then recovery. The hyperthyroid phase is treated with propranolol (antithyroid drugs are ineffective), and the hypothyroid phase with levothyroxine if symptomatic. It recurs in later pregnancies, and permanent hypothyroidism can develop.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6f80544a-7567-549d-bd9a-20345669759d', 'b5dc004a-ac14-5a77-bc79-80f1aa642f92', 'A', 'Graves'' disease', false, 0),
  ('3a9da822-c6d5-5461-8333-f13bfd2c6fb4', 'b5dc004a-ac14-5a77-bc79-80f1aa642f92', 'B', 'Factitious thyrotoxicosis', false, 1),
  ('8c174c3d-2322-5123-8538-8f18a43637d3', 'b5dc004a-ac14-5a77-bc79-80f1aa642f92', 'C', 'Toxic multinodular goitre', false, 2),
  ('2a338bc8-5c9f-59ac-90d0-f93fdc643b2f', 'b5dc004a-ac14-5a77-bc79-80f1aa642f92', 'D', 'Postpartum thyroiditis', true, 3),
  ('386765f1-06ba-5d73-b79d-70d4a8287151', 'b5dc004a-ac14-5a77-bc79-80f1aa642f92', 'E', 'Subacute (de Quervain''s) thyroiditis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5fae9e93-1c14-5c13-955a-89336c94257e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 68 year old man has had progressive swelling of both ankles. He takes amlodipine 10 mg, and his BP is well controlled. His JVP is normal, urinalysis is normal and his albumin is normal. Echo and NT-proBNP are normal. What is the SINGLE most likely cause?', 'Dihydropyridine calcium channel blockers (amlodipine, nifedipine) cause dose-related ankle oedema from precapillary vasodilation. Diuretics are not effective. Options are reducing the dose, switching to another class, or adding an ACE inhibitor or ARB. Other causes of bilateral oedema include heart failure, hypoalbuminaemia, venous insufficiency and hypothyroidism.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6aace652-36af-5077-b784-1c4f01297f8b', '5fae9e93-1c14-5c13-955a-89336c94257e', 'A', 'Liver cirrhosis', false, 0),
  ('0f9f9dd4-184a-5f44-ae56-727346293b59', '5fae9e93-1c14-5c13-955a-89336c94257e', 'B', 'Heart failure', false, 1),
  ('55f7e3c2-e0f4-5f26-b2a0-489af8654cdd', '5fae9e93-1c14-5c13-955a-89336c94257e', 'C', 'DVT', false, 2),
  ('38fae0f9-24b1-51d9-bf06-bea07f2d1538', '5fae9e93-1c14-5c13-955a-89336c94257e', 'D', 'Nephrotic syndrome', false, 3),
  ('1c841a62-b200-50dc-9d0c-f4a1478fd865', '5fae9e93-1c14-5c13-955a-89336c94257e', 'E', 'Calcium channel blocker-induced oedema', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ac56d144-f198-5557-a849-ec173ce6aa08', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 35 year old man has had a sudden painful red swollen left calf after a long-haul flight. His Wells score is 2. Ultrasound will not be available for 2 days. What is the SINGLE most appropriate action?', 'With a ''likely'' DVT (Wells 2 or more) where ultrasound cannot be done within 4 hours, NICE recommends a D-dimer and interim therapeutic anticoagulation, with ultrasound within 24 hours where possible. If the scan is negative but the D-dimer is positive, it is repeated in 6-8 days. Confirmed DVT is treated with apixaban or rivaroxaban.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c3ab8b5b-3b69-57d6-8784-9939e8ccf571', 'ac56d144-f198-5557-a849-ec173ce6aa08', 'A', 'Start interim anticoagulation (e.g. apixaban) and arrange ultrasound as soon as possible', true, 0),
  ('0f627132-ed45-5379-a4e0-f090871b1d59', 'ac56d144-f198-5557-a849-ec173ce6aa08', 'B', 'Give aspirin and discharge', false, 1),
  ('7b5221cd-1e0a-5732-b6af-dc05218f5021', 'ac56d144-f198-5557-a849-ec173ce6aa08', 'C', 'D-dimer alone with no further action', false, 2),
  ('4f43c5fc-cf5e-5432-a640-0f8c3e488069', 'ac56d144-f198-5557-a849-ec173ce6aa08', 'D', 'Wait 2 days without treatment', false, 3),
  ('08c296c6-9517-55a1-96b5-85fa73e9304a', 'ac56d144-f198-5557-a849-ec173ce6aa08', 'E', 'Compression stockings and discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2b1ce427-b81f-599f-b3cc-58d3b9483514', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 65 year old man has had recurrent episodes of lower back pain and wants to keep active. He asks about the role of imaging. He has no red flags. What is the SINGLE most appropriate advice?', 'NICE (NG59) recommends against routine imaging for non-specific low back pain in primary care, because imaging findings often correlate poorly with symptoms and can lead to unnecessary treatment. Imaging is reserved for red flags (cancer, infection, fracture, cauda equina) or when the result would change management. The STarT Back tool helps stratify risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ffbfe4fa-1f8b-5686-8792-754c0e27b1ce', '2b1ce427-b81f-599f-b3cc-58d3b9483514', 'A', 'An X-ray is essential to diagnose back pain', false, 0),
  ('cb144ade-a29c-5b49-a593-b4c0e8b38d58', '2b1ce427-b81f-599f-b3cc-58d3b9483514', 'B', 'Bone scan annually', false, 1),
  ('7c7a7fc1-e1bf-55b8-b8ff-b6862e291a1f', '2b1ce427-b81f-599f-b3cc-58d3b9483514', 'C', 'CT scan for all', false, 2),
  ('88b4fd2d-4814-5057-9a97-9010d3eaa644', '2b1ce427-b81f-599f-b3cc-58d3b9483514', 'D', 'An MRI is needed every 6 months', false, 3),
  ('f898c234-c3dc-595a-904b-532f49858f2c', '2b1ce427-b81f-599f-b3cc-58d3b9483514', 'E', 'Imaging is not routinely needed for non-specific low back pain without red flags', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('87d16e0c-3b06-5351-9ed2-30b04d9f41d4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 30 year old woman attends a genetics clinic. Her mother was recently diagnosed with autosomal dominant polycystic kidney disease (ADPKD). Her father is healthy with no family history of kidney disease. She has not had genetic testing or imaging. She is planning a pregnancy with a partner who has no family history. What is the chance that her future child will inherit ADPKD?', 'ADPKD is autosomal dominant. Her affected mother is almost certainly heterozygous, so the woman has a 50% (1/2) chance of carrying the variant. If she carries it, each child has a 50% chance of inheriting it. Because her own status is unknown, the overall risk to her child is 1/2 x 1/2 = 1/4, or 25%.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d6d70bda-06ec-5559-a499-5c011ca39b02', '87d16e0c-3b06-5351-9ed2-30b04d9f41d4', 'A', '0%', false, 0),
  ('cc91b16e-07ab-511b-a7dc-51079325ac45', '87d16e0c-3b06-5351-9ed2-30b04d9f41d4', 'B', '12.5%', false, 1),
  ('8594f877-da12-5cec-95ba-1cb4188418e5', '87d16e0c-3b06-5351-9ed2-30b04d9f41d4', 'C', '25%', true, 2),
  ('10ced624-d3ac-5489-bfa6-5e74f7746471', '87d16e0c-3b06-5351-9ed2-30b04d9f41d4', 'D', '50%', false, 3),
  ('11bcc940-71d3-5612-8562-656a59022941', '87d16e0c-3b06-5351-9ed2-30b04d9f41d4', 'E', '100%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8a45172f-3906-5186-9d5f-72a23d40eb23', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 28 year old woman is a known carrier of Duchenne muscular dystrophy, confirmed on genetic testing after her brother was diagnosed. Her partner is healthy. They are expecting a baby boy and ask about the risk to their son. What is the chance that their son will be affected by Duchenne muscular dystrophy?', 'Duchenne muscular dystrophy is X-linked recessive. A carrier mother passes her affected X chromosome to half of her children. A son gets his only X chromosome from his mother and his Y from his father, so each son has a 50% chance of being affected. Each daughter has a 50% chance of being a carrier, and daughters are usually unaffected.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c3282094-af9a-514b-9fbb-2b876abe4770', '8a45172f-3906-5186-9d5f-72a23d40eb23', 'A', '0%', false, 0),
  ('12c62e18-93f2-56a0-8124-a44ef24aee62', '8a45172f-3906-5186-9d5f-72a23d40eb23', 'B', '25%', false, 1),
  ('78a9fd77-f325-5b00-b5da-e52f4389530d', '8a45172f-3906-5186-9d5f-72a23d40eb23', 'C', '33%', false, 2),
  ('0cf4e24a-1b03-5fc4-ad7b-95e7a2988dbb', '8a45172f-3906-5186-9d5f-72a23d40eb23', 'D', '50%', true, 3),
  ('b83711aa-95be-5a3e-915a-e8457f267e60', '8a45172f-3906-5186-9d5f-72a23d40eb23', 'E', '100%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('57133e9b-18e2-5d31-8980-bc551967f2d4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 38 year old woman is 11 weeks pregnant. Her previous pregnancy was affected by trisomy 18. She wants a definitive diagnostic test for chromosomal abnormality as early as possible in this pregnancy and understands the procedure-related risk of miscarriage. What is the SINGLE most appropriate investigation at this stage?', 'Chorionic villus sampling (CVS) is a diagnostic test that can be done from 11 to 14 weeks, so it is the earliest definitive option. Amniocentesis is also diagnostic but is done from 15 weeks. The combined test, NIPT and nuchal translucency scan are screening tests: they give a risk or a high-chance result, but a positive result still needs a diagnostic test to confirm it.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('24f2dca0-bae7-53cb-b766-04466bfc689f', '57133e9b-18e2-5d31-8980-bc551967f2d4', 'A', 'Non-invasive prenatal testing (NIPT)', false, 0),
  ('0413dbfb-b5e6-501b-a553-2466a1ff6dab', '57133e9b-18e2-5d31-8980-bc551967f2d4', 'B', 'Nuchal translucency scan alone', false, 1),
  ('9ca90679-c4bb-5b9a-aa81-6769510201da', '57133e9b-18e2-5d31-8980-bc551967f2d4', 'C', 'Chorionic villus sampling', true, 2),
  ('2919c9eb-23a4-5e20-9f02-972b17baee2d', '57133e9b-18e2-5d31-8980-bc551967f2d4', 'D', 'Amniocentesis', false, 3),
  ('f01d88bf-fc24-5f76-928e-4fdb3fe51388', '57133e9b-18e2-5d31-8980-bc551967f2d4', 'E', 'Combined test', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bd39d68b-544e-5bd9-9455-463e2b925703', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A couple attend genetic counselling. Both are carriers of cystic fibrosis, confirmed by testing after a cousin was diagnosed. Neither has symptoms. They are planning their first pregnancy. What is the chance that their child will have cystic fibrosis?', 'Cystic fibrosis is autosomal recessive. When both parents are carriers (heterozygous), each child has a 1 in 4 (25%) chance of being affected, a 1 in 2 (50%) chance of being a carrier and a 1 in 4 chance of being neither. 67% (2/3) is the chance that an unaffected sibling of an affected child is a carrier, a common distractor. Prenatal diagnosis (CVS) or preimplantation genetic testing can be offered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0095ef8c-f4b6-552c-95ce-adebab980763', 'bd39d68b-544e-5bd9-9455-463e2b925703', 'A', '0%', false, 0),
  ('42533cda-0fbe-5d07-b1d3-266f44ef7f37', 'bd39d68b-544e-5bd9-9455-463e2b925703', 'B', '25%', true, 1),
  ('277a53b3-fe86-5f98-a78e-5ada3d7a4437', 'bd39d68b-544e-5bd9-9455-463e2b925703', 'C', '50%', false, 2),
  ('66ae9e1e-eca3-502a-bf92-f4173079e90e', 'bd39d68b-544e-5bd9-9455-463e2b925703', 'D', '67%', false, 3),
  ('91a45606-0544-5c07-b2de-fe084404aa6e', 'bd39d68b-544e-5bd9-9455-463e2b925703', 'E', '100%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('43069741-9c77-5938-bc2d-ecc32bab70bd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 26 year old man has an older brother with cystic fibrosis. Both parents are healthy. The man himself is healthy and has no symptoms of cystic fibrosis. He has not been tested. What is the chance that he is a carrier?', 'Both parents must be carriers because they have an affected child. The possible outcomes for each child are affected (1/4), carrier (2/4) and non-carrier (1/4). As he is unaffected, the affected outcome is excluded, leaving carrier in 2 of the 3 remaining outcomes: 2/3, about 67%. This is a classic genetics calculation in which the known phenotype changes the denominator.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a97a11e6-6a50-5097-afa1-dde48e0b958e', '43069741-9c77-5938-bc2d-ecc32bab70bd', 'A', '25%', false, 0),
  ('f5a1a81f-34aa-58c0-bc22-cfff89134b48', '43069741-9c77-5938-bc2d-ecc32bab70bd', 'B', '33%', false, 1),
  ('f0a8d3ca-96d2-5e38-b97b-32b4c2ce76b1', '43069741-9c77-5938-bc2d-ecc32bab70bd', 'C', '50%', false, 2),
  ('bccee569-da83-5d24-b8c6-8dec5c83017f', '43069741-9c77-5938-bc2d-ecc32bab70bd', 'D', '67%', true, 3),
  ('330bd6db-b9d1-5123-abbe-b5f67e118538', '43069741-9c77-5938-bc2d-ecc32bab70bd', 'E', '100%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c5c7fe6-b43f-5007-a91e-009b08c6e003', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 12 year old girl is short and has not started puberty. She has a webbed neck, a broad chest with widely spaced nipples and a low posterior hairline. She had coarctation of the aorta repaired as a baby. What is the SINGLE most likely karyotype?', 'Short stature, delayed puberty (primary ovarian insufficiency), a webbed neck, a shield chest and coarctation of the aorta are features of Turner syndrome (45,X). Bicuspid aortic valve and horseshoe kidney are also associated. Treatment includes growth hormone and oestrogen replacement. 47,XXY is Klinefelter syndrome (tall males with hypogonadism and gynaecomastia).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('08f97398-f19e-5bea-811e-3e9d0393faf9', '9c5c7fe6-b43f-5007-a91e-009b08c6e003', 'A', '46,XY', false, 0),
  ('c00cb0e1-2b5b-50f7-8a2f-ebf46a734a7c', '9c5c7fe6-b43f-5007-a91e-009b08c6e003', 'B', '47,XXY', false, 1),
  ('822f6ce2-25f1-5e2d-8884-b1e240847cd7', '9c5c7fe6-b43f-5007-a91e-009b08c6e003', 'C', '47,XX,+21', false, 2),
  ('20f64a49-325e-5d3e-b9f3-5a98e69e2124', '9c5c7fe6-b43f-5007-a91e-009b08c6e003', 'D', '45,X', true, 3),
  ('b39fb187-372c-5c84-ad73-c243c8e7d622', '9c5c7fe6-b43f-5007-a91e-009b08c6e003', 'E', '47,XXX', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8b6f53b8-1dd7-532f-a230-8d104638467e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A newborn baby has hypotonia, upslanting palpebral fissures, epicanthic folds, a single palmar crease and a sandal gap between the first and second toes. An echocardiogram shows an atrioventricular septal defect. What is the SINGLE most likely underlying cause?', 'These are typical features of Down syndrome. AVSD is the characteristic cardiac defect, and associations include duodenal atresia, Hirschsprung''s disease, hypothyroidism, acute leukaemia and early-onset Alzheimer''s disease. About 95% of cases are caused by non-disjunction (risk rises with maternal age), with a smaller number from Robertsonian translocation (which needs parental karyotyping). Edwards syndrome causes rocker-bottom feet and overlapping fingers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dd881189-aecb-5376-ada9-279f4bc9ddf5', '8b6f53b8-1dd7-532f-a230-8d104638467e', 'A', 'Trisomy 18 (Edwards syndrome)', false, 0),
  ('099993d8-b383-5581-90f4-2c44703def0c', '8b6f53b8-1dd7-532f-a230-8d104638467e', 'B', 'Trisomy 21 (Down syndrome)', true, 1),
  ('a29eb621-0168-564e-953e-7ced2d7b9ac9', '8b6f53b8-1dd7-532f-a230-8d104638467e', 'C', 'Fragile X syndrome', false, 2),
  ('783ec718-1f50-5c9e-9bb7-0f02528a95c8', '8b6f53b8-1dd7-532f-a230-8d104638467e', 'D', 'Trisomy 13 (Patau syndrome)', false, 3),
  ('8d7b8203-3df5-525d-8b83-090abd829a4a', '8b6f53b8-1dd7-532f-a230-8d104638467e', 'E', 'Turner syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5b3f574f-8649-56c7-9321-8cc22aa25d20', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 34 year old woman''s mother was diagnosed with breast cancer at 38 and ovarian cancer at 50. Her maternal aunt had breast cancer at 42. The woman has no symptoms and a normal breast examination. What is the SINGLE most appropriate next step?', 'A strong family history of early breast cancer and ovarian cancer on the same side suggests a BRCA1/2 pathogenic variant (autosomal dominant). NICE recommends referral for specialist assessment when there is a first-degree relative with breast cancer under 40, or with breast and ovarian cancer. If a variant is found, options include enhanced surveillance (annual MRI), chemoprevention and risk-reducing surgery.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2f8ad486-b7c8-579d-a47e-5f90e837e67f', '5b3f574f-8649-56c7-9321-8cc22aa25d20', 'A', 'Perform a CA-125 test monthly', false, 0),
  ('5142f5a6-8ade-5cca-80ca-4281aec94d69', '5b3f574f-8649-56c7-9321-8cc22aa25d20', 'B', 'Refer to secondary care or a specialist genetics service for risk assessment and possible BRCA testing', true, 1),
  ('9935f513-26cd-5c39-91e1-5014dd984a8d', '5b3f574f-8649-56c7-9321-8cc22aa25d20', 'C', 'Reassure and advise breast screening from age 50', false, 2),
  ('dad8d25a-57fc-5c32-9bbf-ebc0a63e947e', '5b3f574f-8649-56c7-9321-8cc22aa25d20', 'D', 'Start tamoxifen in primary care', false, 3),
  ('d309f122-7eea-56e9-a44d-72a0206cc9db', '5b3f574f-8649-56c7-9321-8cc22aa25d20', 'E', 'Arrange an immediate bilateral mastectomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f418dac7-b1b7-58cc-b608-d98b9a309aed', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 14 year old boy has learning difficulties, a long face with large protruding ears, a prominent jaw and enlarged testes. His maternal uncle had similar features. What is the SINGLE most likely diagnosis?', 'Fragile X syndrome is the most common inherited cause of learning disability. It is X-linked and caused by a CGG trinucleotide repeat expansion in the FMR1 gene. Features include a long face, large ears, macro-orchidism after puberty, hypermobility and autistic features. Repeats can expand when passed through the maternal line (anticipation). Diagnosis is by DNA testing for the repeat length.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1476db06-37f0-5311-ae86-166d7ee2e5eb', 'f418dac7-b1b7-58cc-b608-d98b9a309aed', 'A', 'Marfan syndrome', false, 0),
  ('f38af8d4-5e10-5d8a-ba59-fe2f8cae4162', 'f418dac7-b1b7-58cc-b608-d98b9a309aed', 'B', 'Klinefelter syndrome', false, 1),
  ('a07ae63c-2a7d-529a-a097-5950b5b95234', 'f418dac7-b1b7-58cc-b608-d98b9a309aed', 'C', 'Down syndrome', false, 2),
  ('7b9f5fc3-90f0-57d0-816f-b53fd58fbd04', 'f418dac7-b1b7-58cc-b608-d98b9a309aed', 'D', 'Fragile X syndrome', true, 3),
  ('dd0dd6ec-b510-516a-87dd-c7b79dfcf4df', 'f418dac7-b1b7-58cc-b608-d98b9a309aed', 'E', 'Prader-Willi syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a692715e-b696-5d25-b529-73cb7f3eb80a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 30 year old woman has a son with Duchenne muscular dystrophy. She is pregnant with a girl. What is the chance that her daughter will be a carrier, assuming she herself is a confirmed carrier and her partner is unaffected?', 'In X-linked recessive inheritance from a carrier mother and unaffected father, each daughter has a 50% chance of being a carrier (and is usually unaffected), and each son has a 50% chance of being affected. Female carriers of DMD may have mild muscle weakness or cardiomyopathy and should have cardiac screening.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
