  ('6f60602c-4908-5d39-8142-abb6ef1e5673', 'a692715e-b696-5d25-b529-73cb7f3eb80a', 'A', '0%', false, 0),
  ('51df0281-c006-5474-bc20-3fd18b179ae3', 'a692715e-b696-5d25-b529-73cb7f3eb80a', 'B', '25%', false, 1),
  ('c29a780a-1fd6-5562-add8-3d5f6b78c695', 'a692715e-b696-5d25-b529-73cb7f3eb80a', 'C', '50%', true, 2),
  ('b194ebdc-cb6e-5a3c-8852-7ebf07491f8c', 'a692715e-b696-5d25-b529-73cb7f3eb80a', 'D', '75%', false, 3),
  ('21b1ccbc-ed8a-5034-9017-7bbc7dac1305', 'a692715e-b696-5d25-b529-73cb7f3eb80a', 'E', '100%', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('339622cb-8eee-53ff-bd21-b9c714247d5a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A man with haemophilia A (X-linked recessive) and an unaffected woman (not a carrier) have children. What is the chance that their son will be affected?', 'An affected father passes his X chromosome to all his daughters (who are all obligate carriers) and his Y chromosome to all his sons. So none of his sons will be affected (no male-to-male transmission in X-linked conditions), and all daughters will be carriers. The absence of male-to-male transmission helps distinguish X-linked from autosomal dominant inheritance.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
