  ('1454f32c-61ff-57ad-87c4-09c7361cdb5a', '339622cb-8eee-53ff-bd21-b9c714247d5a', 'A', '0%', true, 0),
  ('3dca1b61-1fac-581e-a2a3-e07030800665', '339622cb-8eee-53ff-bd21-b9c714247d5a', 'B', '25%', false, 1),
  ('9418fef7-5e29-59eb-b7bb-1f0c94f785c0', '339622cb-8eee-53ff-bd21-b9c714247d5a', 'C', '50%', false, 2),
  ('9bdb4335-2b0e-57d2-a218-c92519e7f13b', '339622cb-8eee-53ff-bd21-b9c714247d5a', 'D', '75%', false, 3),
