insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('63a53233-b6c7-56d8-8ac9-3210055e0115', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A man with an autosomal dominant condition (heterozygous) and an unaffected partner have a child. What is the chance that their child is affected?', 'In autosomal dominant inheritance, an affected heterozygous parent passes the variant to each child with a 50% (1/2) chance, regardless of sex. Examples include Huntington''s disease, ADPKD, Marfan syndrome, neurofibromatosis type 1, familial hypercholesterolaemia and BRCA1/2. Features include incomplete penetrance, variable expressivity and new mutations.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
