  ('d7ea7548-c937-582c-91e1-3d2241ccac38', '63a53233-b6c7-56d8-8ac9-3210055e0115', 'A', '0%', false, 0),
  ('4cfcbef2-5a9c-5601-b666-54e0373adb53', '63a53233-b6c7-56d8-8ac9-3210055e0115', 'B', '25%', false, 1),
  ('03142096-ef2f-5a57-bde3-d80400a056db', '63a53233-b6c7-56d8-8ac9-3210055e0115', 'C', '50%', true, 2),
  ('f94c9e46-b058-5eb3-84a8-4110b85c95a2', '63a53233-b6c7-56d8-8ac9-3210055e0115', 'D', '75%', false, 3),
