insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('34256fdb-0f3a-516b-a679-e7659736b429', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 30 year old woman''s mother has myotonic dystrophy. The mother''s symptoms began at 50, but the woman developed symptoms at 25, and her son was born with severe congenital hypotonia. What genetic phenomenon explains the earlier and more severe onset?', 'Anticipation is earlier onset and greater severity in successive generations. It happens in trinucleotide repeat disorders because the repeats expand: myotonic dystrophy (CTG, especially through maternal transmission, with congenital forms), Huntington''s disease (CAG, especially through paternal transmission), Fragile X (CGG) and Friedreich''s ataxia (GAA). Genetic counselling is important.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d81b6766-be15-5ce6-967f-08a499acbc1b', '34256fdb-0f3a-516b-a679-e7659736b429', 'A', 'Anticipation (trinucleotide repeat expansion)', true, 0),
  ('b2e51240-aa3b-5065-a0d3-ea3002ef89e8', '34256fdb-0f3a-516b-a679-e7659736b429', 'B', 'Incomplete penetrance', false, 1),
  ('064c06b2-0a92-520f-b647-72b95f1fa6fb', '34256fdb-0f3a-516b-a679-e7659736b429', 'C', 'Mosaicism', false, 2),
  ('b3e82fe8-3e1d-5e85-9f57-35dea404d157', '34256fdb-0f3a-516b-a679-e7659736b429', 'D', 'Genomic imprinting', false, 3),
  ('4a2c1b8b-3dc7-51e4-a1a0-b7d975251e15', '34256fdb-0f3a-516b-a679-e7659736b429', 'E', 'Uniparental disomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ef53d5ad-6176-58cc-b040-2fb5407e54ec', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A child has hypotonia and poor feeding in infancy, then develops insatiable appetite, obesity, short stature, learning difficulties and hypogonadism. Genetic testing shows a deletion on the paternally inherited chromosome 15. What is the SINGLE most likely diagnosis?', 'Prader-Willi syndrome comes from loss of paternally expressed genes on 15q11-13 (paternal deletion or maternal uniparental disomy), an example of genomic imprinting. Loss of the maternal copy (UBE3A) causes Angelman syndrome (happy demeanour, seizures, ataxia, severe learning disability).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
