  ('1d66d8c2-c506-5da3-b8ca-4699ce78eecd', 'ef53d5ad-6176-58cc-b040-2fb5407e54ec', 'A', 'Down syndrome', false, 0),
  ('b952c497-4a77-53f0-bf67-912b34bfc4af', 'ef53d5ad-6176-58cc-b040-2fb5407e54ec', 'B', 'Turner syndrome', false, 1),
  ('81ae3200-7b0a-5804-a67c-06ff88779279', 'ef53d5ad-6176-58cc-b040-2fb5407e54ec', 'C', 'Angelman syndrome', false, 2),
  ('38cd377b-2307-5360-b8d3-e8cbb13629a1', 'ef53d5ad-6176-58cc-b040-2fb5407e54ec', 'D', 'Prader-Willi syndrome', true, 3),
  ('cd8f2ae9-4fcd-50b8-948b-af3c80bfe0ab', 'ef53d5ad-6176-58cc-b040-2fb5407e54ec', 'E', 'Fragile X syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1a3fe6e8-61b4-5b9c-bc64-ca3f46fa61f1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A newborn baby has a small jaw, low-set ears, clenched fists with overlapping fingers, rocker-bottom feet and a heart defect. What is the SINGLE most likely karyotype?', 'Edwards syndrome (trisomy 18) causes micrognathia, low-set ears, clenched fists with overlapping fingers, rocker-bottom feet, cardiac defects and severe learning disability, with most babies dying in the first year. Patau syndrome (trisomy 13) causes cleft lip and palate, polydactyly, microcephaly and holoprosencephaly. Both are detected through combined screening and NIPT.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0cb3a3fe-2846-5c83-b02f-00a6c8ac9a0c', '1a3fe6e8-61b4-5b9c-bc64-ca3f46fa61f1', 'A', 'Trisomy 13 (Patau syndrome)', false, 0),
  ('881d1636-7745-5efd-8550-b6122b132159', '1a3fe6e8-61b4-5b9c-bc64-ca3f46fa61f1', 'B', '45,X (Turner syndrome)', false, 1),
  ('d85cfd3e-009f-56a3-9b15-f84995090f1c', '1a3fe6e8-61b4-5b9c-bc64-ca3f46fa61f1', 'C', 'Trisomy 18 (Edwards syndrome)', true, 2),
  ('1ed77cf1-3f4a-5778-bd04-85a792812c94', '1a3fe6e8-61b4-5b9c-bc64-ca3f46fa61f1', 'D', 'Trisomy 21 (Down syndrome)', false, 3),
  ('c63d095d-aa52-5c75-90c4-d3e46c516f4c', '1a3fe6e8-61b4-5b9c-bc64-ca3f46fa61f1', 'E', '47,XXY (Klinefelter syndrome)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('107ea30e-ef58-5667-aa4d-5c496bda183d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 25 year old tall man has had poor progress through puberty, small firm testes, gynaecomastia and infertility. His LH and FSH are high and testosterone is low. What is the SINGLE most likely karyotype?', 'Klinefelter syndrome (47,XXY) causes primary hypogonadism (small firm testes, raised LH and FSH, low testosterone), tall stature, gynaecomastia, infertility (azoospermia) and sometimes learning difficulties. Treatment is testosterone replacement. Sperm retrieval with ICSI may allow fertility. There is an increased risk of breast cancer and osteoporosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('529a2a15-1716-5b0b-bfa8-c890243cfb92', '107ea30e-ef58-5667-aa4d-5c496bda183d', 'A', '45,X', false, 0),
  ('959b7847-e733-551a-a111-692ea4bd996f', '107ea30e-ef58-5667-aa4d-5c496bda183d', 'B', '46,XY', false, 1),
  ('e65419ea-fd68-5b3f-a6cb-4ab3a50c1385', '107ea30e-ef58-5667-aa4d-5c496bda183d', 'C', '46,XX', false, 2),
  ('3f4c7a2a-7ae3-5024-b807-8a1c5317edde', '107ea30e-ef58-5667-aa4d-5c496bda183d', 'D', '47,XXY', true, 3),
  ('637975f9-b4a7-5fd1-ba41-995f0f8f565e', '107ea30e-ef58-5667-aa4d-5c496bda183d', 'E', '47,XYY', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e3ff9349-0034-5027-a826-c74c421f0129', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 10 year old boy has multiple café-au-lait macules (more than six, over 5 mm each), axillary freckling and several soft nodules on his skin. His father has similar features. What is the SINGLE most likely diagnosis?', 'NF1 (autosomal dominant, chromosome 17) causes café-au-lait macules, axillary or inguinal freckling, neurofibromas, Lisch nodules, optic gliomas and bony dysplasia, with risks of hypertension (phaeochromocytoma, renal artery stenosis) and malignant nerve sheath tumours. NF2 (chromosome 22) causes bilateral vestibular schwannomas and meningiomas.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
