  ('61fdfc58-3839-5f7d-9aaa-299794d43e92', 'e3ff9349-0034-5027-a826-c74c421f0129', 'A', 'Peutz-Jeghers syndrome', false, 0),
  ('142bf828-6952-59c5-97a5-30151a070db6', 'e3ff9349-0034-5027-a826-c74c421f0129', 'B', 'Tuberous sclerosis', false, 1),
  ('9b0d4c4c-843f-5c4d-a4ee-3e8888d04fdf', 'e3ff9349-0034-5027-a826-c74c421f0129', 'C', 'Neurofibromatosis type 1', true, 2),
  ('f48958de-75ac-539a-b1a1-18c74d095fa5', 'e3ff9349-0034-5027-a826-c74c421f0129', 'D', 'Neurofibromatosis type 2', false, 3),
  ('60351373-9b28-5158-9d33-848f3796be38', 'e3ff9349-0034-5027-a826-c74c421f0129', 'E', 'McCune-Albright syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a3acd162-9ce7-51fe-8b99-20eda2022615', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 6 year old boy has seizures, learning difficulties and facial angiofibromas over his nose and cheeks. He has hypopigmented ''ash leaf'' macules and a shagreen patch on his lower back. What is the SINGLE most likely diagnosis?', 'Tuberous sclerosis (autosomal dominant, TSC1/TSC2) causes hamartomas in many organs: skin (ash leaf macules, angiofibromas, shagreen patch, periungual fibromas), brain (cortical tubers, causing seizures including infantile spasms, and learning difficulties), kidneys (angiomyolipomas), heart (rhabdomyomas) and lungs. mTOR inhibitors (everolimus) are used.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c5674b31-8a78-5241-bd7f-9200d409859c', 'a3acd162-9ce7-51fe-8b99-20eda2022615', 'A', 'Down syndrome', false, 0),
  ('b58e9763-f114-5ed3-9616-42e946209fd5', 'a3acd162-9ce7-51fe-8b99-20eda2022615', 'B', 'Sturge-Weber syndrome', false, 1),
  ('58579a14-da02-557c-9b92-0d6d6418f1fa', 'a3acd162-9ce7-51fe-8b99-20eda2022615', 'C', 'Neurofibromatosis type 1', false, 2),
  ('c55e597e-84d2-5386-9c05-2022e8d6077b', 'a3acd162-9ce7-51fe-8b99-20eda2022615', 'D', 'Tuberous sclerosis', true, 3),
  ('a6343269-d61d-5bf1-9b94-39f5e6534fb2', 'a3acd162-9ce7-51fe-8b99-20eda2022615', 'E', 'Fragile X syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b33cb6db-b727-5ca4-a801-4a0258fde14a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 22 year old tall man has long fingers, arm span greater than his height, pectus excavatum and an upward lens dislocation. His father died of aortic dissection at 40. What is the SINGLE most important ongoing monitoring?', 'Marfan syndrome (autosomal dominant, FBN1, fibrillin-1) causes tall stature, arachnodactyly, joint hypermobility, upward lens dislocation, mitral valve prolapse and aortic root dilatation, with a risk of dissection. Regular echocardiography is essential. Beta-blockers or ARBs slow aortic dilatation, and prophylactic aortic root surgery is offered at a threshold diameter. Homocystinuria causes downward lens dislocation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6afa59b8-71d6-57e4-9e57-2984c8d2e4a9', 'b33cb6db-b727-5ca4-a801-4a0258fde14a', 'A', 'Renal ultrasound', false, 0),
  ('5ae68591-854f-58b5-8495-3b75f6d5bb0a', 'b33cb6db-b727-5ca4-a801-4a0258fde14a', 'B', 'Regular echocardiography to monitor aortic root dilatation', true, 1),
  ('a58d4889-864a-5d86-b24f-c916beef609d', 'b33cb6db-b727-5ca4-a801-4a0258fde14a', 'C', 'Annual EEG', false, 2),
  ('cb8b615d-62b6-5f54-a556-6fac7f54ec24', 'b33cb6db-b727-5ca4-a801-4a0258fde14a', 'D', 'Bone marrow biopsy', false, 3),
  ('fcfb0d02-5d0a-56b4-9083-a52ef4409e2c', 'b33cb6db-b727-5ca4-a801-4a0258fde14a', 'E', 'Annual colonoscopy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c0b1b63-f73e-5880-9c62-2cc6b0ce7393', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A couple, both of Ashkenazi Jewish descent, ask about genetic carrier testing before starting a family. Which autosomal recessive condition is MOST relevant for carrier screening in this population?', 'Tay-Sachs disease (hexosaminidase A deficiency, a GM2 gangliosidosis) is autosomal recessive with a higher carrier frequency in Ashkenazi Jewish people. It causes progressive neurodegeneration from 6 months, with a cherry-red spot at the macula and death in early childhood. Carrier screening allows informed reproductive choices. Gaucher disease and familial dysautonomia are also more common in this population.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('09d78c51-16dd-5d7d-8980-59302118c586', '9c0b1b63-f73e-5880-9c62-2cc6b0ce7393', 'A', 'Marfan syndrome', false, 0),
  ('06a45bb7-67e1-5ed0-8ad6-bb1405eb7946', '9c0b1b63-f73e-5880-9c62-2cc6b0ce7393', 'B', 'Tay-Sachs disease', true, 1),
  ('77c7b003-301c-5a0c-ac62-9a780826cfb8', '9c0b1b63-f73e-5880-9c62-2cc6b0ce7393', 'C', 'Duchenne muscular dystrophy', false, 2),
  ('9258ccc7-b6f4-584a-978f-2ba51e969cd4', '9c0b1b63-f73e-5880-9c62-2cc6b0ce7393', 'D', 'Haemophilia A', false, 3),
  ('e74bd714-45fd-5d3f-9d9c-12b654ea3032', '9c0b1b63-f73e-5880-9c62-2cc6b0ce7393', 'E', 'Huntington''s disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('938ca274-fce1-5b75-a959-a8826e94f90b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 40 year old man has a pathogenic BRCA2 variant. He asks about his cancer risks. Which cancer risks are MOST increased in male BRCA2 carriers?', 'BRCA2 carriers have increased risks of breast cancer (including male breast cancer), prostate cancer (often more aggressive), pancreatic cancer and melanoma. Female BRCA1/2 carriers have high lifetime risks of breast and ovarian cancer. Cascade testing of relatives is important, because each first-degree relative has a 50% chance of carrying the variant.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2f1d6ac9-f1d1-5fd1-a9af-3a38272d6bc4', '938ca274-fce1-5b75-a959-a8826e94f90b', 'A', 'Colorectal cancer only', false, 0),
  ('d9e5433c-d3c8-5451-8597-1da1dd82cdc8', '938ca274-fce1-5b75-a959-a8826e94f90b', 'B', 'Prostate cancer and male breast cancer (also pancreatic cancer)', true, 1),
  ('9acb6e25-2836-5df6-9ab7-d472fec2ba68', '938ca274-fce1-5b75-a959-a8826e94f90b', 'C', 'No increased risk in men', false, 2),
  ('70d240a8-a82c-59fb-b185-fd66587e2b9c', '938ca274-fce1-5b75-a959-a8826e94f90b', 'D', 'Lung cancer only', false, 3),
  ('af472041-9ab1-5711-81e5-5ebbcdcac5ef', '938ca274-fce1-5b75-a959-a8826e94f90b', 'E', 'Testicular cancer only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3372621a-cf23-590f-a36b-563f47b6869d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 64-year old man has recently been diagnosed with dementia. As part of investigations, he is found to have the Huntington''s disease gene. His family tree is shown; the index case is shown by the arrow. The other family members have not yet been tested.  [In the family tree (an image in the original paper), the index case''s son has not been tested; the grandson is the son''s child.] What is the risk that his grandson has Huntington’s disease?', 'Huntington''s disease is autosomal dominant. The affected index case passes it to each child with a 1 in 2 chance. His grandson inherits it only if the untested parent (his child) carries it (1/2) and then passes it on (1/2), giving 1/2 x 1/2 = 1 in 4. (The original question shows a family tree; the key relationships are described here.)', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6888c597-10a4-5eb8-a4a8-6df0959ad2f5', '3372621a-cf23-590f-a36b-563f47b6869d', 'A', '1 in 2', false, 0),
  ('1a40d386-a0a0-5fb1-a2d0-982a7f8c2e38', '3372621a-cf23-590f-a36b-563f47b6869d', 'B', '1 in 4', true, 1),
  ('b721341b-51dc-50c2-be1f-22319c535f64', '3372621a-cf23-590f-a36b-563f47b6869d', 'C', '1 in 8', false, 2),
  ('5ad432e9-8ac3-5795-a2bf-70674348061e', '3372621a-cf23-590f-a36b-563f47b6869d', 'D', '3 in 4', false, 3),
  ('d6640ad7-143e-58b8-9416-feb4283c8006', '3372621a-cf23-590f-a36b-563f47b6869d', 'E', 'No risk', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f81edada-1d30-5331-b868-29a1242df97a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 66 year old man attends his GP with tiredness. Blood tests show haemoglobin 98 g/L, MCV 72 fL and ferritin 6 micrograms/L. He has no visible GI bleeding, no change in bowel habit and no weight loss. He eats a normal diet and takes no regular medication. What is the SINGLE most appropriate next step?', 'Unexplained iron deficiency anaemia in a man, or in a postmenopausal woman, should be treated as GI malignancy until proven otherwise. NICE recommends a suspected cancer pathway referral (with FIT testing where local pathways require it) for gastroscopy and colonoscopy. Iron replacement should be started too, but not instead of investigation. Coeliac serology is also recommended.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e5e64376-fb5c-509b-8c1a-98c38e47e1e2', 'f81edada-1d30-5331-b868-29a1242df97a', 'A', 'Suspected cancer (two-week wait) referral for upper and lower GI investigation', true, 0),
  ('7a01b946-3358-53b3-a560-0ac5fbc162ea', 'f81edada-1d30-5331-b868-29a1242df97a', 'B', 'Oral iron and repeat blood count in 3 months', false, 1),
  ('288da004-613a-5d73-86d0-27ae4433cb08', 'f81edada-1d30-5331-b868-29a1242df97a', 'C', 'Faecal calprotectin', false, 2),
  ('44f034bc-1b0d-5522-a1a1-2ac3c5971d64', 'f81edada-1d30-5331-b868-29a1242df97a', 'D', 'Bone marrow biopsy', false, 3),
  ('55fe553f-c97d-57c3-8d18-f255d63077d5', 'f81edada-1d30-5331-b868-29a1242df97a', 'E', 'Haemoglobin electrophoresis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d1b6752a-805f-51ab-bdf1-a7cf5d12396a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 34 year old woman develops septic shock from a perforated appendix. On the second day she is oozing blood from her cannula sites and has new petechiae. Her platelets are 38 x 10^9/L, PT and APTT are both prolonged, fibrinogen is 0.8 g/L and D-dimer is markedly raised. What is the SINGLE most likely diagnosis?', 'DIC causes widespread activation of coagulation, which uses up platelets and clotting factors. It leads to low platelets, prolonged PT and APTT, low fibrinogen and a raised D-dimer, with bleeding and thrombosis together. It is always secondary, here to sepsis. Treatment is of the underlying cause, with supportive blood products (platelets, FFP, cryoprecipitate) for bleeding. ITP has normal clotting.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('04b079ea-8e37-52aa-8551-d58193018f77', 'd1b6752a-805f-51ab-bdf1-a7cf5d12396a', 'A', 'Vitamin K deficiency', false, 0),
  ('7ccdfca3-3878-5494-a226-9924a0d52182', 'd1b6752a-805f-51ab-bdf1-a7cf5d12396a', 'B', 'Heparin-induced thrombocytopenia', false, 1),
  ('b4faac8e-d98b-5e81-b747-7d05f5bacfbd', 'd1b6752a-805f-51ab-bdf1-a7cf5d12396a', 'C', 'Disseminated intravascular coagulation', true, 2),
  ('7b9ef4da-d2ed-5bb3-b59c-97616ef97d7a', 'd1b6752a-805f-51ab-bdf1-a7cf5d12396a', 'D', 'Immune thrombocytopenic purpura', false, 3),
  ('4add8c12-01a3-5ea4-9ece-a701962f7ae4', 'd1b6752a-805f-51ab-bdf1-a7cf5d12396a', 'E', 'Thrombotic thrombocytopenic purpura', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b60d4ad9-2a64-5d56-8b7b-b465eef5456e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 4 year old boy has a petechial rash and bruising on his legs, which appeared 2 weeks after a viral illness. He is otherwise well with no hepatosplenomegaly or lymphadenopathy. His platelets are 18 x 10^9/L. Haemoglobin, white cell count and blood film are otherwise normal. He has no mucosal bleeding. What is the SINGLE most appropriate management?', 'Isolated thrombocytopenia after a viral illness in an otherwise well child, with a normal film, is immune thrombocytopenic purpura. Most cases in children resolve on their own within 3-6 months. Management is usually observation with advice to avoid trauma and NSAIDs or aspirin. Treatment (steroids or IVIG) is for significant bleeding. A bone marrow biopsy is needed only if there are atypical features suggesting leukaemia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('533f6ec4-73df-5350-8ef4-51693e5d2ba0', 'b60d4ad9-2a64-5d56-8b7b-b465eef5456e', 'A', 'Platelet transfusion', false, 0),
  ('50f837f5-e128-52e7-bd4d-47208cb801e1', 'b60d4ad9-2a64-5d56-8b7b-b465eef5456e', 'B', 'Bone marrow biopsy in all cases', false, 1),
  ('2c815802-d718-5fa6-95c5-22934e6e1f26', 'b60d4ad9-2a64-5d56-8b7b-b465eef5456e', 'C', 'Observation with advice to avoid contact sports, and follow-up', true, 2),
  ('52cfb2d8-23ee-5106-92c9-1abcc11f753a', 'b60d4ad9-2a64-5d56-8b7b-b465eef5456e', 'D', 'Splenectomy', false, 3),
  ('8627581b-95e8-5999-9903-accf518401df', 'b60d4ad9-2a64-5d56-8b7b-b465eef5456e', 'E', 'Oral aspirin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('80db0753-67af-50cf-9a34-3e151a6a1303', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'An 18 year old man with sickle cell disease presents with severe pain in his back, arms and legs that started after a cold, wet weekend camping. His temperature is 37.6°C, oxygen saturation 97% on air and his chest is clear. What is the SINGLE most appropriate immediate management?', 'This is a vaso-occlusive (painful) crisis. NICE recommends giving analgesia within 30 minutes of arrival, usually a strong opioid such as morphine, and reassessing frequently. He also needs hydration, oxygen if saturations are low, and investigation of any trigger such as infection. Watch for acute chest syndrome (new infiltrate on X-ray, chest pain, fever, hypoxia), which needs urgent senior input and may need exchange transfusion. Hydroxycarbamide reduces the frequency of crises long-term.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3fc1732a-a66d-53e1-a41d-3888620b7963', '80db0753-67af-50cf-9a34-3e151a6a1303', 'A', 'Oral hydroxycarbamide and review in 1 week', false, 0),
  ('3d529a7c-62de-5e45-b61e-6c0716a51bbd', '80db0753-67af-50cf-9a34-3e151a6a1303', 'B', 'IV antibiotics only', false, 1),
  ('7fbffec4-966a-5210-b61e-c33d2c496cd9', '80db0753-67af-50cf-9a34-3e151a6a1303', 'C', 'Urgent exchange transfusion', false, 2),
  ('12fbdca6-4760-5822-9ba3-a5448f140633', '80db0753-67af-50cf-9a34-3e151a6a1303', 'D', 'Rapid analgesia with strong opioids within 30 minutes, plus IV fluids', true, 3),
  ('ea2edcff-6065-5ab0-8276-8461436b6f69', '80db0753-67af-50cf-9a34-3e151a6a1303', 'E', 'Oral paracetamol and discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cbce0f5d-5e6a-5314-a34a-0fd23dc1928a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 62 year old woman with vitiligo and hypothyroidism has tiredness, a sore red tongue and pins and needles in her feet. Her haemoglobin is 92 g/L, MCV 118 fL and serum B12 is low. Her folate is normal. Intrinsic factor antibodies are positive. What is the SINGLE most appropriate treatment?', 'Macrocytic anaemia with low B12 and intrinsic factor antibodies in a woman with other autoimmune conditions is pernicious anaemia. B12 cannot be absorbed from the gut, so treatment is IM hydroxocobalamin. With neurological involvement, it is given on alternate days until there is no further improvement, then every 2 months for life. Folic acid must not be given alone in B12 deficiency, because it can bring on subacute combined degeneration of the cord.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('425cb47c-48ef-50e3-ac33-d84b38deff1b', 'cbce0f5d-5e6a-5314-a34a-0fd23dc1928a', 'A', 'IM hydroxocobalamin, then lifelong maintenance injections', true, 0),
  ('63103169-3072-5ba0-8bae-a237e772d90e', 'cbce0f5d-5e6a-5314-a34a-0fd23dc1928a', 'B', 'Oral cyanocobalamin for 1 month only', false, 1),
  ('4a00a7e8-2766-5846-873a-0b473303ee4f', 'cbce0f5d-5e6a-5314-a34a-0fd23dc1928a', 'C', 'Oral ferrous sulfate', false, 2),
  ('7a741f2e-53bc-59cf-9b01-e812f2c401f9', 'cbce0f5d-5e6a-5314-a34a-0fd23dc1928a', 'D', 'Blood transfusion', false, 3),
  ('61ba6ec5-9d73-5d90-b587-783b9bacccbf', 'cbce0f5d-5e6a-5314-a34a-0fd23dc1928a', 'E', 'Oral folic acid alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('669bc145-ce30-5984-b1c5-4b8224eb761e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 24 year old man has a painless swelling in his neck for 2 months, drenching night sweats, fevers and 8 kg of weight loss. He notices his neck lumps ache after drinking alcohol. Biopsy of a cervical lymph node shows Reed-Sternberg cells. What is the SINGLE most likely diagnosis?', 'Reed-Sternberg cells (large binucleate ''owl''s eye'' cells) are the hallmark of Hodgkin lymphoma, which peaks in young adults and the elderly. B symptoms (fever, night sweats, weight loss over 10% in 6 months) carry a worse prognosis, and pain after alcohol is a rare but classic feature. Staging is with PET-CT (Ann Arbor/Lugano). Treatment is chemotherapy, such as ABVD, with or without radiotherapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cb2f5578-d72b-5f86-9782-7d7f60082af6', '669bc145-ce30-5984-b1c5-4b8224eb761e', 'A', 'Hodgkin lymphoma', true, 0),
  ('8544b6c0-490a-5aad-873d-d530b47390e4', '669bc145-ce30-5984-b1c5-4b8224eb761e', 'B', 'Tuberculous lymphadenitis', false, 1),
  ('3ff783a0-0119-563c-9b3e-84daa0f7b395', '669bc145-ce30-5984-b1c5-4b8224eb761e', 'C', 'Infectious mononucleosis', false, 2),
  ('5471b239-1675-50f5-9f81-08bc0eb55321', '669bc145-ce30-5984-b1c5-4b8224eb761e', 'D', 'Chronic lymphocytic leukaemia', false, 3),
  ('2fef7c6b-6e39-563c-93ac-db993e32fe9c', '669bc145-ce30-5984-b1c5-4b8224eb761e', 'E', 'Non-Hodgkin lymphoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ed2738b9-3082-5a29-a0e4-aed3bfacacaa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 32 year old woman has had fatigue and breathlessness. Her Hb is 95 g/L, MCV 70 fL and ferritin 5 micrograms/L. She has heavy periods. Coeliac serology is negative. What is the SINGLE most appropriate treatment?', 'Iron deficiency anaemia from menorrhagia is treated with oral iron, for example ferrous sulfate 200 mg once daily (alternate-day dosing may improve absorption and tolerability), continued for 3 months after Hb normalises. Hb should rise by about 20 g/L in 3-4 weeks. The cause (here heavy periods) also needs treating. Men and postmenopausal women need GI investigation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e69e2c9c-3446-5ec5-a208-4c1f04b63b8b', 'ed2738b9-3082-5a29-a0e4-aed3bfacacaa', 'A', 'Vitamin B12 injections', false, 0),
  ('02579a27-f900-5438-bfe4-3a0a822ae130', 'ed2738b9-3082-5a29-a0e4-aed3bfacacaa', 'B', 'Blood transfusion', false, 1),
  ('2dd104db-6e7f-56c7-b790-640d25b3fcc7', 'ed2738b9-3082-5a29-a0e4-aed3bfacacaa', 'C', 'Folic acid only', false, 2),
  ('a6a3d9ef-14cf-5f1a-b839-0a800d33ff63', 'ed2738b9-3082-5a29-a0e4-aed3bfacacaa', 'D', 'IV iron as first-line', false, 3),
  ('14ec9834-5939-5fbb-9ec2-5a7b7fbee07c', 'ed2738b9-3082-5a29-a0e4-aed3bfacacaa', 'E', 'Oral ferrous sulfate (or fumarate) daily, with Hb rechecked in 2-4 weeks', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1e3b4ff7-fae7-5e25-b3ee-7595365be3f4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 24 year old man of Greek descent has a mild microcytic anaemia (Hb 118 g/L, MCV 64 fL) with a normal ferritin. His red cell count is high-normal. What is the SINGLE most appropriate investigation?', 'A marked microcytosis that is disproportionate to the mild anaemia, with a normal ferritin and a high red cell count, suggests beta-thalassaemia trait, which is common in Mediterranean, Middle Eastern and Asian people. HbA2 is raised on electrophoresis. It needs no treatment, but iron should not be given unnecessarily. Partner testing is advised before pregnancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f2137b77-699d-506f-828a-f1b2aba8ed7d', '1e3b4ff7-fae7-5e25-b3ee-7595365be3f4', 'A', 'Colonoscopy', false, 0),
  ('e37447af-23b5-5aa0-800d-447a7b6a5c1f', '1e3b4ff7-fae7-5e25-b3ee-7595365be3f4', 'B', 'Bone marrow biopsy', false, 1),
  ('b1250d54-458f-5282-b57b-24db96496fd2', '1e3b4ff7-fae7-5e25-b3ee-7595365be3f4', 'C', 'Iron studies repeated monthly', false, 2),
  ('49fbe6d8-3710-5608-94f9-13dec6d73a9d', '1e3b4ff7-fae7-5e25-b3ee-7595365be3f4', 'D', 'Vitamin B12', false, 3),
  ('b172667f-7db4-54c2-b7e9-84dca95e163f', '1e3b4ff7-fae7-5e25-b3ee-7595365be3f4', 'E', 'Haemoglobin electrophoresis (HbA2 level)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b3fdd44b-cebc-54a8-862c-8d3d524718e9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 7 year old boy has jaundice and dark urine after eating broad beans at a family meal. He is of Mediterranean origin. Blood film shows bite cells and Heinz bodies. What is the SINGLE most likely diagnosis?', 'G6PD deficiency is X-linked recessive and causes episodes of intravascular haemolysis triggered by oxidative stress: fava beans, infections and drugs (primaquine, sulfonamides, nitrofurantoin, quinolones, dapsone). The film shows bite cells and Heinz bodies. The G6PD level should be checked after recovery, because it may be falsely normal during haemolysis. Management is avoiding triggers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ff665314-cb99-5080-8894-351f0f23ea5a', 'b3fdd44b-cebc-54a8-862c-8d3d524718e9', 'A', 'Thalassaemia', false, 0),
  ('69b69f90-f2b2-587f-a1c0-4e3965956025', 'b3fdd44b-cebc-54a8-862c-8d3d524718e9', 'B', 'Hereditary spherocytosis', false, 1),
  ('07e99c37-d759-51a5-a62b-61c03b461fc3', 'b3fdd44b-cebc-54a8-862c-8d3d524718e9', 'C', 'Sickle cell disease', false, 2),
  ('144cbf26-b0cc-54e8-8e79-923433c67363', 'b3fdd44b-cebc-54a8-862c-8d3d524718e9', 'D', 'Autoimmune haemolytic anaemia', false, 3),
  ('49cf1527-97d1-5cc4-b881-a1b2e8e06242', 'b3fdd44b-cebc-54a8-862c-8d3d524718e9', 'E', 'Glucose-6-phosphate dehydrogenase (G6PD) deficiency', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('91c3ff1e-9ece-5caa-8b4f-d4fa64eb4051', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 12 year old girl has had intermittent jaundice and gallstones. Her mother had a splenectomy. She has splenomegaly. Blood film shows spherocytes, the direct antiglobulin test is negative and reticulocytes are raised. What is the SINGLE most likely diagnosis?', 'Hereditary spherocytosis is usually autosomal dominant and caused by red cell membrane defects (spectrin, ankyrin). It causes extravascular haemolysis, splenomegaly, pigment gallstones and DAT-negative spherocytes. Parvovirus B19 can cause an aplastic crisis. Treatment is folic acid, and splenectomy in severe cases, with vaccinations and antibiotic prophylaxis afterwards.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('79885b57-2aa4-5e75-96c3-f1098ea38813', '91c3ff1e-9ece-5caa-8b4f-d4fa64eb4051', 'A', 'Sickle cell disease', false, 0),
  ('74c46b84-6704-579a-97c2-5b8b5d085fcc', '91c3ff1e-9ece-5caa-8b4f-d4fa64eb4051', 'B', 'Hereditary spherocytosis', true, 1),
  ('41366c76-58f2-5554-b7cc-339ae0c5df91', '91c3ff1e-9ece-5caa-8b4f-d4fa64eb4051', 'C', 'Autoimmune haemolytic anaemia', false, 2),
  ('10a9d2f3-e320-5fa6-a80d-a3539dc3d12f', '91c3ff1e-9ece-5caa-8b4f-d4fa64eb4051', 'D', 'G6PD deficiency', false, 3),
  ('918e756d-4771-5fed-86f4-53597f6f018c', '91c3ff1e-9ece-5caa-8b4f-d4fa64eb4051', 'E', 'Beta-thalassaemia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ddd706df-e074-5283-b156-4bb5d65dde89', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 45 year old woman with SLE has fatigue and jaundice. Her Hb is 72 g/L, reticulocytes are raised, bilirubin (unconjugated) and LDH are raised and haptoglobin is low. Blood film shows spherocytes. Which test is MOST useful to confirm the cause?', 'Haemolysis with spherocytes in a patient with an autoimmune disease suggests warm autoimmune haemolytic anaemia (IgG), confirmed by a positive DAT. Causes include SLE, CLL, lymphoma and drugs. First-line treatment is prednisolone. Cold AIHA (IgM) is linked to Mycoplasma, EBV and lymphoproliferative disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('42b26d16-8fdd-5751-8f65-bf6ad6ca65c2', 'ddd706df-e074-5283-b156-4bb5d65dde89', 'A', 'G6PD level', false, 0),
  ('9e02bf1f-f122-5336-814f-806299f9af48', 'ddd706df-e074-5283-b156-4bb5d65dde89', 'B', 'Haemoglobin electrophoresis', false, 1),
  ('48409714-cdbb-5803-9c6e-6a516745760f', 'ddd706df-e074-5283-b156-4bb5d65dde89', 'C', 'Bone marrow biopsy', false, 2),
  ('0ddc0147-6fc9-5e3b-a4fe-d3a15330d7b5', 'ddd706df-e074-5283-b156-4bb5d65dde89', 'D', 'Direct antiglobulin (Coombs) test', true, 3),
  ('791b3e46-f466-559a-a9eb-d99541c9eb6d', 'ddd706df-e074-5283-b156-4bb5d65dde89', 'E', 'Osmotic fragility test', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('81b7d617-f0b6-522c-8ce1-dfd217cd5a64', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 72 year old man has an incidental lymphocytosis of 18 x 10^9/L on routine blood tests. He has small painless lymph nodes and no symptoms. Blood film shows smear (smudge) cells. Immunophenotyping shows CD5+ CD19+ CD23+ B cells. What is the SINGLE most likely diagnosis?', 'CLL is the commonest leukaemia in older adults, often found by chance with lymphocytosis and smear cells. Early asymptomatic disease (Binet A) is monitored (''watch and wait''). Treatment (targeted agents such as BTK inhibitors and venetoclax) is for progressive or symptomatic disease. Complications include infection, AIHA, ITP and Richter transformation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1c32bd28-fa0e-503f-b8a7-ca3ad22fbc88', '81b7d617-f0b6-522c-8ce1-dfd217cd5a64', 'A', 'Chronic myeloid leukaemia', false, 0),
  ('3de46997-09ab-5c69-8d72-ea162aff0ec0', '81b7d617-f0b6-522c-8ce1-dfd217cd5a64', 'B', 'Chronic lymphocytic leukaemia', true, 1),
  ('b7fa9066-3cd3-59a8-a4d8-6363713110ca', '81b7d617-f0b6-522c-8ce1-dfd217cd5a64', 'C', 'Infectious mononucleosis', false, 2),
  ('f324c755-5ae5-5f92-8be8-91cc30bc3a4d', '81b7d617-f0b6-522c-8ce1-dfd217cd5a64', 'D', 'Acute lymphoblastic leukaemia', false, 3),
  ('9dd9fdaf-f5e3-5e75-b45b-820b1d220fe6', '81b7d617-f0b6-522c-8ce1-dfd217cd5a64', 'E', 'Hodgkin lymphoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0f91a161-90f7-55d0-a318-eac58c11671c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 55 year old man has fatigue, early satiety and left upper quadrant discomfort. He has massive splenomegaly. His WCC is 180 x 10^9/L with neutrophils and myelocytes at all stages of maturation, and basophilia. What is the SINGLE most appropriate investigation to confirm the diagnosis?', 'Chronic myeloid leukaemia is a myeloproliferative neoplasm with the Philadelphia chromosome t(9;22), creating the BCR-ABL1 fusion gene. It causes massive splenomegaly and a very high WCC with granulocytes at all stages. Tyrosine kinase inhibitors (imatinib) give excellent long-term control. Untreated, it can progress to blast crisis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('12b83b28-9d42-56ca-9aa1-9fc0358975f4', '0f91a161-90f7-55d0-a318-eac58c11671c', 'A', 'Bone marrow trephine for fibrosis', false, 0),
  ('e5b8869d-df26-511e-b702-d7f5be80d091', '0f91a161-90f7-55d0-a318-eac58c11671c', 'B', 'Serum electrophoresis', false, 1),
  ('05158435-d0c7-551d-9dfc-47b6f74c8609', '0f91a161-90f7-55d0-a318-eac58c11671c', 'C', 'JAK2 mutation', false, 2),
  ('ebaa3c2b-7b7e-56c3-bb7c-d80827308209', '0f91a161-90f7-55d0-a318-eac58c11671c', 'D', 'Testing for the Philadelphia chromosome (BCR-ABL1)', true, 3),
  ('740cab37-4a07-5d32-a862-b402835673f6', '0f91a161-90f7-55d0-a318-eac58c11671c', 'E', 'Lymph node biopsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('df1079fa-ca60-5ff2-9cea-b66c4a68c13b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 65 year old man has had headaches, itching after hot baths and a ruddy complexion. His Hb is 205 g/L and haematocrit 0.60. He has splenomegaly. He does not smoke and his oxygen saturations are normal. What is the SINGLE most appropriate investigation?', 'Polycythaemia vera is a myeloproliferative neoplasm; over 95% have the JAK2 V617F mutation. It causes headaches, aquagenic pruritus, plethora, splenomegaly and thrombosis. Serum EPO is low (secondary polycythaemia has a high EPO). Treatment is venesection (target haematocrit under 0.45), aspirin and, in high-risk patients, hydroxycarbamide.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('74b45f7d-718b-5d21-91c4-2bd1311682e6', 'df1079fa-ca60-5ff2-9cea-b66c4a68c13b', 'A', 'Haemoglobin electrophoresis', false, 0),
  ('69b1c2ad-3a83-57b8-8d32-f87207f0b89a', 'df1079fa-ca60-5ff2-9cea-b66c4a68c13b', 'B', 'Bone marrow aspirate only', false, 1),
  ('8875f10e-5f35-5fdc-9f34-23cbf395c9ac', 'df1079fa-ca60-5ff2-9cea-b66c4a68c13b', 'C', 'Serum erythropoietin as the only test', false, 2),
  ('3dc0b5a2-307a-574b-8f23-a8e43856245e', 'df1079fa-ca60-5ff2-9cea-b66c4a68c13b', 'D', 'Philadelphia chromosome', false, 3),
  ('cfa615ac-07bf-5d23-a227-e32a9695230f', 'df1079fa-ca60-5ff2-9cea-b66c4a68c13b', 'E', 'JAK2 V617F mutation analysis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a16ba3ef-300e-50fc-bed4-1dbd7662a000', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 68 year old woman has fatigue and recurrent infections. Her blood count shows pancytopenia with macrocytosis. Blood film shows dysplastic neutrophils (hypogranular, pseudo-Pelger). B12 and folate are normal. What is the SINGLE most likely diagnosis?', 'MDS is a clonal bone marrow disorder of older people with ineffective haematopoiesis, causing cytopenias, often macrocytosis and dysplastic cells. A bone marrow biopsy confirms it. It can transform to AML. Management ranges from supportive transfusions and growth factors to azacitidine or stem cell transplant.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('206bc6f2-8405-5d46-b0fe-f1bb5a9ae744', 'a16ba3ef-300e-50fc-bed4-1dbd7662a000', 'A', 'Vitamin B12 deficiency', false, 0),
  ('ddbe9a45-66e3-55b0-8fde-11d27c00f8a8', 'a16ba3ef-300e-50fc-bed4-1dbd7662a000', 'B', 'Myelodysplastic syndrome', true, 1),
  ('4c6a374c-01e3-5794-8715-74164cd542e5', 'a16ba3ef-300e-50fc-bed4-1dbd7662a000', 'C', 'Aplastic anaemia', false, 2),
  ('f5bac2bc-6d95-5a4a-b9c1-ae067fb92a19', 'a16ba3ef-300e-50fc-bed4-1dbd7662a000', 'D', 'Hypothyroidism', false, 3),
  ('1d98e6c0-9860-50ef-a746-4f656310664a', 'a16ba3ef-300e-50fc-bed4-1dbd7662a000', 'E', 'Acute myeloid leukaemia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a194a4bc-fbd2-5373-b939-9dc55ee5b355', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 35 year old woman has had fatigue, bruising and gum bleeding for 2 weeks. Her blood count shows Hb 75 g/L, platelets 15 x 10^9/L and WCC 45 x 10^9/L. Blood film shows blasts with Auer rods. What is the SINGLE most likely diagnosis?', 'Auer rods are characteristic of AML. AML is the commonest acute leukaemia in adults and presents with bone marrow failure. Acute promyelocytic leukaemia (t(15;17)) causes DIC and is treated urgently with all-trans retinoic acid. Diagnosis is by bone marrow with cytogenetics. Treatment is intensive chemotherapy and possibly stem cell transplant.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a5b089a8-50aa-5b5b-b2dc-db209b405c7d', 'a194a4bc-fbd2-5373-b939-9dc55ee5b355', 'A', 'Immune thrombocytopenic purpura', false, 0),
  ('79a101c8-a60c-553f-9109-eeb33fc83ceb', 'a194a4bc-fbd2-5373-b939-9dc55ee5b355', 'B', 'Acute lymphoblastic leukaemia', false, 1),
  ('78347a97-0f52-5474-9a73-6820a4a84da5', 'a194a4bc-fbd2-5373-b939-9dc55ee5b355', 'C', 'Aplastic anaemia', false, 2),
  ('a5f22b69-961c-538b-8f48-c0a6d0245da3', 'a194a4bc-fbd2-5373-b939-9dc55ee5b355', 'D', 'Acute myeloid leukaemia', true, 3),
  ('7eca33d0-0b1f-5fbd-98c1-03d0b7c8dd47', 'a194a4bc-fbd2-5373-b939-9dc55ee5b355', 'E', 'Chronic myeloid leukaemia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e30e88ad-ba6a-5f38-bb91-a82e557bb627', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 22 year old woman has heavy periods since menarche, frequent nosebleeds and prolonged bleeding after a tooth extraction. Her platelet count and PT are normal, and her APTT is mildly prolonged. Her mother has similar problems. What is the SINGLE most likely diagnosis?', 'Von Willebrand disease is the commonest inherited bleeding disorder (usually autosomal dominant). It causes mucocutaneous bleeding (menorrhagia, epistaxis, prolonged bleeding after dental work). The APTT may be prolonged because vWF carries factor VIII. Investigations are vWF antigen and activity and factor VIII. Treatment includes desmopressin, tranexamic acid and vWF concentrates.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('26360556-ac85-5ca0-8110-9e633b060887', 'e30e88ad-ba6a-5f38-bb91-a82e557bb627', 'A', 'DIC', false, 0),
  ('155e4ffa-9fdf-53a8-b46d-6707414215d6', 'e30e88ad-ba6a-5f38-bb91-a82e557bb627', 'B', 'Von Willebrand disease', true, 1),
  ('5f3a98b9-f0b2-54a4-a57b-ef1f64d51b8a', 'e30e88ad-ba6a-5f38-bb91-a82e557bb627', 'C', 'Immune thrombocytopenia', false, 2),
  ('6febfd3e-a92d-5c46-ae54-cce8c82e2968', 'e30e88ad-ba6a-5f38-bb91-a82e557bb627', 'D', 'Haemophilia A', false, 3),
  ('d49d3b33-edba-5bbc-8742-3e0749ae5e22', 'e30e88ad-ba6a-5f38-bb91-a82e557bb627', 'E', 'Vitamin K deficiency', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f8a2397a-0b7d-5e7f-8907-803b0568b636', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 3 year old boy has a large, painful, swollen knee after a minor fall, and bleeding after circumcision as a baby. His platelet count and PT are normal; APTT is prolonged. His maternal uncle had a similar bleeding problem. What is the SINGLE most likely diagnosis?', 'Haemophilia A is X-linked recessive (factor VIII deficiency) and causes deep bleeding into joints (haemarthroses) and muscles, with an isolated prolonged APTT. Haemophilia B is factor IX deficiency. Treatment is recombinant factor VIII replacement (or emicizumab prophylaxis). NSAIDs and IM injections should be avoided. Female carriers may have low factor levels.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('71a75623-f9a0-5de1-9588-b743e0cade4d', 'f8a2397a-0b7d-5e7f-8907-803b0568b636', 'A', 'Immune thrombocytopenia', false, 0),
  ('f743a56d-d2e2-5248-ba30-8bcac839d883', 'f8a2397a-0b7d-5e7f-8907-803b0568b636', 'B', 'Haemophilia A (factor VIII deficiency)', true, 1),
  ('a91aaa30-c27d-5662-81d9-82eb65243858', 'f8a2397a-0b7d-5e7f-8907-803b0568b636', 'C', 'Henoch-Schönlein purpura', false, 2),
  ('ebfebb7b-936c-551f-8630-cfce610230ea', 'f8a2397a-0b7d-5e7f-8907-803b0568b636', 'D', 'Vitamin K deficiency', false, 3),
  ('2c36a508-e739-5112-993e-55e99b15de9f', 'f8a2397a-0b7d-5e7f-8907-803b0568b636', 'E', 'Von Willebrand disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3b885734-03e2-5360-9a8c-8660da5647fc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 40 year old woman develops fever, confusion, petechiae and dark urine. Her platelets are 18 x 10^9/L, Hb 76 g/L with schistocytes on film, LDH is high and creatinine is mildly raised. Her clotting is normal. What is the SINGLE most appropriate urgent treatment?', 'Thrombotic thrombocytopenic purpura (from ADAMTS13 deficiency) causes microangiopathic haemolytic anaemia, thrombocytopenia, neurological symptoms, fever and kidney involvement, with normal clotting (unlike DIC). It is a haematological emergency. Urgent plasma exchange, steroids, caplacizumab and rituximab are used. Platelet transfusion is avoided because it may worsen thrombosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('790d69a1-5ad0-5f6e-92ea-10af5c03b40b', '3b885734-03e2-5360-9a8c-8660da5647fc', 'A', 'Splenectomy', false, 0),
  ('2cea2571-1593-5a7d-873b-7ebc0cdfcef1', '3b885734-03e2-5360-9a8c-8660da5647fc', 'B', 'Plasma exchange', true, 1),
  ('b777fe68-a696-55c1-a180-400e44f90883', '3b885734-03e2-5360-9a8c-8660da5647fc', 'C', 'IV heparin', false, 2),
  ('6712117f-0b57-5e2e-8aa2-63fc4ff7954b', '3b885734-03e2-5360-9a8c-8660da5647fc', 'D', 'Platelet transfusion', false, 3),
  ('65eef61f-4cc9-5494-be2f-eed39cd2cdff', '3b885734-03e2-5360-9a8c-8660da5647fc', 'E', 'Oral prednisolone only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('79ed0a3e-ddc6-5fdd-979d-45eef5b5356d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 64 year old man had a knee replacement 7 days ago and has been on prophylactic heparin. His platelet count has fallen from 260 to 95 x 10^9/L and he has a new DVT. What is the SINGLE most appropriate management?', 'Heparin-induced thrombocytopenia (type II) is an immune reaction (antibodies to the PF4-heparin complex) usually 5-10 days after starting heparin. It causes a fall in platelets of more than 50% and paradoxical thrombosis. The 4Ts score assesses probability. All heparin must be stopped and a non-heparin anticoagulant started. Warfarin should not be started until platelets recover.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('10865f0f-9811-544a-a2d5-0eee54520b0f', '79ed0a3e-ddc6-5fdd-979d-45eef5b5356d', 'A', 'Switch to LMWH', false, 0),
  ('509ded82-1425-59a4-8103-16369d1379fd', '79ed0a3e-ddc6-5fdd-979d-45eef5b5356d', 'B', 'Stop all heparin and start a non-heparin anticoagulant (e.g. argatroban or fondaparinux)', true, 1),
  ('4a212ce2-475a-53bc-9426-d42da4fb2d22', '79ed0a3e-ddc6-5fdd-979d-45eef5b5356d', 'C', 'Start warfarin alone immediately', false, 2),
  ('fa872f27-b18c-53d7-b4cd-005c15ac7fb9', '79ed0a3e-ddc6-5fdd-979d-45eef5b5356d', 'D', 'Increase the heparin dose', false, 3),
  ('eb66d689-fa93-55db-ba13-a865a84844e9', '79ed0a3e-ddc6-5fdd-979d-45eef5b5356d', 'E', 'Platelet transfusion', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('42a6a727-05d1-5239-812c-bbd2dfb95075', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 70 year old man has fatigue, bone pain and recurrent infections. His serum protein electrophoresis shows a monoclonal IgG paraprotein of 45 g/L. Calcium is 2.9 mmol/L, creatinine raised and Hb 92 g/L. Skeletal survey shows lytic lesions. What is the SINGLE most appropriate confirmatory investigation?', 'Multiple myeloma is diagnosed by clonal plasma cells of 10% or more in the bone marrow plus a myeloma-defining event (CRAB features or biomarkers). Serum free light chains and urine Bence Jones protein are also tested. Whole-body MRI or low-dose CT has replaced the skeletal survey. Treatment includes novel agents, autologous stem cell transplant and bisphosphonates.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9226bd0e-892c-50e3-8467-a23e744f3e78', '42a6a727-05d1-5239-812c-bbd2dfb95075', 'A', 'Liver biopsy', false, 0),
  ('9047a326-f85a-5659-8187-a3e3b91d7b94', '42a6a727-05d1-5239-812c-bbd2dfb95075', 'B', 'Lymph node biopsy', false, 1),
  ('8134628a-e802-5812-8e15-84545844992a', '42a6a727-05d1-5239-812c-bbd2dfb95075', 'C', 'Upper GI endoscopy', false, 2),
  ('a2c03715-32af-52cc-9c8b-0ca93b47a38d', '42a6a727-05d1-5239-812c-bbd2dfb95075', 'D', 'Bone marrow aspirate and trephine biopsy', true, 3),
  ('cbbff9ed-2bef-58dc-a664-01841ff0d630', '42a6a727-05d1-5239-812c-bbd2dfb95075', 'E', 'Coeliac serology', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d7d8fce3-1a80-5662-bde2-c38309344e85', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 60 year old man has an incidental IgG paraprotein of 8 g/L. He has normal calcium, renal function and Hb, and no bone lesions. His bone marrow plasma cells are 5%. What is the SINGLE most likely diagnosis?', 'MGUS is a paraprotein under 30 g/L, bone marrow plasma cells under 10% and no end-organ damage (CRAB). It progresses to myeloma or a related disorder at about 1% a year, so it needs long-term monitoring of the paraprotein and blood tests. No treatment is needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8eef0e0c-0cde-5a5a-a70d-dabd3ab64532', 'd7d8fce3-1a80-5662-bde2-c38309344e85', 'A', 'Smouldering myeloma', false, 0),
  ('1813e423-b651-5f05-8cfc-1056691682bd', 'd7d8fce3-1a80-5662-bde2-c38309344e85', 'B', 'Monoclonal gammopathy of undetermined significance (MGUS)', true, 1),
  ('5daac2d3-931e-5ab0-af35-9cf5456d57b3', 'd7d8fce3-1a80-5662-bde2-c38309344e85', 'C', 'Waldenström macroglobulinaemia', false, 2),
  ('8a52e125-250b-5f90-b9ad-b4782d01a381', 'd7d8fce3-1a80-5662-bde2-c38309344e85', 'D', 'Amyloidosis', false, 3),
  ('6d725960-149e-5e27-b7d0-4d7eb032f2fe', 'd7d8fce3-1a80-5662-bde2-c38309344e85', 'E', 'Multiple myeloma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5a001b67-b4b8-5a05-a12d-20a2f5439813', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 30 year old woman has had progressive fatigue, recurrent infections and easy bruising. Her blood count shows Hb 70 g/L, WCC 1.2 x 10^9/L, neutrophils 0.3 x 10^9/L and platelets 12 x 10^9/L. Reticulocytes are low. Bone marrow biopsy shows a hypocellular marrow replaced by fat, with no abnormal cells. What is the SINGLE most likely diagnosis?', 'Aplastic anaemia is bone marrow failure with pancytopenia and a hypocellular (fatty) marrow, without infiltration. Causes include idiopathic autoimmune disease, drugs (chloramphenicol, carbamazepine), viruses (hepatitis) and radiation. Treatment is supportive (transfusions, antibiotics), immunosuppression (ATG and ciclosporin) or stem cell transplantation in younger patients.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('598e7314-f99f-5cef-84fb-c1a3fcb8dfcb', '5a001b67-b4b8-5a05-a12d-20a2f5439813', 'A', 'Hypersplenism', false, 0),
  ('638a0996-ff1b-55cc-870e-11164ee45711', '5a001b67-b4b8-5a05-a12d-20a2f5439813', 'B', 'Aplastic anaemia', true, 1),
  ('a57ed540-a6cc-5a2c-9179-b4af8bacda72', '5a001b67-b4b8-5a05-a12d-20a2f5439813', 'C', 'Acute leukaemia', false, 2),
  ('aa3e5a1c-a37b-5547-b18e-04482a7031c8', '5a001b67-b4b8-5a05-a12d-20a2f5439813', 'D', 'Vitamin B12 deficiency', false, 3),
  ('35091821-2372-597a-a369-1480e36e9bd0', '5a001b67-b4b8-5a05-a12d-20a2f5439813', 'E', 'Myelodysplasia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cd23f449-b590-5720-b657-9fab564b6ac7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 72 year old man has had a single episode of painless lymphadenopathy, night sweats and weight loss. A lymph node biopsy shows diffuse large B-cell lymphoma. What is the SINGLE most appropriate first-line treatment?', 'Diffuse large B-cell lymphoma is the commonest aggressive non-Hodgkin lymphoma. Standard first-line treatment is R-CHOP (rituximab, cyclophosphamide, doxorubicin, vincristine, prednisolone), often curative. Staging is with PET-CT. Follicular lymphoma is indolent and often managed with watch and wait. ABVD is used for Hodgkin lymphoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('650713ad-db2d-59d8-82dd-f887e91f536e', 'cd23f449-b590-5720-b657-9fab564b6ac7', 'A', 'ABVD', false, 0),
  ('24fd337f-1c99-5e88-a45f-a1998c935afb', 'cd23f449-b590-5720-b657-9fab564b6ac7', 'B', 'R-CHOP chemoimmunotherapy', true, 1),
  ('b70cfa55-fc23-5ad7-8ebc-a54d1c2c6b41', 'cd23f449-b590-5720-b657-9fab564b6ac7', 'C', 'Imatinib', false, 2),
  ('e29f4035-6b68-5200-960d-9ebb979c555c', 'cd23f449-b590-5720-b657-9fab564b6ac7', 'D', 'Watch and wait', false, 3),
  ('e43004ae-029c-5a9a-b668-95d86f6ecca7', 'cd23f449-b590-5720-b657-9fab564b6ac7', 'E', 'Radiotherapy alone for disseminated disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8c00172e-2629-545a-a14c-a18d2d028f86', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 54 year old man has received 4 units of blood. During the second unit he develops fever, rigors, hypotension, back pain and dark urine within 15 minutes of starting. What is the SINGLE most appropriate immediate action?', 'Fever, rigors, hypotension, back or loin pain and haemoglobinuria early in a transfusion suggest an acute haemolytic transfusion reaction, usually from ABO incompatibility caused by an identification error. Stop the transfusion immediately, give supportive care (fluids, monitoring urine output), recheck identity and send the unit and samples to the lab. It must be reported to SHOT and MHRA (SABRE). A mild febrile reaction can be managed by slowing the transfusion and giving paracetamol.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6c28507c-60c8-55b1-9c5c-b5f4843b8199', '8c00172e-2629-545a-a14c-a18d2d028f86', 'A', 'Stop the transfusion, keep the line open with saline, check the patient and unit identity, and send samples for investigation', true, 0),
  ('40ae3b86-9d9a-55e8-bd07-c51e6664faf9', '8c00172e-2629-545a-a14c-a18d2d028f86', 'B', 'Give paracetamol and continue', false, 1),
  ('f3d9d27e-2a16-51fa-bf6d-9c0fe8f05286', '8c00172e-2629-545a-a14c-a18d2d028f86', 'C', 'Slow the transfusion rate', false, 2),
  ('ca1c8477-02fe-558b-a4cf-90e173ac112a', '8c00172e-2629-545a-a14c-a18d2d028f86', 'D', 'Give IV antihistamine and continue', false, 3),
  ('b36933ac-0113-5e0a-917c-76dc790fab99', '8c00172e-2629-545a-a14c-a18d2d028f86', 'E', 'Finish the unit quickly', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('655f8686-4fb6-58e7-9ceb-1f490cd1d89c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 75 year old woman with heart failure is given a red cell transfusion. Within 2 hours she becomes breathless and hypertensive with raised JVP and bibasal crackles. What is the SINGLE most likely diagnosis?', 'TACO causes acute pulmonary oedema from volume overload, typically in older people with heart or kidney disease. It presents with hypertension and a raised JVP. Management is stopping or slowing the transfusion and giving diuretics, with oxygen. Prevention includes a pre-transfusion risk assessment, single units with review, and prophylactic furosemide in at-risk patients. TRALI causes hypotension with non-cardiogenic oedema.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e91dbbd-c412-583d-a880-d6b15c5402b2', '655f8686-4fb6-58e7-9ceb-1f490cd1d89c', 'A', 'Transfusion-associated circulatory overload (TACO)', true, 0),
  ('519deee3-ee10-584f-9adf-085960bdcb7a', '655f8686-4fb6-58e7-9ceb-1f490cd1d89c', 'B', 'Anaphylaxis', false, 1),
  ('6bf11274-df9d-5e37-80f7-02715eebaf37', '655f8686-4fb6-58e7-9ceb-1f490cd1d89c', 'C', 'Transfusion-related acute lung injury (TRALI)', false, 2),
  ('f8b3ef06-776f-59eb-a727-540dcd338c0f', '655f8686-4fb6-58e7-9ceb-1f490cd1d89c', 'D', 'Febrile non-haemolytic reaction', false, 3),
  ('0a59937f-8e95-50df-a9bf-6879f9b180eb', '655f8686-4fb6-58e7-9ceb-1f490cd1d89c', 'E', 'Haemolytic transfusion reaction', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f69faf97-1f76-5d73-9ae2-222063ce5913', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 2 year old girl with sickle cell disease is brought in pale and lethargic with abdominal distension. Her spleen is massively enlarged and tender. Hb has dropped from 80 to 42 g/L. Reticulocytes are raised. What is the SINGLE most likely diagnosis?', 'Splenic sequestration in young children with sickle cell disease involves rapid pooling of blood in the spleen, causing a sudden fall in Hb, splenomegaly and hypovolaemic shock. It is life-threatening and needs urgent transfusion. An aplastic crisis (parvovirus B19) causes a fall in Hb with low reticulocytes. Parents are taught to feel for the spleen.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8fd35e96-f558-5802-bfc4-be08fc942238', 'f69faf97-1f76-5d73-9ae2-222063ce5913', 'A', 'Acute chest syndrome', false, 0),
  ('bc59034c-6bda-5c78-a021-68e1c16e810f', 'f69faf97-1f76-5d73-9ae2-222063ce5913', 'B', 'Aplastic crisis', false, 1),
  ('b487d1f5-5131-5372-9b31-510bdd557c94', 'f69faf97-1f76-5d73-9ae2-222063ce5913', 'C', 'Acute splenic sequestration crisis', true, 2),
  ('9960fffe-d233-5915-9be5-dad88f4d362e', 'f69faf97-1f76-5d73-9ae2-222063ce5913', 'D', 'Vaso-occlusive crisis', false, 3),
  ('c3f9965f-834e-51fb-bea7-38f4f9096fe9', 'f69faf97-1f76-5d73-9ae2-222063ce5913', 'E', 'Haemolytic crisis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('814b931d-39eb-5bec-8ed3-bbd32816869c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 78 year old man has low back pain for 6 weeks and is seen in his GP surgery There is no radiation of pain. He has no history of trauma. He has not taken any analgesia and takes no regular prescription medication. He was treated for polymyalgia rheumatica 3 years ago. His BMI is 22 kg/m² and his temperature is 37.4 °C. There is bony tenderness over his lumbar spine. Neurological examination is normal. Investigations: Haemoglobin 78 g/L (130–175) ESR 98 mm/hr (<20) Which is the most likely diagnosis?', 'Bone pain with tenderness, anaemia and a very high ESR in an older man suggest multiple myeloma. Investigations include serum and urine protein electrophoresis (paraprotein, Bence Jones protein), serum free light chains, calcium and renal function, then a bone marrow biopsy and whole-body imaging. Features are summarised as CRAB: hyperCalcaemia, Renal failure, Anaemia and Bone lesions.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('308f5c33-c4cc-50bb-a810-4026a675cfe2', '814b931d-39eb-5bec-8ed3-bbd32816869c', 'A', 'Discitis', false, 0),
  ('ccdd35e8-d87c-5147-8d9f-6da698e4ef7e', '814b931d-39eb-5bec-8ed3-bbd32816869c', 'B', 'Mechanical back pain', false, 1),
  ('b8e37189-8a6a-5022-b1a5-d4581091c799', '814b931d-39eb-5bec-8ed3-bbd32816869c', 'C', 'Multiple myeloma', true, 2),
  ('45d55dce-4426-534b-938b-2defd5f7b621', '814b931d-39eb-5bec-8ed3-bbd32816869c', 'D', 'Osteoporotic wedge fracture', false, 3),
  ('ed5ea661-cd6a-52fa-aff8-3126a64825af', '814b931d-39eb-5bec-8ed3-bbd32816869c', 'E', 'Recurrence of polymyalgia rheumatica', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('29a98be1-7ca0-5a91-ba58-6e17bb072241', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 55 year old woman has slowly worsening shortness of breath on exertion for 8 weeks. She has Hashimoto’s thyroiditis and takes levothyroxine. She looks pale. Investigations: Haemoglobin 64 g/L (115–150) Mean cell volume 103 fL (80–96) Thyroid stimulating hormone 1.4 mU/L (0.3–4.2) Which is the most likely haematological diagnosis?', 'Macrocytic anaemia in a woman with autoimmune thyroid disease is most likely pernicious anaemia (autoimmune gastritis with intrinsic factor antibodies), causing B12 deficiency. Investigations are serum B12 and intrinsic factor antibodies. Treatment is IM hydroxocobalamin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e7420784-0396-558c-91cf-3f4d845a97db', '29a98be1-7ca0-5a91-ba58-6e17bb072241', 'A', 'Folate deficiency', false, 0),
  ('c4a6e3c7-5955-553d-88ee-b05047733ff8', '29a98be1-7ca0-5a91-ba58-6e17bb072241', 'B', 'Haemolysis', false, 1),
  ('ad92f5ec-716d-5aa6-bf89-0117ad188f72', '29a98be1-7ca0-5a91-ba58-6e17bb072241', 'C', 'Iron deficiency', false, 2),
  ('5ccdf324-cfd3-553f-99d9-1113ed0feeb6', '29a98be1-7ca0-5a91-ba58-6e17bb072241', 'D', 'Myelodysplasia', false, 3),
  ('8d371135-57d9-55b9-ac66-40c60b8962c6', '29a98be1-7ca0-5a91-ba58-6e17bb072241', 'E', 'Pernicious anaemia', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('de4dcb3f-4d00-5f23-8170-a60bb5b5da00', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 4 year old girl is seen at home by her GP with a high fever, drowsiness and a spreading non-blanching purpuric rash on her legs. An emergency ambulance has been called. She has no known drug allergies. What is the SINGLE most appropriate action while waiting for the ambulance?', 'Suspected meningococcal disease (fever with a non-blanching rash) needs parenteral antibiotics as soon as possible, without delaying transfer. NICE dosing for IM or IV benzylpenicillin in the community is: under 1 year 300 mg, 1-9 years 600 mg, 10 years and over (and adults) 1200 mg. Antibiotics should only be withheld for a history of anaphylaxis to penicillin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('81d6fe5f-d52f-53d2-aa2e-46f21f617213', 'de4dcb3f-4d00-5f23-8170-a60bb5b5da00', 'A', 'IM benzylpenicillin 1200 mg', false, 0),
  ('3daca5d2-f990-5b82-9992-84b6eef06be1', 'de4dcb3f-4d00-5f23-8170-a60bb5b5da00', 'B', 'IM benzylpenicillin 600 mg', true, 1),
  ('818511ba-8294-52eb-b6e3-6069d7f0da51', 'de4dcb3f-4d00-5f23-8170-a60bb5b5da00', 'C', 'No antibiotics until hospital blood cultures are taken', false, 2),
  ('30aad355-4885-5419-bbdc-f56565b3aef8', 'de4dcb3f-4d00-5f23-8170-a60bb5b5da00', 'D', 'IM benzylpenicillin 300 mg', false, 3),
  ('c4aa97e8-ef32-5ac6-8920-1ee3b6acc97a', 'de4dcb3f-4d00-5f23-8170-a60bb5b5da00', 'E', 'Oral amoxicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f9edbe7d-f650-5e47-8387-5fa9d14ffc0f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 36 year old man returned from visiting family in Nigeria 10 days ago. He did not take malaria prophylaxis. He has fever, rigors, headache and muscle aches. He is alert and his observations are stable. A blood film shows Plasmodium falciparum with 1% parasitaemia. He is not vomiting. What is the SINGLE most appropriate treatment?', 'Uncomplicated falciparum malaria (parasitaemia under 2%, no severe features and able to take oral treatment) is treated with an oral artemisinin combination such as artemether-lumefantrine (Riamet). Severe malaria (parasitaemia over 2%, reduced consciousness, acidosis, AKI, severe anaemia or shock) needs IV artesunate. Chloroquine is used for non-falciparum species, with primaquine for P. vivax or ovale to clear liver hypnozoites.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bbf062f6-eb31-50b7-84e0-88d915e197ec', 'f9edbe7d-f650-5e47-8387-5fa9d14ffc0f', 'A', 'Oral chloroquine', false, 0),
  ('50b64141-9a83-5df6-a4a5-f9e486728aa9', 'f9edbe7d-f650-5e47-8387-5fa9d14ffc0f', 'B', 'Oral doxycycline alone', false, 1),
  ('52dd42c6-6bed-57fc-877a-22c1136b0eda', 'f9edbe7d-f650-5e47-8387-5fa9d14ffc0f', 'C', 'Oral artemisinin-based combination therapy (such as artemether-lumefantrine)', true, 2),
  ('1502d5bd-944d-5a43-b532-1202ff91d1a8', 'f9edbe7d-f650-5e47-8387-5fa9d14ffc0f', 'D', 'IV artesunate', false, 3),
  ('fc031ef7-12df-5cab-bc6c-b85f2160d2b1', 'f9edbe7d-f650-5e47-8387-5fa9d14ffc0f', 'E', 'Oral primaquine alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c6cde34c-5a0f-5840-a680-1fa4cd053d33', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 27 year old nurse sustains a deep needlestick injury from a hollow-bore needle used on a patient with known HIV. The patient''s viral load is unknown. The injury happened 1 hour ago and the wound has been washed. What is the SINGLE most appropriate management?', 'Encourage bleeding, wash with soap and water, and report the injury. HIV PEP should be started as soon as possible, ideally within hours and no later than 72 hours, when the source is known HIV positive with a detectable or unknown viral load. A 28-day course is given (for example tenofovir/emtricitabine with raltegravir). HIV testing is done at baseline and at least 45 days after PEP finishes. Hepatitis B and C exposure also needs assessing.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1ffc8638-cc22-58b1-bbf8-301cd5e203c1', 'c6cde34c-5a0f-5840-a680-1fa4cd053d33', 'A', 'HIV test in 3 months only', false, 0),
  ('05c286a9-22bc-581f-a6f6-452ef856b95f', 'c6cde34c-5a0f-5840-a680-1fa4cd053d33', 'B', 'No action needed as the risk is very low', false, 1),
  ('459f625f-d0e2-5cd8-ae64-6c9813d7d057', 'c6cde34c-5a0f-5840-a680-1fa4cd053d33', 'C', 'A single dose of an antiretroviral', false, 2),
  ('18050622-cf88-5961-87c1-aaa0788b3596', 'c6cde34c-5a0f-5840-a680-1fa4cd053d33', 'D', 'Start PEP only if her HIV test at 6 weeks is positive', false, 3),
  ('9f944ab2-14ed-5dcb-b238-051a2dbb3c1a', 'c6cde34c-5a0f-5840-a680-1fa4cd053d33', 'E', 'Start HIV post-exposure prophylaxis as soon as possible (ideally within 72 hours) for 28 days', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d53922c9-c3de-51c9-992c-9dd252093b33', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 30 year old man has a single painless, firm ulcer on his penis with a clean base, which appeared 3 weeks after unprotected sex. He has painless, rubbery inguinal lymphadenopathy. What is the SINGLE most likely causative organism?', 'A painless, indurated ulcer (chancre) with painless lymphadenopathy is primary syphilis. Diagnosis is by dark-ground microscopy, PCR or serology (treponemal EIA, then RPR/VDRL). Treatment is IM benzathine benzylpenicillin. Genital herpes causes multiple painful ulcers. Chancroid (H. ducreyi) causes painful ulcers with painful lymph nodes. LGV causes a transient ulcer followed by large painful nodes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c5da57d0-8851-591a-bcdd-fedf1baeb24c', 'd53922c9-c3de-51c9-992c-9dd252093b33', 'A', 'Haemophilus ducreyi', false, 0),
  ('d0210132-e53a-5ec2-8e3f-4d5fbc9be0ad', 'd53922c9-c3de-51c9-992c-9dd252093b33', 'B', 'Human papillomavirus', false, 1),
  ('e0c2dcf2-8967-5c30-8c44-f6999eed9b66', 'd53922c9-c3de-51c9-992c-9dd252093b33', 'C', 'Herpes simplex virus type 2', false, 2),
  ('4838afdd-a479-5bcd-8f47-c42cf928d55a', 'd53922c9-c3de-51c9-992c-9dd252093b33', 'D', 'Chlamydia trachomatis serovars L1-L3', false, 3),
  ('6df4862a-f688-5916-b88d-1e4dfc14166f', 'd53922c9-c3de-51c9-992c-9dd252093b33', 'E', 'Treponema pallidum', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('10e85766-98c8-5088-a55b-22bc4a036550', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 52 year old man has 3 days of a spreading red, hot, swollen, tender area on his right shin after a gardening injury. He has a temperature of 37.8°C but is otherwise well, with normal observations and no comorbidities. He has no penicillin allergy. What is the SINGLE most appropriate antibiotic?', 'This is Eron class I cellulitis (no systemic toxicity or significant comorbidity), which can be treated at home with oral flucloxacillin for 5-7 days, covering Streptococcus pyogenes and Staphylococcus aureus. Clarithromycin, erythromycin or doxycycline are used in penicillin allergy. Mark the edges of the redness to monitor spread. Admission and IV antibiotics are for Eron class III-IV or rapidly spreading infection.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0cfff108-22fa-5077-a893-f0e746f30fcf', '10e85766-98c8-5088-a55b-22bc4a036550', 'A', 'Oral clarithromycin', false, 0),
  ('3eaf92dd-fc85-501b-9223-1282ef4dd044', '10e85766-98c8-5088-a55b-22bc4a036550', 'B', 'Oral flucloxacillin', true, 1),
  ('a7491c85-5e1c-5531-8b7a-a3461f997b8f', '10e85766-98c8-5088-a55b-22bc4a036550', 'C', 'Topical fusidic acid', false, 2),
  ('1ee4bde3-a761-5979-b920-f2b54198df1f', '10e85766-98c8-5088-a55b-22bc4a036550', 'D', 'IV benzylpenicillin', false, 3),
  ('1ff1f2bd-da28-565e-bdf3-9ac5a5d3b1d7', '10e85766-98c8-5088-a55b-22bc4a036550', 'E', 'Oral ciprofloxacin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4f364714-309c-572a-82aa-6f8a2651d495', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 17 year old girl has 1 week of fever, a severe sore throat with exudative tonsils, fatigue and tender posterior cervical lymph nodes. She has mild splenomegaly. Her GP gave her amoxicillin 2 days ago and she now has a widespread itchy maculopapular rash. What is the SINGLE most likely diagnosis?', 'Fever, exudative pharyngitis, posterior cervical lymphadenopathy and splenomegaly in a teenager suggest glandular fever (EBV). A rash after amoxicillin is classic, and is not a true penicillin allergy. Diagnosis is by a heterophile antibody (Monospot) test, with atypical lymphocytes on the blood film. Management is supportive, and she should avoid contact sports for 4-8 weeks because of the risk of splenic rupture.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('99604675-7eb5-57ea-8e46-8a239d17ce60', '4f364714-309c-572a-82aa-6f8a2651d495', 'A', 'Streptococcal tonsillitis with penicillin allergy', false, 0),
  ('0775e6f9-9ccb-5c39-8c72-d29097f382c3', '4f364714-309c-572a-82aa-6f8a2651d495', 'B', 'Measles', false, 1),
  ('9f0bf525-51c4-5ad5-8d2f-a057ba7b9ea9', '4f364714-309c-572a-82aa-6f8a2651d495', 'C', 'Infectious mononucleosis (Epstein-Barr virus)', true, 2),
  ('ba9058e8-c0f5-571c-888f-045b149dc381', '4f364714-309c-572a-82aa-6f8a2651d495', 'D', 'Acute HIV seroconversion', false, 3),
  ('838d7a0f-589f-5701-ab47-9f0e85fe1939', '4f364714-309c-572a-82aa-6f8a2651d495', 'E', 'Scarlet fever', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('62dc72ff-98b0-5d3e-a877-58bc4fb0c482', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 42 year old man returned from Thailand 5 days ago with a high fever, severe headache, retro-orbital pain, severe myalgia and a rash. His platelets are 60 x 10^9/L and he has a raised haematocrit. Malaria films are negative. What is the SINGLE most likely diagnosis?', 'Dengue (a flavivirus spread by Aedes mosquitoes in tropical areas) causes fever, severe headache, retro-orbital pain, myalgia (''breakbone fever''), rash, thrombocytopenia and leucopenia. Warning signs of severe dengue (plasma leakage, bleeding, organ impairment) need hospital care. Management is supportive, and NSAIDs and aspirin should be avoided. Malaria must always be excluded in a febrile traveller.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5aa101da-30b1-5cb9-82af-082b108bc64c', '62dc72ff-98b0-5d3e-a877-58bc4fb0c482', 'A', 'Dengue fever', true, 0),
  ('820b166e-b1e6-52f1-b211-82aa53488aef', '62dc72ff-98b0-5d3e-a877-58bc4fb0c482', 'B', 'Malaria', false, 1),
  ('ad671d63-ae1c-586d-a03a-4ecd038727cd', '62dc72ff-98b0-5d3e-a877-58bc4fb0c482', 'C', 'Yellow fever', false, 2),
  ('34749ba4-c48a-5a7c-a34d-73d8bc1801aa', '62dc72ff-98b0-5d3e-a877-58bc4fb0c482', 'D', 'Chikungunya', false, 3),
  ('141e546a-2d2a-512c-b971-ac3f127e36ad', '62dc72ff-98b0-5d3e-a877-58bc4fb0c482', 'E', 'Typhoid fever', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('27782cf9-afa1-5d1c-9291-bfcdd8cc2460', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 28 year old man returned from Bangladesh 2 weeks ago. He has had a step-wise rising fever, headache, abdominal pain and constipation. His pulse is 68 beats/minute despite a temperature of 39.5°C. He has faint rose-coloured spots on his trunk. What is the SINGLE most appropriate diagnostic test?', 'Enteric (typhoid) fever (Salmonella typhi or paratyphi) causes a step-wise fever, relative bradycardia, abdominal pain, constipation or diarrhoea, rose spots and hepatosplenomegaly. Blood cultures are the most useful early test. Treatment is guided by local resistance, often ceftriaxone or azithromycin. It is notifiable, and complications include GI perforation and bleeding.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('237d3147-b10b-5c2c-96f9-128e408d5a0e', '27782cf9-afa1-5d1c-9291-bfcdd8cc2460', 'A', 'Stool cultures only', false, 0),
  ('012fcb3b-9606-55c3-9013-22f5b3e12e3b', '27782cf9-afa1-5d1c-9291-bfcdd8cc2460', 'B', 'Blood cultures', true, 1),
  ('3809f35d-5db6-53f7-97b8-608d326f4d0b', '27782cf9-afa1-5d1c-9291-bfcdd8cc2460', 'C', 'Urine culture', false, 2),
  ('1e04ec8d-198c-5158-9937-e4c856f22c1a', '27782cf9-afa1-5d1c-9291-bfcdd8cc2460', 'D', 'Widal test only', false, 3),
  ('64d4db6a-185d-5a15-95ef-92f222d6a4a0', '27782cf9-afa1-5d1c-9291-bfcdd8cc2460', 'E', 'Thick and thin blood films', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7bde978d-48fe-5872-9e15-3b269c09a11a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 35 year old farm worker has had high fever, myalgia and conjunctival suffusion for 6 days, followed by jaundice, AKI and haemoptysis. He swims in a river near the farm, which is infested with rats. What is the SINGLE most likely diagnosis?', 'Leptospirosis is spread through water or soil contaminated by rodent urine (farmers, sewer workers, water sports). It causes fever, myalgia (especially calves) and conjunctival suffusion. Severe disease (Weil''s disease) causes jaundice, AKI and haemorrhage. Treatment is penicillin or doxycycline. It is notifiable.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c83be164-e11f-512d-b608-e5917d592e88', '7bde978d-48fe-5872-9e15-3b269c09a11a', 'A', 'Dengue', false, 0),
  ('faf9f2f9-3fa0-5e0f-9c55-021ecf2c98e7', '7bde978d-48fe-5872-9e15-3b269c09a11a', 'B', 'Leptospirosis (Weil''s disease)', true, 1),
  ('23b3b69e-e548-5943-9d69-f62c8a315942', '7bde978d-48fe-5872-9e15-3b269c09a11a', 'C', 'Hepatitis A', false, 2),
  ('30a4e836-3a9a-5ebc-9696-b344986be4ce', '7bde978d-48fe-5872-9e15-3b269c09a11a', 'D', 'Malaria', false, 3),
  ('9061c024-3ae3-5044-999f-f8153e77cfea', '7bde978d-48fe-5872-9e15-3b269c09a11a', 'E', 'Legionnaires'' disease', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2effccad-5230-5e66-a9a0-4af23f40d9cf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 30 year old man has had fever, sore throat, a maculopapular rash, mouth ulcers and generalised lymphadenopathy for 1 week. He had condomless sex with a new partner 3 weeks ago. EBV serology is negative. What is the SINGLE most appropriate test?', 'Primary HIV infection (seroconversion illness) occurs 2-6 weeks after exposure, with a glandular fever-like illness, rash, mouth ulcers and lymphadenopathy. A fourth-generation test (p24 antigen plus antibody) detects most infections from 4 weeks. A negative result soon after exposure should be repeated, and an HIV RNA PCR may help. Early diagnosis allows treatment and prevents onward transmission.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ac252881-5375-50c6-abeb-868031d459a9', '2effccad-5230-5e66-a9a0-4af23f40d9cf', 'A', 'HIV antibody test only, repeated in 1 year', false, 0),
  ('d85d043b-79d4-55c6-8a95-a2999682b9cc', '2effccad-5230-5e66-a9a0-4af23f40d9cf', 'B', 'Fourth-generation HIV test (p24 antigen and antibody)', true, 1),
  ('5f816978-be16-5742-aaac-9bd65ba3e85d', '2effccad-5230-5e66-a9a0-4af23f40d9cf', 'C', 'CD4 count only', false, 2),
  ('6be276f3-bb33-594d-896d-82a164fe292f', '2effccad-5230-5e66-a9a0-4af23f40d9cf', 'D', 'Throat swab culture', false, 3),
  ('bdb7dffd-f978-5cea-92c2-bc0f89c9707a', '2effccad-5230-5e66-a9a0-4af23f40d9cf', 'E', 'Monospot repeat', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('389f5e7a-81df-5606-925b-9f76fd355c62', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 42 year old woman is HIV positive with a CD4 count of 40 cells/mm3. She has had a headache, fever and confusion for 2 weeks. India ink staining of CSF shows encapsulated yeasts. What is the SINGLE most appropriate treatment?', 'Cryptococcal meningitis is an opportunistic infection in advanced HIV (CD4 under 100). India ink stain or cryptococcal antigen confirms it. Treatment is induction with amphotericin B plus flucytosine, then fluconazole consolidation and maintenance, with management of raised intracranial pressure (therapeutic LPs). ART is started after a delay to reduce the risk of immune reconstitution inflammatory syndrome.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('caa2b784-4e51-530b-9831-f54ef12e8186', '389f5e7a-81df-5606-925b-9f76fd355c62', 'A', 'IV ceftriaxone', false, 0),
  ('3de047e4-67a6-542c-84ac-35bef1fa712a', '389f5e7a-81df-5606-925b-9f76fd355c62', 'B', 'Co-trimoxazole', false, 1),
  ('e4490b1b-a14c-537a-a257-ab70840b6a68', '389f5e7a-81df-5606-925b-9f76fd355c62', 'C', 'Pyrimethamine and sulfadiazine', false, 2),
  ('d708db60-a176-56e8-9547-ed0064aba802', '389f5e7a-81df-5606-925b-9f76fd355c62', 'D', 'IV amphotericin B plus flucytosine, then fluconazole', true, 3),
  ('fdd16184-3ad1-5490-a361-42ee3f87ed21', '389f5e7a-81df-5606-925b-9f76fd355c62', 'E', 'Oral aciclovir', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('840aeaff-3487-5c0e-8745-ffd127f4bbe1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 38 year old man with HIV and a CD4 count of 60 cells/mm3 has a headache, fever, seizures and focal weakness. CT head shows multiple ring-enhancing lesions in the basal ganglia. Toxoplasma serology IgG is positive. What is the SINGLE most likely diagnosis?', 'Toxoplasmosis causes multiple ring-enhancing lesions in people with a CD4 count under 100. Treatment is pyrimethamine plus sulfadiazine (with folinic acid). A response within 2 weeks supports the diagnosis. Primary CNS lymphoma usually causes a single lesion and is EBV-associated. Co-trimoxazole prophylaxis prevents toxoplasmosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('34546187-8dea-5e2d-9577-04303ca0dda2', '840aeaff-3487-5c0e-8745-ffd127f4bbe1', 'A', 'Cryptococcal meningitis', false, 0),
  ('f19c21bf-79d8-52bf-ba9b-b896e38c5182', '840aeaff-3487-5c0e-8745-ffd127f4bbe1', 'B', 'Primary CNS lymphoma', false, 1),
  ('0d8bb69a-7eac-591c-9efb-07b9ad040be4', '840aeaff-3487-5c0e-8745-ffd127f4bbe1', 'C', 'Cerebral toxoplasmosis', true, 2),
  ('9c33dfde-2aa2-5ff8-ba98-abeb121c6885', '840aeaff-3487-5c0e-8745-ffd127f4bbe1', 'D', 'Progressive multifocal leukoencephalopathy', false, 3),
  ('8efa002e-4147-5e57-a13b-8cbe8ec91170', '840aeaff-3487-5c0e-8745-ffd127f4bbe1', 'E', 'Tuberculous meningitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5563f7e6-b27f-56e6-a001-ff77c1f2e751', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 72 year old man had a cardiac transplant and is on immunosuppression. He has had fever and diarrhoea, and colonoscopy shows ulcers with inclusion bodies resembling ''owl''s eyes''. What is the SINGLE most likely organism?', 'CMV causes significant disease in immunocompromised patients (transplant recipients, advanced HIV): colitis, oesophagitis, pneumonitis, retinitis and hepatitis. Histology shows ''owl''s eye'' intranuclear inclusions. Treatment is ganciclovir or valganciclovir. Congenital CMV is the commonest congenital infection and a leading cause of sensorineural hearing loss.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9a7bd1c5-ecf3-59da-9f87-d1c6c07a5810', '5563f7e6-b27f-56e6-a001-ff77c1f2e751', 'A', 'Giardia', false, 0),
  ('c7ab41be-fb17-5675-8b9c-0994e3068e9c', '5563f7e6-b27f-56e6-a001-ff77c1f2e751', 'B', 'Herpes simplex virus', false, 1),
  ('8aa003b4-69ce-53c7-b11f-a723c3bddd22', '5563f7e6-b27f-56e6-a001-ff77c1f2e751', 'C', 'Clostridioides difficile', false, 2),
  ('76129ac4-03af-516a-bc14-f69c143afd52', '5563f7e6-b27f-56e6-a001-ff77c1f2e751', 'D', 'Cytomegalovirus', true, 3),
  ('9e394317-1c66-5594-8c4f-010e33ee01e6', '5563f7e6-b27f-56e6-a001-ff77c1f2e751', 'E', 'Campylobacter', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('23311175-2c7f-5f5e-b807-dafd88981dc3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 75 year old woman has a painful vesicular rash in a band on the right side of her chest that stops at the midline. It started 2 days ago after a tingling pain. What is the SINGLE most appropriate treatment?', 'Shingles is reactivation of VZV in a dermatome. NICE recommends oral antivirals within 72 hours for people aged 50 and over, and for those who are immunocompromised, have non-truncal involvement, moderate-severe pain or rash, or eye involvement. Antivirals reduce acute pain and may reduce post-herpetic neuralgia. The shingles vaccine (Shingrix) is offered to people from age 65 (and to immunosuppressed people).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
