  ('0037dff4-5149-545b-9e0c-429f83a6bf52', '23311175-2c7f-5f5e-b807-dafd88981dc3', 'A', 'Topical steroid', false, 0),
  ('d8292eef-58b7-542d-8112-c7113af286d4', '23311175-2c7f-5f5e-b807-dafd88981dc3', 'B', 'Oral antibiotics', false, 1),
  ('5e0e0e08-aa05-5774-965e-df5e539e3921', '23311175-2c7f-5f5e-b807-dafd88981dc3', 'C', 'IV aciclovir for all', false, 2),
  ('7986b5ae-62d7-5b67-95cd-0432446a6452', '23311175-2c7f-5f5e-b807-dafd88981dc3', 'D', 'Oral aciclovir (or valaciclovir) within 72 hours of rash onset', true, 3),
  ('b62bf4ba-e7b7-5124-9870-41f4f799df80', '23311175-2c7f-5f5e-b807-dafd88981dc3', 'E', 'No treatment for anyone over 50', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e8e3c32e-165b-557b-b7b5-23ff51055214', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 60 year old man had shingles 4 months ago on his left chest. He still has burning, shooting pain and allodynia in the same area. What is the SINGLE most appropriate first-line treatment?', 'Post-herpetic neuralgia is neuropathic pain persisting at least 3 months after shingles, and is more common in older people. NICE recommends a choice of amitriptyline, duloxetine, gabapentin or pregabalin for neuropathic pain, switching if one is ineffective. Topical lidocaine plasters or capsaicin cream can help localised pain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
