  ('99cc4ede-b169-55be-888a-eaf10d117f89', 'e8e3c32e-165b-557b-b7b5-23ff51055214', 'A', 'Strong opioids first-line', false, 0),
  ('2e5b4e4e-28a9-5774-b23f-b54b59a8212a', 'e8e3c32e-165b-557b-b7b5-23ff51055214', 'B', 'Amitriptyline, duloxetine, gabapentin or pregabalin', true, 1),
  ('101a0cc9-cee4-5b5e-b00d-33675de33a2a', 'e8e3c32e-165b-557b-b7b5-23ff51055214', 'C', 'Oral aciclovir', false, 2),
  ('9b0a8eaa-be8f-564f-bf19-88d8991fde6b', 'e8e3c32e-165b-557b-b7b5-23ff51055214', 'D', 'Oral prednisolone', false, 3),
