insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('13c79ef8-56e6-586b-b9af-1e9e93ebfeb2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 24 year old woman has had fever, headache, confusion and odd behaviour for 3 days, and had a seizure. MRI shows temporal lobe changes. CSF shows a lymphocytosis with raised protein and normal glucose. What is the SINGLE most appropriate immediate treatment?', 'Herpes simplex encephalitis (usually HSV-1) affects the temporal lobes, causing fever, confusion, behavioural change, seizures and focal signs. CSF HSV PCR confirms it. IV aciclovir should be started immediately on suspicion, without waiting for results, because untreated mortality is very high. Autoimmune encephalitis (such as anti-NMDA receptor) is a differential.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
