  ('8447d80f-b97f-5f8b-83d9-97843a0b61a3', '13c79ef8-56e6-586b-b9af-1e9e93ebfeb2', 'A', 'IV amphotericin', false, 0),
  ('433dfe40-f3db-56d7-9724-1513abf60af1', '13c79ef8-56e6-586b-b9af-1e9e93ebfeb2', 'B', 'Oral aciclovir', false, 1),
  ('79c20b71-1e0b-569d-a9ae-0af657a76060', '13c79ef8-56e6-586b-b9af-1e9e93ebfeb2', 'C', 'IV ceftriaxone alone', false, 2),
