insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e8fa61f2-8bf5-58f0-93f7-2a5852551752', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 21 year old student has fever, headache and a non-blanching purpuric rash. He is drowsy with cold peripheries and a BP of 82/50 mmHg. What is the SINGLE most appropriate immediate management?', 'Meningococcal septicaemia (Neisseria meningitidis) can progress within hours. Give IV ceftriaxone immediately, with fluid resuscitation and early critical care involvement. An LP is contraindicated in septic shock, coagulopathy or a widespread purpuric rash. Close contacts get ciprofloxacin prophylaxis. It is notifiable, and vaccination (MenB, MenACWY) is part of the UK schedule.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2a07d44b-0831-5c66-bbbf-3d61c82cd511', 'e8fa61f2-8bf5-58f0-93f7-2a5852551752', 'A', 'Oral penicillin', false, 0),
  ('53e40e0e-0e73-5ee2-9e77-124f75f4d3d1', 'e8fa61f2-8bf5-58f0-93f7-2a5852551752', 'B', 'Lumbar puncture first', false, 1),
  ('215280c2-0e14-541f-a42b-632b15678c45', 'e8fa61f2-8bf5-58f0-93f7-2a5852551752', 'C', 'IV ceftriaxone (or cefotaxime) immediately and fluid resuscitation, with senior/ICU input', true, 2),
  ('0f846e8f-91de-5683-aad9-91fb33f98758', 'e8fa61f2-8bf5-58f0-93f7-2a5852551752', 'D', 'CT head before antibiotics', false, 3),
  ('daee7396-d750-5dcf-96fc-50043202ca8f', 'e8fa61f2-8bf5-58f0-93f7-2a5852551752', 'E', 'Wait for blood cultures to grow', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('987a68a2-a2db-5586-b63f-95e7700e5e51', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 30 year old woman has had fever, malaise and a red circular rash expanding over 10 days with central clearing on her thigh after a camping trip in the New Forest. She has no other symptoms. What is the SINGLE most appropriate management?', 'Erythema migrans (an expanding red rash with or without central clearing, usually 5 cm or more) after a tick bite is diagnostic of Lyme disease (Borrelia burgdorferi), and treatment should start without testing. NICE recommends doxycycline for 21 days (amoxicillin in pregnancy). Untreated Lyme disease can cause facial palsy, carditis (heart block), meningitis and arthritis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f57f36d6-064f-5348-8219-63458617f9fe', '987a68a2-a2db-5586-b63f-95e7700e5e51', 'A', 'IV ceftriaxone', false, 0),
  ('0382b6cf-a344-58ee-8071-d478a1e57d7f', '987a68a2-a2db-5586-b63f-95e7700e5e51', 'B', 'Oral doxycycline (diagnosis is clinical; no serology needed)', true, 1),
  ('d9eaa4b1-202a-58ce-9210-2ee60e52853f', '987a68a2-a2db-5586-b63f-95e7700e5e51', 'C', 'No treatment', false, 2),
  ('cb3dc783-4ee3-5083-b5d5-ff0271b0f81d', '987a68a2-a2db-5586-b63f-95e7700e5e51', 'D', 'Wait for Lyme serology before treatment', false, 3),
  ('ff4a6ff2-7046-5052-948f-30ba1f19d2b7', '987a68a2-a2db-5586-b63f-95e7700e5e51', 'E', 'Oral flucloxacillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5e32ffaf-cca7-5450-aa8f-4af6a6f4a8ec', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 55 year old man has had fever and pain in his right upper quadrant for 2 weeks. He returned from India 3 months ago, where he had bloody diarrhoea. Ultrasound shows a single large cyst in the right lobe of the liver. Amoebic serology is positive. What is the SINGLE most appropriate treatment?', 'An amoebic liver abscess (Entamoeba histolytica) can follow amoebic dysentery, sometimes months later. Treatment is metronidazole (or tinidazole), followed by a luminal agent to clear intestinal cysts. Aspiration is reserved for large abscesses at risk of rupture or failure to respond. Hydatid cysts (Echinococcus) are a differential, and aspiration is avoided because of the risk of anaphylaxis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
