  ('d9382d77-2be5-5685-aa35-a595acca37cc', '5e32ffaf-cca7-5450-aa8f-4af6a6f4a8ec', 'A', 'Surgical resection', false, 0),
  ('bafa4b38-f2be-5e4c-b716-66dd02f7ed01', '5e32ffaf-cca7-5450-aa8f-4af6a6f4a8ec', 'B', 'Metronidazole followed by a luminal agent (e.g. paromomycin or diloxanide)', true, 1),
  ('a592dad7-7f48-5113-93d9-2abc3eeee9ed', '5e32ffaf-cca7-5450-aa8f-4af6a6f4a8ec', 'C', 'Ceftriaxone only', false, 2),
